            UserDefaults.standard.set(selectedCharacter.rawValue, forKey: "kon_stage_selected_char")
        }
    }
    @Published var enableBanter: Bool = true
    
    // GPS & HUD Speedometer State
    @Published var recentDestinations: [RecentDestinationRecord] = []
    private let recentDestDefaultsKey = "HTTRecentDestinationsV1"

    func loadAndPruneRecentDestinations() {
        let now = Date().timeIntervalSince1970
        let sevenDays: TimeInterval = 7.0 * 86400.0
        if let data = UserDefaults.standard.data(forKey: recentDestDefaultsKey),
           let decoded = try? JSONDecoder().decode([RecentDestinationRecord].self, from: data) {
            let valid = decoded.filter { (now - $0.timestamp) <= sevenDays }
            recentDestinations = valid
            if valid.count != decoded.count, let enc = try? JSONEncoder().encode(valid) {
                UserDefaults.standard.set(enc, forKey: recentDestDefaultsKey)
            }
        }
    }

    func deleteRecentDestination(id: String) {
        let updated = recentDestinations.filter { $0.id != id }
        recentDestinations = updated
        if let enc = try? JSONEncoder().encode(updated) {
            UserDefaults.standard.set(enc, forKey: recentDestDefaultsKey)
        }
    }

    func recordRecentDestination(name: String, address: String, coord: CLLocationCoordinate2D) {
        let cleanName = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleanName.isEmpty, cleanName != "目的地", cleanName != "正在获取地点..." else { return }
        let now = Date().timeIntervalSince1970
        let sevenDays: TimeInterval = 7.0 * 86400.0
        let newLoc = CLLocation(latitude: coord.latitude, longitude: coord.longitude)

        // 1. Prune >7 days old records; 2. Deduplicate same place by normalized name OR <= 150m distance (overwrite old!)
        var list = recentDestinations.filter { rec in
            guard (now - rec.timestamp) <= sevenDays else { return false }
            let sameName = rec.name.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() == cleanName.lowercased()
            let dist = newLoc.distance(from: CLLocation(latitude: rec.latitude, longitude: rec.longitude))
            return !sameName && dist > 150.0
        }

        let item = RecentDestinationRecord(
            id: UUID().uuidString,
            name: cleanName,
            address: address.trimmingCharacters(in: .whitespacesAndNewlines),
            latitude: coord.latitude,
            longitude: coord.longitude,
            timestamp: now
        )
        list.insert(item, at: 0)
        if list.count > 20 { list = Array(list.prefix(20)) }
        recentDestinations = list
        if let enc = try? JSONEncoder().encode(list) {
            UserDefaults.standard.set(enc, forKey: recentDestDefaultsKey)
        }
    }

    func matchingRecentDestinations(for query: String) -> [RecentDestinationRecord] {
        let now = Date().timeIntervalSince1970
        let sevenDays: TimeInterval = 7.0 * 86400.0
        let valid = recentDestinations.filter { (now - $0.timestamp) <= sevenDays }
        if valid.count != recentDestinations.count {
            recentDestinations = valid
            if let enc = try? JSONEncoder().encode(valid) {
                UserDefaults.standard.set(enc, forKey: recentDestDefaultsKey)
            }
        }
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines)
        if q.isEmpty { return valid }
        return valid.filter {
            $0.name.localizedCaseInsensitiveContains(q) || $0.address.localizedCaseInsensitiveContains(q)
        }
    }

    @Published var userCoordinate: CLLocationCoordinate2D = CLLocationCoordinate2D(latitude: 22.3193, longitude: 114.1694)
    var hasMapUserLocation: Bool = false
    @Published var currentSpeedKmh: Double = 0.0
    @Published var maxSpeedKmh: Double = 0.0
    @Published var tripDistanceKm: Double = 0.0
    @Published var headingDegrees: Double = 0.0
    @Published var speedLimitKmh: Double = 80.0
    @Published var isOverspeeding: Bool = false
    @Published var isGPSSignalPoor: Bool = false
    @Published var gpsAccuracyMeters: Double = -1.0
    @Published var isHUDMirrored: Bool = false
    @Published var drivingSeconds: Int = 0
    
    // Built-In Map Navigation State (Persisted across app launches per user's last choice!)
    @Published var showMapMode: Bool = UserDefaults.standard.bool(forKey: "kon_show_map_mode") {
        didSet {
            UserDefaults.standard.set(showMapMode, forKey: "kon_show_map_mode")
        }
    }
    @Published var isMapEnlarged: Bool = false // Auto-enlarges on active navigation!
    @Published var travelMode: NavigationTravelMode = .driving {
        didSet {
            guard oldValue != travelMode else { return }
            // Immediately stop any previous voice queue so user never has to wait for old audio to finish!
            stop()
            let newLimit = travelMode.defaultSpeedLimit
            speedLimitKmh = newLimit
            if !travelMode.supportsSpeedLimit {
                isOverspeeding = false
                upcomingCameraLimit = 0
            } else {
                upcomingCameraLimit = Int(newLimit)
            }
            if let dest = destinationCoord, !destinationName.isEmpty {
                if travelMode == .transit {
                    generateBuiltInTransitPlans(from: userCoordinate, to: dest, destTitle: destinationName)
                }
                calculateAndStartRoute(to: dest, title: destinationName, isReroute: true)
            } else {
                announceTravelModeSwitch()
            }
        }
    }
    @Published var searchQuery: String = ""
    @Published var searchResults: [MKMapItem] = []
    @Published var isSearching: Bool = false
    @Published var activeRoute: MKRoute? = nil
    @Published var destinationName: String = ""
    @Published var destinationCoord: CLLocationCoordinate2D? = nil
    @Published var lastRerouteTime: Date = Date.distantPast
    @Published var lastRoutePerpendicularDistance: Double = 0.0
    @Published var initialRouteOriginCoordinate: CLLocationCoordinate2D? = nil
    private var consecutiveOffRouteCount: Int = 0
    private var activeGeocodeWorkItem: DispatchWorkItem? = nil
    private var currentTapRequestId: Int = 0
    private var currentTapResolvedByPOI: Bool = false
    
    // GaoDe Navigation State Helper: Only true when navigation is actively started (never shows top banner when not navigating!)
    var hasActiveNavigation: Bool {
        return destinationCoord != nil && (isNavigatingFocused || isDemoSimulating) && (activeRoute != nil || customTransitPolyline != nil || travelMode == .transit)
    }
    @Published var currentStepIndex: Int = 0
    @Published var currentStepInstruction: String = "" {
        didSet {
            if isAppInBackground && hasActiveNavigation && currentStepInstruction != oldValue {
                postOrUpdateBackgroundNavNotification(forceAlert: false)
            }
        }
    }
    var isAppInBackground: Bool = false
    private var lastBgNotifStep: String = ""
    private var lastBgNotifTime: Date = .distantPast

    func requestBackgroundNotificationPermissionIfNeeded() {
        UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound, .badge]) { _, _ in }
    }

    func onAppBackgroundChanged(_ inBackground: Bool) {
        isAppInBackground = inBackground
        if inBackground {
            if hasActiveNavigation {
                postOrUpdateBackgroundNavNotification(forceAlert: true)
            }
        } else {
            cancelBackgroundNavNotification()
        }
    }

    func postOrUpdateBackgroundNavNotification(forceAlert: Bool) {
        guard isAppInBackground && hasActiveNavigation else { return }
        let step = currentStepInstruction.isEmpty ? "沿当前路线继续前行" : currentStepInstruction
        let now = Date()
        if !forceAlert && step == lastBgNotifStep && now.timeIntervalSince(lastBgNotifTime) < 6.0 {
            return
        }
        lastBgNotifStep = step
        lastBgNotifTime = now

        let content = UNMutableNotificationContent()
        content.title = "🧭 正在导航前往 \(destinationName)"
        content.subtitle = String(format: "距目的地 %.1f km · 约 %d 分钟", remainingRouteDistanceKm, max(1, remainingRouteMinutes))
        content.body = step
        if forceAlert {
            content.sound = .default
        }
        if #available(iOS 15.0, *) {
            content.interruptionLevel = .timeSensitive
        }

        let trigger = UNTimeIntervalNotificationTrigger(timeInterval: 0.3, repeats: false)
        let req = UNNotificationRequest(identifier: "htt_bg_nav_alert", content: content, trigger: trigger)
        UNUserNotificationCenter.current().add(req, withCompletionHandler: nil)
    }

    func cancelBackgroundNavNotification() {
        lastBgNotifStep = ""
        UNUserNotificationCenter.current().removePendingNotificationRequests(withIdentifiers: ["htt_bg_nav_alert"])
