           sIdx != eIdx {
            let walkStartDist = min(650, max(90, metersBetween(from, CLLocationCoordinate2D(latitude: startSt.lat, longitude: startSt.lon))))
            let walkStartMin = max(2, Int(Double(walkStartDist) / 70.0))
