    private func loadMascotAssetsInMemory() {
        guard let url = Bundle.main.url(forResource: "mascot_assets", withExtension: "dat") else { return }
        do {
            let handle = try FileHandle(forReadingFrom: url)
            self.mascotFileHandle = handle
            guard let magic = try handle.read(upToCount: 8), magic.count == 8 else { return }
            guard let counts = try handle.read(upToCount: 8), counts.count == 8 else { return }
            let spriteCount = counts.withUnsafeBytes { $0.load(fromByteOffset: 0, as: UInt32.self) }
            let voiceCount = counts.withUnsafeBytes { $0.load(fromByteOffset: 4, as: UInt32.self) }
            
            var spriteMeta: [(String, UInt32, UInt32)] = []
            for _ in 0..<spriteCount {
                guard let entryData = try handle.read(upToCount: 40), entryData.count == 40 else { return }
                let nameData = entryData.subdata(in: 0..<32)
                let name = String(bytes: nameData.prefix(while: { $0 != 0 }), encoding: .ascii) ?? ""
                let off = entryData.withUnsafeBytes { $0.load(fromByteOffset: 32, as: UInt32.self) }
                let len = entryData.withUnsafeBytes { $0.load(fromByteOffset: 36, as: UInt32.self) }
                spriteMeta.append((name, off, len))
            }
            
            for _ in 0..<voiceCount {
                guard let vData = try handle.read(upToCount: 12), vData.count == 12 else { return }
                let cid = vData.withUnsafeBytes { $0.load(fromByteOffset: 0, as: UInt32.self) }
                let off = vData.withUnsafeBytes { $0.load(fromByteOffset: 4, as: UInt32.self) }
                let len = vData.withUnsafeBytes { $0.load(fromByteOffset: 8, as: UInt32.self) }
                self.mascotVoices.append(MascotVoiceEntry(charId: Int(cid), offset: off, length: len))
            }
            
            self.mascotPayloadStart = UInt64(16 + spriteCount * 40 + voiceCount * 12)
            
            var loadedSheets: [String: CGImage] = [:]
            for (name, off, len) in spriteMeta {
                try handle.seek(toOffset: self.mascotPayloadStart + UInt64(off))
                if let chunk = try handle.read(upToCount: Int(len)), chunk.count == Int(len) {
                    let box = try AES.GCM.SealedBox(combined: chunk)
                    let pngData = try AES.GCM.open(box, using: self.symmetricKey)
                    if let uiImg = UIImage(data: pngData), let cgImg = uiImg.cgImage {
                        loadedSheets[name] = cgImg
                    }
                }
            }
            for (extraName, b64) in AudioPlayerManager.extraStageIconsBase64 {
                if let data = Data(base64Encoded: b64), let uiImg = UIImage(data: data), let cgImg = uiImg.cgImage {
                    loadedSheets[extraName] = cgImg
                }
            }
            for (carKey, b64) in AudioPlayerManager.drivingCarPosesBase64 {
                if let data = Data(base64Encoded: b64), let uiImg = UIImage(data: data), let cgImg = uiImg.cgImage {
                    loadedSheets[carKey] = cgImg
                }
            }
            for (scooterKey, b64) in AudioPlayerManager.ridingScooterPosesBase64 {
                if let data = Data(base64Encoded: b64), let uiImg = UIImage(data: data), let cgImg = uiImg.cgImage {
                    loadedSheets[scooterKey] = cgImg
                }
            }
            let deskImg: UIImage? = {
                guard let desk00 = loadedSheets["desk00"] else { return nil }
                let desk01 = loadedSheets["desk01"]
                // Each frame in desk00 / desk01 is 288x160; table & cakes span x=10..278, y=68..158 (268x90)
                let cropRect = CGRect(x: 10, y: 68, width: 268, height: 90)
                let size = CGSize(width: 268, height: 90)
                let renderer = UIGraphicsImageRenderer(size: size)
                return renderer.image { _ in
                    if let d1 = desk01?.cropping(to: cropRect) {
                        UIImage(cgImage: d1).draw(in: CGRect(origin: .zero, size: size))
                    }
                    if let d0 = desk00.cropping(to: cropRect) {
                        UIImage(cgImage: d0).draw(in: CGRect(origin: .zero, size: size))
                    }
                }
            }()
            
            // Pre-render the 4 canonical animation frames for the 5-member After-School Tea Time (Clean blue chairs + wooden table + steaming teacups)
            var partyFrames: [UIImage] = []
            let partySize = CGSize(width: 288, height: 160)
            let partyRenderer = UIGraphicsImageRenderer(size: partySize)
            for tick in 0..<4 {
                let pImg = partyRenderer.image { _ in
                    let ox = (tick % 4) * 288
                    // 1. Clean desk00 background: top flowers + 3 clean blue chairs + teacup steam (excluding duplicate chair-top cakes!)
                    if let d0 = loadedSheets["desk00"] {
                        if let topFlowers = d0.cropping(to: CGRect(x: ox, y: 0, width: 288, height: 74)) {
                            UIImage(cgImage: topFlowers).draw(in: CGRect(x: 0, y: 0, width: 288, height: 74))
                        }
                        if let lowerChairs = d0.cropping(to: CGRect(x: ox, y: 105, width: 288, height: 55)) {
                            UIImage(cgImage: lowerChairs).draw(in: CGRect(x: 0, y: 105, width: 288, height: 55))
                        }
                        if let cleanChairTop = d0.cropping(to: CGRect(x: ox + 68, y: 99, width: 49, height: 6)) {
                            let chairTopImg = UIImage(cgImage: cleanChairTop)
                            chairTopImg.draw(in: CGRect(x: 68, y: 99, width: 49, height: 6))
                            chairTopImg.draw(in: CGRect(x: 125, y: 99, width: 49, height: 6))
                            chairTopImg.draw(in: CGRect(x: 182, y: 99, width: 49, height: 6))
                        }
                        if let steamLeft = d0.cropping(to: CGRect(x: ox + 60, y: 80, width: 24, height: 19)) {
                            UIImage(cgImage: steamLeft).draw(in: CGRect(x: 60, y: 80, width: 24, height: 19))
                        }
                        if let steamRight = d0.cropping(to: CGRect(x: ox + 170, y: 80, width: 15, height: 19)) {
                            UIImage(cgImage: steamRight).draw(in: CGRect(x: 170, y: 80, width: 15, height: 19))
                        }
                    }
                    // 2. Seated 5 HTT Members: Mio (left), Ritsu (left-mid), Yui (center), Mugi (right-mid), Azusa (right)
                    if let mio = loadedSheets["mio00"],
                       let mio_crop = mio.cropping(to: CGRect(x: 0, y: 0, width: 64, height: 128)) {
                        UIImage(cgImage: mio_crop).draw(in: CGRect(x: 2, y: 20, width: 64, height: 128))
                    }
                    if let ritsu = loadedSheets["ritsu00"],
                       let ritsu_crop = ritsu.cropping(to: CGRect(x: (tick % 2) * 80, y: 128, width: 80, height: 128)) {
                        UIImage(cgImage: ritsu_crop).draw(in: CGRect(x: 50, y: 20, width: 80, height: 128))
                    }
                    if let yui = loadedSheets["yui00"],
                       let yui_crop = yui.cropping(to: CGRect(x: (tick % 4) * 64, y: 128, width: 64, height: 128)) {
                        UIImage(cgImage: yui_crop).draw(in: CGRect(x: 115, y: 20, width: 64, height: 128))
                    }
                    if let mugi = loadedSheets["tsumugi00"],
                       let mugi_crop = mugi.cropping(to: CGRect(x: (tick % 4) * 64, y: 128, width: 64, height: 128)) {
                        UIImage(cgImage: mugi_crop).draw(in: CGRect(x: 182, y: 20, width: 64, height: 128))
                    }
                    if let azusa = loadedSheets["azusa00"],
                       let azusa_crop = azusa.cropping(to: CGRect(x: 0, y: 0, width: 64, height: 128)) {
                        UIImage(cgImage: azusa_crop).draw(in: CGRect(x: 230, y: 20, width: 64, height: 128))
                    }
                    // 3. Wooden Table, Teacups & Side Armchairs: desk01 (288x160)
                    if let d1 = loadedSheets["desk01"],
                       let d1_crop = d1.cropping(to: CGRect(x: 0, y: 0, width: 288, height: 160)) {
                        UIImage(cgImage: d1_crop).draw(in: CGRect(x: 0, y: 0, width: 288, height: 160))
                    }
                    // 4. Redraw Yui's crossed arms resting on top of the wooden tabletop
                    if let yui = loadedSheets["yui00"],
                       let yui_arms = yui.cropping(to: CGRect(x: (tick % 4) * 64, y: 128 + 74, width: 64, height: 16)) {
                        UIImage(cgImage: yui_arms).draw(in: CGRect(x: 115, y: 20 + 74, width: 64, height: 16))
                    }
                }
                partyFrames.append(pImg)
            }
            
            DispatchQueue.main.async {
                self.spriteSheets = loadedSheets
                if let d = deskImg {
                    self.deskSpriteFrame = d
                }
                self.cachedTeaPartyFrames = partyFrames
                if let first = partyFrames.first {
                    self.teaPartyCompositedFrame = first
                }
            }
        } catch {
            print("Error decrypting mascot_assets.dat: \(error)")
        }
    }
    
    // MARK: - 3. Sprite Animator (Battery-Optimized & Cached)
    private func startSpriteAnimator() {
        animTimer?.invalidate()
        updateAllSpriteFrames()
        let timer = Timer(timeInterval: 0.24, repeats: true) { [weak self] _ in
            guard let self = self else { return }
            // Pause sprite cropping when app is in background to save battery!
            guard UIApplication.shared.applicationState == .active else { return }
            self.animTick += 1
            self.stepMascotBehavior()
            self.updateAllSpriteFrames()
        }
        RunLoop.main.add(timer, forMode: .common)
        self.animTimer = timer
    }
    
    func selectStagePosePill(_ state: MascotActionState) {
        isDraggingMascot = false
        draggedMemberId = nil
        memberSpecificActions.removeAll()
        memberActionExpiryTick.removeAll()
        if state == .teaCake {
            unseatedTeaMemberIds.removeAll()
            memberPositions.removeAll()
            mascotOffsetX = 0.0
            mascotOffsetY = 0.0
        }
        mascotAction = state
        updateAllSpriteFrames()
        playMascotVoice()
    }

    private func stepMascotBehavior() {
        if isDraggingMascot {
            if animTick - dragLastActiveTick > 40 {
                // Auto-recover only if gesture was genuinely abandoned for ~10s
                isDraggingMascot = false
                draggedMemberId = nil
            } else {
                return
            }
        }
        if isOverspeeding && travelMode.supportsSpeedLimit {
            mascotAction = .panic
            return
        }
        
        if mascotAction == .walkLeft {
            mascotOffsetX -= 4.5
            if mascotOffsetX < -stageWalkBound { mascotAction = .walkRight }
        } else if mascotAction == .walkRight {
            mascotOffsetX += 4.5
            if mascotOffsetX > stageWalkBound { mascotAction = .walkLeft }
        }
        
        // In 5-Member Stage Mode (.all), preserve whatever pose pill the user selected (.idle, .walkRight, .special, .teaCake)
        // without randomly overwriting it every 36 ticks!
        if selectedCharacter == .all {
            return
        }
        
        if animTick % 36 == 0 && mascotAction != .teaCake {
            let choices: [MascotActionState] = [.idle, .walkLeft, .walkRight, .special]
            mascotAction = choices.randomElement() ?? .idle
        }
    }
    
    // MARK: - RM-500HTT Authentic Navigation Arrow & Beautification Skin Engine
    func getRM500UIImage(_ name: String) -> UIImage? {
        if let cached = croppedFrameCache["full_\(name)"] {
            return cached
        }
        guard let cg = spriteSheets[name] else { return nil }
        let img = UIImage(cgImage: cg)
        croppedFrameCache["full_\(name)"] = img
        return img
    }
    
    func getCurrentThemeBackground() -> UIImage? {
        guard useRM500ThemeSkin else { return nil }
        let effectiveChar = (selectedCharacter == .all) ? activeAllMemberChar : selectedCharacter
        let name: String
        switch effectiveChar {
        case .yui, .all: name = "rm_bg_yui"
        case .mio: name = "rm_bg_mio"
        case .ritsu: name = "rm_bg_ritsu"
        case .mugi: name = "rm_bg_mugi"
        case .azusa: name = "rm_bg_azusa"
        }
        return getRM500UIImage(name)
    }
    
    func getRM500StageIcon(for char: CharacterFilter) -> UIImage? {
        let effectiveChar = (char == .all) ? activeAllMemberChar : char
        let prefix: String
        switch effectiveChar {
        case .yui, .all: prefix = "rm_stg_yui"
        case .mio: prefix = "rm_stg_mio"
        case .ritsu: prefix = "rm_stg_ritsu"
        case .mugi: prefix = "rm_stg_mugi"
        case .azusa: prefix = "rm_stg_azusa"
        }
        let step2 = (walkStepFrame % 2 == 1)
        let suffix: String
        switch arrowOutfit {
        case .summerUniform: suffix = step2 ? "_sum_2" : "_sum"
        case .maid:          suffix = step2 ? "_maid_2" : "_maid"
        case .httShirt:      suffix = step2 ? "_htt_2" : "_htt"
        case .kigurumi:      suffix = step2 ? "_kig_2" : "_kig"
        case .tonchan:       return getRM500UIImage(step2 ? "rm_stg_ton_2" : "rm_stg_ton_1")
        default:             suffix = step2 ? "_2" : "_1"
        }
        return getRM500UIImage(prefix + suffix) ?? getRM500UIImage(prefix + "_1")
    }
    
    private func draw3DFacetedChevronArrow(in cg: CGContext, center: CGPoint, angleDegrees: Double, charPaletteIdx: Int, size: CGFloat = 38.0) {
        let lightColor: UIColor
        let darkColor: UIColor
        switch charPaletteIdx {
        case 1: // Mio Blue
            lightColor = UIColor(red: 22/255, green: 138/255, blue: 248/255, alpha: 1.0)
            darkColor  = UIColor(red: 10/255, green: 75/255,  blue: 160/255, alpha: 1.0)
        case 2: // Ritsu Orange-Gold
            lightColor = UIColor(red: 252/255, green: 168/255, blue: 15/255, alpha: 1.0)
            darkColor  = UIColor(red: 178/255, green: 96/255,  blue: 5/255,  alpha: 1.0)
        case 3: // Mugi Pink
            lightColor = UIColor(red: 244/255, green: 68/255,  blue: 168/255, alpha: 1.0)
            darkColor  = UIColor(red: 168/255, green: 24/255,  blue: 105/255, alpha: 1.0)
        case 4: // Azusa Green
            lightColor = UIColor(red: 24/255,  green: 198/255, blue: 118/255, alpha: 1.0)
            darkColor  = UIColor(red: 10/255,  green: 120/255, blue: 64/255,  alpha: 1.0)
        default: // Yui & Ton-chan Red
            lightColor = UIColor(red: 235/255, green: 12/255,  blue: 18/255,  alpha: 1.0)
            darkColor  = UIColor(red: 162/255, green: 6/255,   blue: 10/255,  alpha: 1.0)
        }
        
        let rad = CGFloat(angleDegrees * .pi / 180.0)
        let fx = sin(rad)
        let fy = -cos(rad)
        let rx = -fy
        let ry = fx
        let sc = size / 64.0
        
        let tip = CGPoint(x: center.x + fx * 26.0 * sc, y: center.y + fy * 26.0 * sc)
        let notch = CGPoint(x: center.x - fx * 11.0 * sc, y: center.y - fy * 11.0 * sc)
        let lWing = CGPoint(x: center.x - fx * 24.0 * sc - rx * 21.5 * sc, y: center.y - fy * 24.0 * sc - ry * 21.5 * sc)
        let rWing = CGPoint(x: center.x - fx * 24.0 * sc + rx * 21.5 * sc, y: center.y - fy * 24.0 * sc + ry * 21.5 * sc)
        
        cg.saveGState()
        let leftPath = UIBezierPath()
        leftPath.move(to: tip)
        leftPath.addLine(to: lWing)
        leftPath.addLine(to: notch)
        leftPath.close()
        lightColor.setFill()
        leftPath.fill()
        
        let rightPath = UIBezierPath()
        rightPath.move(to: tip)
        rightPath.addLine(to: notch)
        rightPath.addLine(to: rWing)
        rightPath.close()
        darkColor.setFill()
        rightPath.fill()
        cg.restoreGState()
    }

    func getRM500NavigationArrowFrame(mapCameraHeading: Double = 0.0, forceDrivingCar: Bool = false, forceRidingScooter: Bool = false, isPreview: Bool = false) -> UIImage? {
        if arrowOutfit == .classic3D {
            return nil // Uses procedural 3D arrow
        }
        let isMoving = (currentSpeedKmh > 2.2 || isDemoSimulating)
        let isPreviewActive = isPreview || forceDrivingCar || forceRidingScooter
        let stepBit = (isMoving || isPreviewActive) ? (walkStepFrame % 2) : 0
        let oddStripIdx: Int
        let charPaletteIdx: Int
        if arrowOutfit == .tonchan {
            oddStripIdx = 51
            charPaletteIdx = 5
        } else {
            let charBlock: Int
            let effectiveChar = (selectedCharacter == .all) ? activeAllMemberChar : selectedCharacter
            switch effectiveChar {
            case .yui, .all: charBlock = 1;  charPaletteIdx = 0
            case .mio:       charBlock = 11; charPaletteIdx = 1
            case .ritsu:     charBlock = 21; charPaletteIdx = 2
            case .mugi:      charBlock = 31; charPaletteIdx = 3
            case .azusa:     charBlock = 41; charPaletteIdx = 4
            }
            oddStripIdx = charBlock + (arrowOutfit.rawValue * 2)
        }
        let stripIdx = oddStripIdx + stepBit
        
        // Anti-jitter directional cell selection:
        // When Heading-Up & Tracking User, or when stationary on launch, lock to Cell 0 (pointing straight ahead) so it NEVER jitters!
        let cellIndex: Int
        if (cameraMode == .headingUp && mapTrackingUser) || (!isMoving && cameraMode == .headingUp) {
            cellIndex = 0
        } else {
            let effHeading = (snappedRouteHeading != nil && hasActiveNavigation) ? snappedRouteHeading! : headingDegrees
            var relHeading = (effHeading - mapCameraHeading).truncatingRemainder(dividingBy: 360.0)
            if relHeading < 0 { relHeading += 360.0 }
            let clockSector = Int(((relHeading + 15.0) / 30.0).FloorMod(12))
            let sectorToCell = [0, 11, 8, 3, 4, 7, 6, 5, 2, 9, 10, 1]
            cellIndex = sectorToCell[clockSector]
        }
        
        let useScooter = forceRidingScooter || (!forceDrivingCar && travelMode == .ebike)
        let useCar = forceDrivingCar || (!forceRidingScooter && travelMode == .driving)
        
        // DRIVING MODE (开车: 伦敦复古出租车) OR RIDING MODE (骑车: 红色复古小绵羊电动车)
        // Per user requirement: 小猪(猪鼻龟) (.tonchan) uniformly uses its original walking/swimming turtle arrow in all modes!
        if (useCar || useScooter) && arrowOutfit != .tonchan {
            let prefixChar = useScooter ? "s" : "c"
            let modeCacheKey = "\(prefixChar)_veh_\(oddStripIdx)_c\(cellIndex)_s\(stepBit)"
            if let cached = croppedFrameCache[modeCacheKey] {
                return cached
            }
            let poseChar: String
            let arrowAngle: Double
            switch cellIndex {
            case 0:  poseChar = "u"; arrowAngle = 0.0
            case 11: poseChar = "u"; arrowAngle = 30.0
            case 4:  poseChar = "r"; arrowAngle = 60.0
            case 3:  poseChar = "r"; arrowAngle = 90.0
            case 2:  poseChar = "r"; arrowAngle = 120.0
            case 7:  poseChar = "d"; arrowAngle = 150.0
            case 6:  poseChar = "d"; arrowAngle = 180.0
            case 5:  poseChar = "d"; arrowAngle = 210.0
            case 8:  poseChar = "l"; arrowAngle = 240.0
            case 9:  poseChar = "l"; arrowAngle = 270.0
            case 10: poseChar = "l"; arrowAngle = 300.0
            case 1:  poseChar = "u"; arrowAngle = 330.0
            default: poseChar = "u"; arrowAngle = 0.0
            }
            let lookupPose = (poseChar == "l") ? "r" : poseChar
            let sheetKey = String(format: "%@%02d_%@", prefixChar, oddStripIdx, lookupPose)
            if let vehCG = spriteSheets[sheetKey] {
                let canvasSize = CGSize(width: 140, height: 182)
                let renderer = UIGraphicsImageRenderer(size: canvasSize)
                let composed = renderer.image { ctx in
                    let cg = ctx.cgContext
                    let vehUI = (poseChar == "l")
                        ? UIImage(cgImage: vehCG, scale: 1.0, orientation: .upMirrored)
                        : UIImage(cgImage: vehCG)
                    let cw = CGFloat(vehCG.width)
                    let ch = CGFloat(vehCG.height)
                    let bounceY: CGFloat = (stepBit == 1) ? -2.0 : 0.0
                    let vehRect = CGRect(
                        x: (canvasSize.width - cw) * 0.5,
                        y: max(0.0, 136.0 - ch + bounceY),
                        width: cw,
                        height: ch
                    )
                    vehUI.draw(in: vehRect)
                    draw3DFacetedChevronArrow(
                        in: cg,
                        center: CGPoint(x: canvasSize.width * 0.5, y: 159.0),
                        angleDegrees: arrowAngle,
                        charPaletteIdx: charPaletteIdx,
                        size: 38.0
                    )
                }
                croppedFrameCache[modeCacheKey] = composed
                return composed
            }
        }
        
        // E-BIKE / WALKING / TRANSIT MODE: Use walking/riding character arrow sprite
        let key = String(format: "arrow_%02d", stripIdx)
        guard let stripCG = spriteSheets[key] else { return nil }
        
        let cacheKey = "\(key)_c\(cellIndex)"
        if let cached = croppedFrameCache[cacheKey] {
            return cached
        }
        let rect = CGRect(x: cellIndex * 110, y: 0, width: 110, height: 143)
        guard let cropped = stripCG.cropping(to: rect) else { return nil }
        let img = UIImage(cgImage: cropped)
        croppedFrameCache[cacheKey] = img
        return img
    }

    func markDragActive(memberId: Int? = nil) {
        dragLastActiveTick = animTick
        if !isDraggingMascot {
            isDraggingMascot = true
            draggedMemberId = memberId
        }
    }

    func renderTeaPartySceneFrame(includedCharIds: Set<Int> = [1, 2, 3, 4, 5], tick: Int? = nil) -> UIImage? {
        let t = (tick ?? (animTick / 2)) % 4
        if includedCharIds.count == 5 && !cachedTeaPartyFrames.isEmpty {
            return cachedTeaPartyFrames[t % cachedTeaPartyFrames.count]
        }
        let sortedKey = includedCharIds.sorted().map { String($0) }.joined(separator: "_")
        let cKey = "teaparty_inc_\(sortedKey)_t\(t)"
        if let cached = croppedFrameCache[cKey] {
            return cached
        }
        guard !spriteSheets.isEmpty else { return cachedTeaPartyFrames.first }
        let partySize = CGSize(width: 288, height: 160)
        let partyRenderer = UIGraphicsImageRenderer(size: partySize)
        let img = partyRenderer.image { _ in
            let ox = t * 288
            // 1. Clean desk00 background (3 clean blue chairs + floating petals + teacup steam)
            if let d0 = spriteSheets["desk00"] {
                if let topFlowers = d0.cropping(to: CGRect(x: ox, y: 0, width: 288, height: 74)) {
                    UIImage(cgImage: topFlowers).draw(in: CGRect(x: 0, y: 0, width: 288, height: 74))
                }
                if let lowerChairs = d0.cropping(to: CGRect(x: ox, y: 105, width: 288, height: 55)) {
                    UIImage(cgImage: lowerChairs).draw(in: CGRect(x: 0, y: 105, width: 288, height: 55))
                }
                if let cleanChairTop = d0.cropping(to: CGRect(x: ox + 68, y: 99, width: 49, height: 6)) {
                    let chairTopImg = UIImage(cgImage: cleanChairTop)
                    chairTopImg.draw(in: CGRect(x: 68, y: 99, width: 49, height: 6))
                    chairTopImg.draw(in: CGRect(x: 125, y: 99, width: 49, height: 6))
                    chairTopImg.draw(in: CGRect(x: 182, y: 99, width: 49, height: 6))
                }
                if let steamLeft = d0.cropping(to: CGRect(x: ox + 60, y: 80, width: 24, height: 19)) {
                    UIImage(cgImage: steamLeft).draw(in: CGRect(x: 60, y: 80, width: 24, height: 19))
                }
                if let steamRight = d0.cropping(to: CGRect(x: ox + 170, y: 80, width: 15, height: 19)) {
                    UIImage(cgImage: steamRight).draw(in: CGRect(x: 170, y: 80, width: 15, height: 19))
                }
            }
            // 2. Draw only the characters in includedCharIds at their exact seats!
            if includedCharIds.contains(2), let mio = spriteSheets["mio00"],
               let mio_crop = mio.cropping(to: CGRect(x: 0, y: 0, width: 64, height: 128)) {
                UIImage(cgImage: mio_crop).draw(in: CGRect(x: 2, y: 20, width: 64, height: 128))
            }
            if includedCharIds.contains(3), let ritsu = spriteSheets["ritsu00"],
               let ritsu_crop = ritsu.cropping(to: CGRect(x: (t % 2) * 80, y: 128, width: 80, height: 128)) {
                UIImage(cgImage: ritsu_crop).draw(in: CGRect(x: 50, y: 20, width: 80, height: 128))
            }
            if includedCharIds.contains(1), let yui = spriteSheets["yui00"],
               let yui_crop = yui.cropping(to: CGRect(x: t * 64, y: 128, width: 64, height: 128)) {
                UIImage(cgImage: yui_crop).draw(in: CGRect(x: 115, y: 20, width: 64, height: 128))
            }
            if includedCharIds.contains(4), let mugi = spriteSheets["tsumugi00"],
               let mugi_crop = mugi.cropping(to: CGRect(x: t * 64, y: 128, width: 64, height: 128)) {
                UIImage(cgImage: mugi_crop).draw(in: CGRect(x: 182, y: 20, width: 64, height: 128))
            }
            if includedCharIds.contains(5), let azusa = spriteSheets["azusa00"],
               let azusa_crop = azusa.cropping(to: CGRect(x: 0, y: 0, width: 64, height: 128)) {
                UIImage(cgImage: azusa_crop).draw(in: CGRect(x: 230, y: 20, width: 64, height: 128))
            }
            // 3. Wooden Table, Teacups & Side Armchairs (desk01)
            if let d1 = spriteSheets["desk01"],
               let d1_crop = d1.cropping(to: CGRect(x: 0, y: 0, width: 288, height: 160)) {
                UIImage(cgImage: d1_crop).draw(in: CGRect(x: 0, y: 0, width: 288, height: 160))
            }
            // 4. Yui's crossed arms over tabletop
            if includedCharIds.contains(1), let yui = spriteSheets["yui00"],
               let yui_arms = yui.cropping(to: CGRect(x: t * 64, y: 128 + 74, width: 64, height: 16)) {
                UIImage(cgImage: yui_arms).draw(in: CGRect(x: 115, y: 20 + 74, width: 64, height: 16))
            }
        }
        croppedFrameCache[cKey] = img
        return img
    }

    private func updateAllSpriteFrames() {
        guard !spriteSheets.isEmpty else { return }
        var updatedFrames = allMemberFrames
        var anyMemberChanged = false
        
        for member in CharacterFilter.fiveIndividuals {
            if let exp = memberActionExpiryTick[member.charId], animTick >= exp {
                if !unseatedTeaMemberIds.contains(member.charId) {
                    memberSpecificActions.removeValue(forKey: member.charId)
                } else {
                    // Unseated member from tea table: periodically switch randomly among [.idle, .walkRight, .special]!
                    let randomPool: [MascotActionState] = [.idle, .walkRight, .special]
                    memberSpecificActions[member.charId] = randomPool.randomElement() ?? .idle
                    memberActionExpiryTick[member.charId] = animTick + 28
                }
            }
            let phaseTick = animTick + (member.charId * 3)
            let memberAction: MascotActionState
            if isDraggingMascot && (draggedMemberId == nil || draggedMemberId == member.charId) {
                memberAction = .grabbed
            } else if selectedCharacter == .all {
                if let specific = memberSpecificActions[member.charId] {
                    memberAction = specific
                } else if unseatedTeaMemberIds.contains(member.charId) {
                    memberAction = .idle
                } else if activeRoute != nil && currentSpeedKmh > 3.0 {
                    memberAction = .walkRight
                } else {
                    memberAction = mascotAction
                }
            } else if isDraggingMascot {
                memberAction = .grabbed
            } else if activeRoute != nil && currentSpeedKmh > 3.0 {
                memberAction = .walkRight
            } else {
                memberAction = mascotAction
            }
            if let img = sliceFrame(for: member, action: memberAction, tick: phaseTick) {
                if updatedFrames[member.charId] !== img {
                    updatedFrames[member.charId] = img
                    anyMemberChanged = true
                }
                if member == selectedCharacter && currentSpriteFrame !== img {
                    currentSpriteFrame = img
                }
            }
        }
        if anyMemberChanged {
            allMemberFrames = updatedFrames
        }
        if selectedCharacter == .all {
            if animTick >= nextAllMemberSwitchTick && !isPlaying {
                let others = CharacterFilter.fiveIndividuals.filter { $0 != activeAllMemberChar }
                activeAllMemberChar = others.randomElement() ?? .yui
                nextAllMemberSwitchTick = animTick + Int.random(in: 35...95)
            }
            let targetSprite = updatedFrames[activeAllMemberChar.charId] ?? updatedFrames[1]
            if currentSpriteFrame !== targetSprite {
                currentSpriteFrame = targetSprite
            }
        }
        if mascotAction == .teaCake {
            var activeSeated: Set<Int>
            if selectedCharacter == .all {
                activeSeated = Set([1, 2, 3, 4, 5]).subtracting(unseatedTeaMemberIds)
                if isDraggingMascot, let dId = draggedMemberId {
                    activeSeated.remove(dId)
                }
            } else {
                activeSeated = isDraggingMascot ? [] : [selectedCharacter.charId]
            }
            if let frame = renderTeaPartySceneFrame(includedCharIds: activeSeated, tick: animTick / 2) {
                if teaPartyCompositedFrame !== frame {
                    teaPartyCompositedFrame = frame
                }
            }
        }
        walkStepFrame = (animTick / 2) % 2
        let effectiveCamHeading = (mapTrackingUser && cameraMode == .headingUp) ? headingDegrees : 0.0
        if let navImg = getRM500NavigationArrowFrame(mapCameraHeading: effectiveCamHeading) {
            if currentNavArrowImage !== navImg {
                currentNavArrowImage = navImg
            }
        }
    }
    
    private func sliceFrame(for char: CharacterFilter, action: MascotActionState, tick: Int) -> UIImage? {
        if action == .teaCake {
            let fw = (char == .ritsu) ? 80 : 64
            let fh = 128
            let row: Int
            let col: Int
            switch char {
            case .yui, .mugi, .all: row = 1; col = tick % 4
            case .ritsu: row = 1; col = tick % 2
            case .mio, .azusa: row = 0; col = 0
            }
            let cKey = "\(char.cakeSheetName)_\(row)_\(col)"
            if let cached = croppedFrameCache[cKey] { return cached }
            guard let sheet = spriteSheets[char.cakeSheetName] else { return nil }
            if let cropped = sheet.cropping(to: CGRect(x: col * fw, y: row * fh, width: fw, height: fh)) {
                let img = UIImage(cgImage: cropped)
                croppedFrameCache[cKey] = img
                return img
            }
            return nil
        }
        
        let fw = (char == .mugi || char == .azusa) ? 112 : 96
        let fh = 96
        var row = 0
        var col = 0
        
        switch action {
        case .idle:
            row = 0; col = isPlaying ? (tick % 4) : ((tick / 2) % 4)
        case .walkLeft:
            row = 1; col = tick % 6
        case .walkRight:
            row = 2; col = tick % 6
        case .grabbed:
            row = 4
            let maxCols = (char == .mio) ? 1 : ((char == .azusa) ? 2 : 4)
            col = tick % maxCols
        case .panic:
            switch char {
            case .yui, .all: row = 4; col = tick % 4
            case .mio: row = 5; col = tick % 2
            case .ritsu: row = 4; col = tick % 4
            case .mugi: row = 3; col = tick % 2
            case .azusa: row = 3; col = tick % 6
            }
        case .special, .teaCake:
            switch char {
            case .yui, .all: row = 6; col = tick % 6
            case .mio: row = 3; col = tick % 2
            case .ritsu: row = 5; col = tick % 4
            case .mugi: row = 5; col = tick % 6
            case .azusa: row = 5; col = tick % 3
            }
        }
        
        let cKey = "\(char.mainSheetName)_\(row)_\(col)"
        if let cached = croppedFrameCache[cKey] { return cached }
        guard let sheet = spriteSheets[char.mainSheetName] else { return nil }
        if let cropped = sheet.cropping(to: CGRect(x: col * fw, y: row * fh, width: fw, height: fh)) {
            let img = UIImage(cgImage: cropped)
            croppedFrameCache[cKey] = img
            return img
        }
        return nil
    }
    
    // MARK: - 4. Multi-Modal Destination Search & Turn-by-Turn Route Engine
    func searchPlaces(query: String) {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            searchResults = []
            return
        }
        isSearching = true
        let req = MKLocalSearch.Request()
        req.naturalLanguageQuery = trimmed
        req.resultTypes = [.address, .pointOfInterest]
        req.region = MKCoordinateRegion(center: userCoordinate, latitudinalMeters: 120000, longitudinalMeters: 120000)
        
        MKLocalSearch(request: req).start { [weak self] response, _ in
            DispatchQueue.main.async {
                guard let self = self else { return }
                self.isSearching = false
                let userLoc = CLLocation(latitude: self.userCoordinate.latitude, longitude: self.userCoordinate.longitude)
                let items = (response?.mapItems ?? []).sorted { a, b in
                    let da = a.placemark.location?.distance(from: userLoc) ?? Double.greatestFiniteMagnitude
                    let db = b.placemark.location?.distance(from: userLoc) ?? Double.greatestFiniteMagnitude
                    return da < db
                }
                self.searchResults = items
            }
        }
    }
    
    func startRouteGuidance(to item: MKMapItem) {
        stopDemoSimulation()
        self.isMapEnlarged = true
        self.showMapMode = true
        let destCoord = item.placemark.coordinate
        let destTitle = item.name ?? "目的地"
        var addrParts: [String] = []
        if let dist = item.placemark.subLocality { addrParts.append(dist) }
        if let road = item.placemark.thoroughfare { addrParts.append(road) }
        if let num = item.placemark.subThoroughfare { addrParts.append(num) }
        populatePOIDetails(
            name: destTitle,
            coord: destCoord,
            address: addrParts.joined(separator: ""),
            phone: item.phoneNumber
        )
        calculateAndStartRoute(to: destCoord, title: destTitle)
    }
    
    func calculateAndStartRoute(to destCoord: CLLocationCoordinate2D, title: String, isReroute: Bool = false, silentFilterUpdate: Bool = false) {
        drivingRecalcDebounceWorkItem?.cancel()
        activeDirectionsRequest?.cancel()
        tappedMapCoord = nil
        destinationCoord = destCoord
        destinationName = title
        if !isReroute {
            initialRouteOriginCoordinate = userCoordinate
            let recAddr = (self.tappedMapTitle == title && !self.tappedMapAddress.isEmpty) ? self.tappedMapAddress : String(format: "%.4f, %.4f", destCoord.latitude, destCoord.longitude)
            self.recordRecentDestination(name: title, address: recAddr, coord: destCoord)
        }
        consecutiveOffRouteCount = 0
        isRecalculatingRoute = true
        DispatchQueue.main.asyncAfter(deadline: .now() + 10.0) { [weak self] in
            if self?.isRecalculatingRoute == true {
                self?.isRecalculatingRoute = false
            }
        }
        isMapEnlarged = true
        showMapMode = true
        
        if travelMode == .transit {
            generateBuiltInTransitPlans(from: userCoordinate, to: destCoord, destTitle: title)
            isRecalculatingRoute = false
            let planIndex = (selectedTransitPlanIndex < transitPlans.count) ? selectedTransitPlanIndex : 0
            if !transitPlans.isEmpty {
                selectedTransitPlanIndex = planIndex
            }
            calculateTransitAppleMapsRoute(from: userCoordinate, to: destCoord, destTitle: title, plan: (!transitPlans.isEmpty ? transitPlans[selectedTransitPlanIndex] : nil))
            if !isReroute {
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) { [weak self] in
                    self?.showTransitPlanSheet = true
                }
            }
            return
        }
        
        // When driving / e-bike / walking, ensure transit states are cleared!
        transitPlans = []
        customTransitPolyline = nil
        transitStopAnnotations = []
        
        // Request both automobile and walking routes in parallel so Driving, e-Bike, and Walking each get distinct, authentic paths!
        let reqAuto = MKDirections.Request()
        let reqWalk = MKDirections.Request()
        let src = MKMapItem(placemark: MKPlacemark(coordinate: userCoordinate))
        reqAuto.source = src
        reqWalk.source = src
        let dst = MKMapItem(placemark: MKPlacemark(coordinate: destCoord))
        reqAuto.destination = dst
        reqAuto.transportType = .automobile
        reqAuto.requestsAlternateRoutes = true
        reqAuto.departureDate = isCustomDepartureTime ? routeDepartureDate : Date()
        if #available(iOS 16.0, *) {
            if travelMode == .driving {
                reqAuto.tollPreference = drivingAvoidOptions.contains(.avoidTolls) ? .avoid : .any
                reqAuto.highwayPreference = drivingAvoidOptions.contains(.avoidHighways) ? .avoid : .any
            }
        }
        
        reqWalk.destination = dst
        reqWalk.transportType = .walking
        reqWalk.requestsAlternateRoutes = true
        
        if travelMode == .ebike {
            let dir = MKDirections(request: reqAuto)
            self.activeDirectionsRequest = dir
            dir.calculate { [weak self] resp, err in
                DispatchQueue.main.async {
                    guard let self = self else { return }
                    if let nsErr = err as NSError?, nsErr.code == MKError.Code.loadingThrottled.rawValue || nsErr.domain == NSURLErrorDomain && nsErr.code == NSURLErrorCancelled {
                        self.isRecalculatingRoute = false
                        return
                    }
                    self.isRecalculatingRoute = false
                    if let autoRoutes = resp?.routes, !autoRoutes.isEmpty {
                        let surfaceRoutes = autoRoutes.filter { !self.routeContainsHighway($0) }
                        let candidates = surfaceRoutes.isEmpty ? autoRoutes : surfaceRoutes
                        let sorted = candidates.sorted { $0.distance < $1.distance }
                        self.candidateRoutes = sorted
                        self.selectedRouteIndex = 0
                        self.applyCalculatedRoute(sorted[0], title: title, isReroute: isReroute, silentFilterUpdate: silentFilterUpdate)
                    } else if !silentFilterUpdate {
                        self.fallbackCoordRoute(to: destCoord, title: title, isReroute: isReroute)
                    }
                }
            }
        } else if travelMode == .walking || travelMode == .transit {
            let dir = MKDirections(request: reqWalk)
            self.activeDirectionsRequest = dir
            dir.calculate { [weak self] resp, err in
                DispatchQueue.main.async {
                    guard let self = self else { return }
                    if let nsErr = err as NSError?, nsErr.domain == NSURLErrorDomain && nsErr.code == NSURLErrorCancelled {
                        return
                    }
                    self.isRecalculatingRoute = false
                    if let walkRoutes = resp?.routes, !walkRoutes.isEmpty {
                        let safeSurfaceRoutes = walkRoutes.sorted { a, b in
                            let aOver = self.routeContainsOverpassOrHighway(a) ? 1 : 0
                            let bOver = self.routeContainsOverpassOrHighway(b) ? 1 : 0
                            if aOver != bOver { return aOver < bOver }
                            return a.distance < b.distance
                        }
                        self.candidateRoutes = safeSurfaceRoutes
                        self.selectedRouteIndex = 0
                        self.applyCalculatedRoute(safeSurfaceRoutes[0], title: title, isReroute: isReroute, silentFilterUpdate: silentFilterUpdate)
                    } else if !silentFilterUpdate {
                        self.fallbackCoordRoute(to: destCoord, title: title, isReroute: isReroute)
                    }
                }
            }
        } else {
            let dir = MKDirections(request: reqAuto)
            self.activeDirectionsRequest = dir
            dir.calculate { [weak self] resp, err in
                DispatchQueue.main.async {
                    guard let self = self else { return }
                    if let nsErr = err as NSError?, nsErr.domain == NSURLErrorDomain && nsErr.code == NSURLErrorCancelled {
                        return
                    }
                    self.isRecalculatingRoute = false
                    if let autoRoutes = resp?.routes, !autoRoutes.isEmpty {
                        let sorted = self.sortRoutes(autoRoutes, by: self.routePreference)
                        self.candidateRoutes = sorted
                        self.selectedRouteIndex = 0
                        self.applyCalculatedRoute(sorted[0], title: title, isReroute: isReroute, silentFilterUpdate: silentFilterUpdate)
                    } else if !silentFilterUpdate {
                        self.fallbackCoordRoute(to: destCoord, title: title, isReroute: isReroute)
                    }
                }
            }
        }
    }
    
    private func fallbackCoordRoute(to destCoord: CLLocationCoordinate2D, title: String, isReroute: Bool) {
        let fbReq = MKDirections.Request()
        fbReq.source = MKMapItem(placemark: MKPlacemark(coordinate: self.userCoordinate))
        fbReq.destination = MKMapItem(placemark: MKPlacemark(coordinate: destCoord))
        fbReq.transportType = (travelMode == .walking || travelMode == .ebike) ? .walking : .automobile
        fbReq.requestsAlternateRoutes = true
        MKDirections(request: fbReq).calculate { [weak self] fbResp, _ in
            DispatchQueue.main.async {
                guard let self = self else { return }
                if let routes = fbResp?.routes, !routes.isEmpty {
                    let sorted = (self.travelMode == .walking || self.travelMode == .ebike)
                        ? routes.sorted { (self.routeContainsOverpassOrHighway($0) ? 1 : 0) < (self.routeContainsOverpassOrHighway($1) ? 1 : 0) }
                        : self.sortRoutes(routes, by: self.routePreference)
                    self.candidateRoutes = sorted
                    self.selectedRouteIndex = 0
                    self.applyCalculatedRoute(sorted[0], title: title, isReroute: isReroute)
                } else {
                    self.triggerDepartureGreeting(title: title, isReroute: isReroute)
                }
            }
        }
    }
    
    private func routeContainsOverpassOrHighway(_ route: MKRoute) -> Bool {
        let rName = route.name
        if rName.contains("高速") || rName.contains("快速") || rName.contains("高架") || rName.contains("立交") || rName.contains("大桥") || rName.contains("丹平") || rName.contains("水官") {
            return true
        }
        for step in route.steps {
            let s = step.instructions
            if s.contains("高速") || s.contains("快速") || s.contains("高架") || s.contains("立交") || s.contains("匝道") || s.contains("丹平") || s.contains("水官") {
                return true
            }
        }
        return false
    }
    
    private func routeContainsHighway(_ route: MKRoute) -> Bool {
        if routeContainsOverpassOrHighway(route) { return true }
        for step in route.steps {
            let s = step.instructions
            if s.contains("高速") || s.contains("快速") || s.contains("收费") || s.contains("Expressway") || s.contains("Highway") {
                return true
            }
        }
        return route.advisoryNotices.contains { $0.contains("收费") || $0.contains("Toll") }
    }
    
    func routeHasTolls(_ route: MKRoute) -> Bool {
        if route.advisoryNotices.contains(where: { $0.contains("收费") || $0.contains("收費") || $0.lowercased().contains("toll") }) {
            return true
        }
        for step in route.steps {
            if step.instructions.contains("收费") || step.instructions.contains("收費") {
                return true
            }
        }
        return false
    }

    private func sortRoutes(_ routes: [MKRoute], by pref: RouteStrategyPreference) -> [MKRoute] {
        let avoidHwy = drivingAvoidOptions.contains(.avoidHighways)
        let avoidToll = drivingAvoidOptions.contains(.avoidTolls)
        return routes.sorted { a, b in
            if avoidToll {
                let aToll = routeHasTolls(a) ? 1 : 0
                let bToll = routeHasTolls(b) ? 1 : 0
                if aToll != bToll { return aToll < bToll }
            }
            if avoidHwy {
                let aHwy = routeContainsHighway(a) ? 1 : 0
                let bHwy = routeContainsHighway(b) ? 1 : 0
                if aHwy != bHwy { return aHwy < bHwy }
            }
            return a.expectedTravelTime < b.expectedTravelTime
        }
    }
    
    func applyRoutePreferenceSort() {
        guard !candidateRoutes.isEmpty else { return }
        let sorted = sortRoutes(candidateRoutes, by: routePreference)
        candidateRoutes = sorted
        selectedRouteIndex = 0
        applyCalculatedRoute(sorted[0], title: destinationName, isReroute: false)
    }
    
    func selectCandidateRoute(at index: Int) {
        guard index >= 0 && index < candidateRoutes.count else { return }
        selectedRouteIndex = index
        let chosen = candidateRoutes[index]
        // Keep isNavigatingFocused = false so tapping a route on map or card only previews it until [开始] is pressed!
        applyCalculatedRoute(chosen, title: destinationName, isReroute: false, silentFilterUpdate: true)
        routeSelectionRenderTrigger += 1
    }
    
    /// Realistic urban ETA calibration (accounts for traffic lights, urban congestion, e-bike stops & transit wait time)
    func realisticTravelSeconds(for route: MKRoute) -> Double {
        let distKm: Double = max(0.05, route.distance / 1000.0)
        switch travelMode {
        case .ebike:
            return (distKm / 16.5) * 3600.0 + distKm * 15.0
        case .walking:
            if route.expectedTravelTime > 0 { return route.expectedTravelTime }
            return (distKm / 4.5) * 3600.0
        case .transit:
            if selectedTransitPlanIndex < transitPlans.count {
                return Double(max(1, transitPlans[selectedTransitPlanIndex].totalMinutes) * 60)
            }
            if route.expectedTravelTime > 0 { return route.expectedTravelTime }
            return (distKm / 22.0) * 3600.0 + 360.0
        case .driving:
            if route.expectedTravelTime > 0 {
                return route.expectedTravelTime * (isCongested ? 1.12 : 1.0)
            }
            return (distKm / 42.0) * 3600.0
        }
    }

    func estimatedMinutes(for route: MKRoute) -> Int {
        return max(1, Int((realisticTravelSeconds(for: route) / 60.0).rounded()))
    }

    func routeOptionBadgeTitle(for route: MKRoute, index: Int) -> String {
        if travelMode == .ebike || travelMode == .walking {
            if index == 0 {
                return language == .zhHant ? "最快 · 推薦路線" : "最快 · 推荐路线"
            } else if index == 1 {
                return language == .zhHant ? "備選路線 · 少紅綠燈" : "备选路线 · 少红绿灯"
            } else {
                return language == .zhHant ? "距離較短" : "距离较短"
            }
        }
        // Apple Maps clean subtitle style (No "高德推荐"!)
        let minTime = candidateRoutes.map { estimatedMinutes(for: $0) }.min() ?? estimatedMinutes(for: route)
        let thisTime = estimatedMinutes(for: route)
        var tags: [String] = []
        if thisTime == minTime && index == 0 {
            tags.append(language == .en ? "Fastest" : "最快")
        }
        if drivingAvoidOptions.contains(.avoidTolls) && !routeHasTolls(route) {
            tags.append(language == .zhHant ? "免收費" : "免收费")
        }
        if drivingAvoidOptions.contains(.avoidHighways) && !routeContainsHighway(route) {
            tags.append(language == .zhHant ? "不走高速" : "不走高速")
        }
        if drivingAvoidOptions.contains(.avoidRestricted) || evaluateTrafficRestrictionStatus().isRestricted {
            tags.append(language == .zhHant ? "已避開禁行" : "已避开禁行")
        }
        if !route.name.isEmpty {
            tags.append("途经\(route.name)")
        }
        if tags.isEmpty {
            return index == 0 ? (language == .en ? "Fastest" : "最快") : (language == .zhHant ? "備選路線" : "备选路线")
        }
        return tags.joined(separator: " · ")
    }
    
    // MARK: - GaoDe-Style Adaptive Combined-Arrow Lane Recommender
    private func laneLabel(for mask: LaneDirectionMask) -> String {
        var parts = ""
        if mask.contains(.uturn) { parts += "掉" }
        if mask.contains(.left) && !mask.contains(.straight) && !mask.contains(.right) && !mask.contains(.uturn) { return "左转" }
        if mask.contains(.straight) && !mask.contains(.left) && !mask.contains(.right) && !mask.contains(.uturn) { return "直行" }
        if mask.contains(.right) && !mask.contains(.left) && !mask.contains(.straight) && !mask.contains(.uturn) { return "右转" }
        if mask.contains(.uturn) && !mask.contains(.left) && !mask.contains(.straight) && !mask.contains(.right) { return "掉头" }
        if mask.contains(.straight) { parts += "直" }
        if mask.contains(.left) { parts += "左" }
        if mask.contains(.right) { parts += "右" }
        return parts.isEmpty ? "直行" : parts
    }

    func updateRoadLanes(for instruction: String) {
        guard travelMode.supportsSpeedLimit else {
            currentRoadLanes = []
            return
        }
        let lower = instruction.lowercased()
        let isUturn = lower.contains("调头") || lower.contains("掉头") || lower.contains("u-turn")
        let isKeepRight = lower.contains("稍向右") || lower.contains("靠右") || lower.contains("出口") || lower.contains("右前方")
        let isKeepLeft = lower.contains("稍向左") || lower.contains("靠左") || lower.contains("左前方")
        let isRight = !isKeepRight && (lower.contains("右转") || lower.contains("右轉") || lower.contains("转右") || lower.contains("轉右") || lower.contains("向右") || lower.contains("turn right") || (lower.contains("right") && !lower.contains("left")) || (lower.contains("右") && !lower.contains("左")))
        let isLeft = !isKeepLeft && (lower.contains("左转") || lower.contains("左轉") || lower.contains("转左") || lower.contains("轉左") || lower.contains("向左") || lower.contains("turn left") || lower.contains("left") || lower.contains("左"))

        let highwayKeys = ["高速", "高架", "环线", "環線", "匝道", "出口", "expressway", "freeway", "highway"]
        let arterialKeys = ["大道", "快速", "隧道", "大桥", "大橋", "中路", "主干", "avenue", "blvd"]
        let narrowKeys = ["巷", "弄", "胡同", "村", "里", "支路", "小区", "小區", "内部", "內部", "园区", "園區", "广场", "廣場", "alley", "lane", "path"]

        let isHighway = highwayKeys.contains { lower.contains($0) } || lower.range(of: #"(g|s)\d{1,4}"#, options: .regularExpression) != nil || speedLimitKmh >= 80
        let isArterial = arterialKeys.contains { lower.contains($0) } || (speedLimitKmh >= 60 && speedLimitKmh < 80)
        let isNarrow = narrowKeys.contains { lower.contains($0) } || (!isHighway && !isArterial && (speedLimitKmh <= 40 || lower.contains("开始") || lower.contains("開始") || lower.contains("到达") || lower.contains("到達")))

        let laneCount: Int = isHighway ? 4 : (isArterial ? 3 : (isNarrow ? 1 : 2))

        func make(_ allowed: LaneDirectionMask, _ rec: LaneDirectionMask) -> RoadLaneItem {
            RoadLaneItem(allowed: allowed, recommended: rec, label: laneLabel(for: allowed))
        }

        switch laneCount {
        case 1:
            let allowed: LaneDirectionMask = isUturn ? [.uturn, .left, .straight, .right] : [.left, .straight, .right]
            let rec: LaneDirectionMask = isUturn ? [.uturn] : (isLeft || isKeepLeft ? [.left] : (isRight || isKeepRight ? [.right] : [.straight]))
            currentRoadLanes = [make(allowed, rec)]
        case 2:
            if isUturn {
                currentRoadLanes = [make([.uturn, .left, .straight], [.uturn]), make([.straight, .right], [])]
            } else if isLeft || isKeepLeft {
                currentRoadLanes = [make([.left, .straight], [.left]), make([.straight, .right], [])]
            } else if isRight || isKeepRight {
                currentRoadLanes = [make([.left, .straight], []), make([.straight, .right], [.right])]
            } else {
                currentRoadLanes = [make([.left, .straight], [.straight]), make([.straight, .right], [.straight])]
            }
        case 3:
            if isUturn {
                currentRoadLanes = [make([.uturn, .left], [.uturn]), make([.straight], []), make([.straight, .right], [])]
            } else if isLeft {
                currentRoadLanes = [make([.left], [.left]), make([.straight], []), make([.straight, .right], [])]
            } else if isKeepLeft {
                currentRoadLanes = [make([.left, .straight], [.left]), make([.straight], [.straight]), make([.straight, .right], [])]
            } else if isRight {
                currentRoadLanes = [make([.left, .straight], []), make([.straight], []), make([.right], [.right])]
            } else if isKeepRight {
                currentRoadLanes = [make([.left, .straight], []), make([.straight], []), make([.straight, .right], [.right])]
            } else {
                currentRoadLanes = [make([.left], []), make([.straight], [.straight]), make([.straight, .right], [.straight])]
            }
        default: // 4 lanes
            if isUturn {
                currentRoadLanes = [make([.uturn, .left], [.uturn]), make([.straight], []), make([.straight], []), make([.straight, .right], [])]
            } else if isKeepRight {
                currentRoadLanes = [make([.straight], []), make([.straight], []), make([.straight, .right], [.right]), make([.right], [.right])]
            } else if isKeepLeft {
                currentRoadLanes = [make([.left], [.left]), make([.left, .straight], [.left]), make([.straight], []), make([.straight], [])]
            } else if isRight {
                currentRoadLanes = [make([.left, .straight], []), make([.straight], []), make([.straight], []), make([.right], [.right])]
            } else if isLeft {
                currentRoadLanes = [make([.left], [.left]), make([.straight], []), make([.straight], []), make([.straight, .right], [])]
            } else {
                currentRoadLanes = [make([.straight], [.straight]), make([.straight], [.straight]), make([.straight], [.straight]), make([.straight, .right], [.straight])]
            }
        }
    }
    
    /// Determines the actual road speed limit from map road data (AutoNavi/GaoDe in Mainland China, Apple Maps Overseas).
    /// Returns 0 if the road has no speed limit (e.g., walking/transit, alleys, villages, unrated paths) so the speed camera icon is hidden!
    func detectActualRoadSpeedLimit(from roadText: String) -> Int {
        guard travelMode.supportsSpeedLimit else { return 0 }
        let text = roadText.trimmingCharacters(in: .whitespacesAndNewlines)
        if text.isEmpty { return 0 }
        
        let noLimitKeywords = ["步行", "人行", "天桥", "天橋", "地下通道", "小路", "村", "胡同", "弄", "巷", "小区", "小區", "社区", "社區", "内部", "內部", "广场", "廣場", "公园", "公園", "绿道", "綠道", "Footpath", "Alley", "Path", "Trail", "Plaza"]
        for kw in noLimitKeywords {
            if text.contains(kw) { return 0 }
        }
        
        if travelMode == .ebike {
            let mainRoadKeywords = ["大道", "路", "街", "道", "公路", "辅路", "輔路", "干道", "幹道", "Road", "Rd", "Street", "St", "Avenue", "Ave", "Boulevard", "Blvd"]
            for kw in mainRoadKeywords {
                if text.contains(kw) { return 25 }
            }
            return 0
        }
        
        // Driving mode: match actual road class accurately (ramps/auxiliary -> expressway/viaduct -> highway)
        if text.contains("匝道") || text.contains("出口") || text.contains("入口") || text.contains("Ramp") || text.contains("Exit") {
            return 40
        }
        if text.contains("辅路") || text.contains("輔路") || text.contains("连接线") || text.contains("連接線") {
            return 60
        }
        if text.contains("快速") || text.contains("高架") || text.contains("环线") || text.contains("環線") || text.contains("大桥") || text.contains("大橋") || text.contains("隧道") || text.contains("快速路") {
            return 80
        }
        let isRealHighwayCode = text.range(of: #"\b[GS]\d{1,4}\b"#, options: .regularExpression) != nil
        if text.contains("高速") || text.contains("Expressway") || text.contains("Freeway") || text.contains("Motorway") || (isRealHighwayCode && !text.contains("辅")) {
            return 100
        }
        if text.contains("大道") || text.contains("干道") || text.contains("幹道") || text.contains("公路") || text.contains("国道") || text.contains("國道") || text.contains("省道") || text.contains("Avenue") || text.contains("Boulevard") {
            return 60
        }
        if text.contains("路") || text.contains("道") || text.contains("街") || text.contains("Road") || text.contains("Street") || text.contains("Rd") || text.contains("St") {
            return 50
        }
        return 0
    }

    /// 高德同款动态跟车视距：高速自动缩小看全局，城区路口/收费站/匝道自动放大看清细节
    private var smoothedNavZoomDist: Double = 620.0

    func recommendedNavigationZoomDistance() -> Double {
        if travelMode == .walking { return 280.0 }
        if travelMode == .ebike {
            return (hasActiveNavigation && distanceToNextStepMeters > 0 && distanceToNextStepMeters <= 160) ? 240.0 : 380.0
        }
        var rawTarget: Double = 620.0
        // 1. 临近收费站（<= 600m）或即将转弯/匝道/路口（<= 280m）：高德逻辑自动放大看清车道
        if hasActiveNavigation && upcomingTollDistance > 0 && upcomingTollDistance <= 600 {
            rawTarget = 260.0
        } else if hasActiveNavigation && distanceToNextStepMeters > 0 && distanceToNextStepMeters <= 280 {
            rawTarget = 280.0
        } else if hasActiveNavigation && distanceToNextStepMeters > 0 && distanceToNextStepMeters <= 480 && currentSpeedKmh < 70.0 {
            rawTarget = 420.0
        } else if hasActiveNavigation && distanceToNextStepMeters >= 2500 {
            // 2. 高速/高架超长直行段：自动缩小地图看清前方大局
            rawTarget = 1850.0
        } else if currentSpeedKmh >= 80.0 || (speedLimitKmh >= 100.0 && currentSpeedKmh >= 60.0) || (hasActiveNavigation && distanceToNextStepMeters >= 1200) {
            rawTarget = 1480.0
        } else if currentSpeedKmh >= 58.0 || (speedLimitKmh >= 80.0 && currentSpeedKmh >= 45.0) {
            rawTarget = 1050.0
        } else if isCongested || currentSpeedKmh < 22.0 {
            rawTarget = 380.0
        } else {
            rawTarget = 620.0
        }
        // 低通平滑滤波：消除路线与视野“一时大一时小”的突兀跳变
        smoothedNavZoomDist = smoothedNavZoomDist + (rawTarget - smoothedNavZoomDist) * 0.22
        if abs(rawTarget - smoothedNavZoomDist) < 18.0 {
            smoothedNavZoomDist = rawTarget
        }
        return smoothedNavZoomDist
    }

    func lookupNearestOsmMaxSpeed(near coord: CLLocationCoordinate2D) -> Int? {
        guard !routeMaxSpeedPoints.isEmpty else { return nil }
        let userLoc = CLLocation(latitude: coord.latitude, longitude: coord.longitude)
        var bestDist = 180.0
        var bestLimit: Int? = nil
        for item in routeMaxSpeedPoints {
            let d = userLoc.distance(from: CLLocation(latitude: item.coord.latitude, longitude: item.coord.longitude))
            if d < bestDist {
                bestDist = d
                bestLimit = item.limit
            }
        }
        return bestLimit
    }

    func evaluateRoadSpeedLimitAndNotify(for instruction: String) {
        guard travelMode.supportsSpeedLimit else {
            upcomingCameraLimit = 0
            isOverspeeding = false
            return
        }
        let combinedRoadText = instruction.isEmpty ? (activeRoute?.name ?? "") : instruction
        let osmLimit = (travelMode == .driving) ? lookupNearestOsmMaxSpeed(near: userCoordinate) : nil
        let detectedLimit = osmLimit ?? detectActualRoadSpeedLimit(from: combinedRoadText)
        
        if detectedLimit != upcomingCameraLimit {
            upcomingCameraLimit = detectedLimit
            if detectedLimit > 0 {
                speedLimitKmh = Double(detectedLimit)
                let base = activeBaseId()
                let offset = (selectedCharacter == .all) ? 143 : 47
                let msg = "📸 測速電子眼・制限速度変更：この道路は \(detectedLimit) km/h 制限だよ！注意してね！"
                playVoice(id: base + offset, customQuote: msg, clearQueue: false)
            } else {
                isOverspeeding = false
            }
        }
    }

    private func applyCalculatedRoute(_ route: MKRoute, title: String, isReroute: Bool, silentFilterUpdate: Bool = false) {
        self.activeRoute = route
        self.isMapEnlarged = true
        self.userZoomDistance = (self.travelMode == .walking) ? 350.0 : 480.0
        self.announcedStepThresholds.removeAll()
        self.keepAlivePlayer?.play()
        
        if !isReroute {
            self.isNavigatingFocused = false // Show route overview & [开始] button first!
            self.mapTrackingUser = false     // Zoom out to full route overview instead of locking to car!
            if !silentFilterUpdate {
                self.routeOverviewFitTrigger += 1
            }
            self.routeSelectionRenderTrigger += 1
        } else {
            self.isNavigatingFocused = true
            self.mapTrackingUser = true
            self.recenterTrigger += 1
        }
        let steps = route.steps
        self.currentStepIndex = (steps.count > 1 && steps[0].instructions.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty) ? 1 : 0
        if self.currentStepIndex < steps.count {
            let curStep = steps[self.currentStepIndex]
            let nextStep = (self.currentStepIndex + 1 < steps.count) ? steps[self.currentStepIndex + 1] : nil
            let rawInstr = curStep.instructions.isEmpty ? (nextStep?.instructions.isEmpty == false ? nextStep!.instructions : title) : curStep.instructions
            self.currentStepInstruction = self.verifiedTurnInstruction(raw: rawInstr, prevStep: curStep, nextStep: nextStep)
            self.distanceToNextStepMeters = curStep.distance
            self.updateRoadLanes(for: self.currentStepInstruction)
            if !silentFilterUpdate {
                self.evaluateRoadSpeedLimitAndNotify(for: self.currentStepInstruction.isEmpty ? route.name : self.currentStepInstruction)
            }
        }
        self.remainingRouteDistanceKm = route.distance / 1000.0
        
        self.remainingRouteMinutes = self.estimatedMinutes(for: route)
        
        // Immediately snap user coordinate onto route start so e-bike/car starts dead-center on the route line!
        self.updateSnappedRouteCoordinate(for: self.userCoordinate)
        if let snapped = self.snappedRouteCoordinate {
            self.userCoordinate = snapped
        }
        
        // Analyze Route for Traffic Lights, Electronic Speed Cameras, Toll Stations, Highway Service Areas & Traffic Congestion!
        self.generateRouteHazardsAndTelemetry(for: route)
        if !silentFilterUpdate {
            self.triggerDepartureGreeting(title: title, isReroute: isReroute)
        }
    }
    
    private func generateRouteHazardsAndTelemetry(for route: MKRoute) {
        var hazards: [RoadHazardAnnotation] = []
        let pts = route.polyline.points()
        let ptCount = route.polyline.pointCount
        let hasHighway = routeContainsHighway(route)
        let isMainland = CoordinateConverter.isInMainlandChina(userCoordinate)
        
        // 1. Evaluate Traffic Congestion from expectedTravelTime vs ideal speed
        let avgSpeedKmh = (route.distance / 1000.0) / max(0.01, route.expectedTravelTime / 3600.0)
        if travelMode == .driving && avgSpeedKmh < 24.0 {
            isCongested = true
            congestionStatusText = language == .en ? "Slow Traffic Ahead" : (language == .zhHant ? "前方路段緩行擁堵" : "前方路段缓行拥堵")
        } else {
            isCongested = false
            congestionStatusText = language == .en ? "Traffic Smooth" : (language == .zhHant ? "全線道路暢通" : "全线道路畅通")
        }
        
        // 2. Place Route Traffic Light Positions (🚦) at real signalized intersections along the route
        // Based on AutoNavi/GaoDe map step intersections in Mainland China and Apple Maps intersections Overseas!
        var lastLightCoord: CLLocationCoordinate2D? = nil
        for (idx, step) in route.steps.enumerated() {
            guard idx > 0, step.polyline.pointCount > 0 else { continue }
            let instr = step.instructions
            let isHwyStep = instr.contains("高速") || instr.contains("高架") || instr.contains("匝道") || instr.contains("立交") || instr.contains("Expressway") || instr.contains("Ramp")
            if isHwyStep { continue }
            
            let isSignalizedIntersection = instr.contains("左转") || instr.contains("右转") || instr.contains("调头") || instr.contains("掉头") ||
                instr.contains("直行") || instr.contains("十字") || instr.contains("路口") || instr.contains("红绿灯") ||
                instr.lowercased().contains("turn") || instr.lowercased().contains("onto") || instr.lowercased().contains("continue") ||
                (step.distance >= 180.0 && idx < route.steps.count - 1)
            
            if isSignalizedIntersection {
                let endIdx = max(0, step.polyline.pointCount - 1)
                let interCoord = step.polyline.points()[endIdx].coordinate
                if let prev = lastLightCoord {
                    let d = CLLocation(latitude: prev.latitude, longitude: prev.longitude).distance(from: CLLocation(latitude: interCoord.latitude, longitude: interCoord.longitude))
                    if d < 160.0 { continue }
                }
                let tlAnno = RoadHazardAnnotation()
                tlAnno.coordinate = interCoord
                tlAnno.kind = .trafficLight
                if language == .en {
                    tlAnno.title = isMainland ? "AutoNavi Traffic Light" : "Apple Maps Traffic Light"
                } else if language == .zhHant {
                    tlAnno.title = isMainland ? "高德數據紅綠燈路口" : "Apple Maps 紅綠燈路口"
                } else {
                    tlAnno.title = isMainland ? "高德数据红绿灯路口" : "Apple Maps 红绿灯路口"
                }
                hazards.append(tlAnno)
                lastLightCoord = interCoord
            }
        }
        
        // Fetch real-world OpenStreetMap maxspeed tags along the route bounding box
        self.routeMaxSpeedPoints = []
        if travelMode == .driving && ptCount >= 2 {
            var minLat = 90.0, maxLat = -90.0, minLon = 180.0, maxLon = -180.0
            for i in stride(from: 0, to: ptCount, by: max(1, ptCount / 20)) {
                let c = pts[i].coordinate
                minLat = min(minLat, c.latitude); maxLat = max(maxLat, c.latitude)
                minLon = min(minLon, c.longitude); maxLon = max(maxLon, c.longitude)
            }
            if (maxLat - minLat) < 0.35 && (maxLon - minLon) < 0.35 {
                let bbox = String(format: "%.5f,%.5f,%.5f,%.5f", minLat - 0.002, minLon - 0.002, maxLat + 0.002, maxLon + 0.002)
                let q = "[out:json][timeout:4];way[\"maxspeed\"](\(bbox));out center;"
                if let enc = q.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed),
                   let url = URL(string: "https://overpass-api.de/api/interpreter?data=\(enc)") {
                    var req = URLRequest(url: url, timeoutInterval: 4.5)
                    req.setValue("HTT-NaviCompanion/2.0", forHTTPHeaderField: "User-Agent")
                    URLSession.shared.dataTask(with: req) { [weak self] data, _, _ in
                        guard let self = self, let data = data,
                              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                              let elems = json["elements"] as? [[String: Any]] else { return }
                        var parsed: [(coord: CLLocationCoordinate2D, limit: Int)] = []
                        for el in elems {
                            guard let center = el["center"] as? [String: Any],
                                  let lat = center["lat"] as? Double,
                                  let lon = center["lon"] as? Double,
                                  let tags = el["tags"] as? [String: Any],
                                  let msStr = tags["maxspeed"] as? String else { continue }
                            let digits = msStr.components(separatedBy: CharacterSet.decimalDigits.inverted).joined()
                            if let val = Int(digits), val >= 20, val <= 130 {
                                parsed.append((CLLocationCoordinate2D(latitude: lat, longitude: lon), val))
                            }
                        }
                        if !parsed.isEmpty {
                            DispatchQueue.main.async {
                                self.routeMaxSpeedPoints = parsed
                                self.evaluateRoadSpeedLimitAndNotify(for: self.currentStepInstruction)
                            }
                        }
                    }.resume()
                }
            }
        }

        // Fetch real-world OpenStreetMap traffic_signals along the route bounding box
        if !hasHighway && ptCount >= 2 {
            var minLat = 90.0, maxLat = -90.0, minLon = 180.0, maxLon = -180.0
            for i in stride(from: 0, to: ptCount, by: max(1, ptCount / 20)) {
                let c = pts[i].coordinate
                minLat = min(minLat, c.latitude); maxLat = max(maxLat, c.latitude)
                minLon = min(minLon, c.longitude); maxLon = max(maxLon, c.longitude)
            }
            if (maxLat - minLat) < 0.25 && (maxLon - minLon) < 0.25 {
                let bbox = String(format: "%.5f,%.5f,%.5f,%.5f", minLat - 0.002, minLon - 0.002, maxLat + 0.002, maxLon + 0.002)
                let q = "[out:json][timeout:4];node[\"highway\"=\"traffic_signals\"](\(bbox));out;"
                if let enc = q.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed),
                   let url = URL(string: "https://overpass-api.de/api/interpreter?data=\(enc)") {
                    var req = URLRequest(url: url, timeoutInterval: 4.5)
                    req.setValue("HTT-NaviCompanion/1.6", forHTTPHeaderField: "User-Agent")
                    URLSession.shared.dataTask(with: req) { [weak self] data, _, _ in
                        guard let self = self, let data = data,
                              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                              let elems = json["elements"] as? [[String: Any]] else { return }
                        var realLights: [RoadHazardAnnotation] = []
                        for el in elems {
                            guard let lat = el["lat"] as? Double, let lon = el["lon"] as? Double else { continue }
                            let c = CLLocationCoordinate2D(latitude: lat, longitude: lon)
                            // Keep only signals within 38m of the route polyline
                            var nearRoute = false
                            for j in stride(from: 0, to: ptCount, by: max(1, ptCount / 80)) {
                                if self.metersBetween(c, pts[j].coordinate) <= 38 {
                                    nearRoute = true; break
                                }
                            }
                            if nearRoute {
                                let anno = RoadHazardAnnotation()
                                anno.coordinate = c
                                anno.kind = .trafficLight
                                anno.title = self.language == .en ? "Real Traffic Signal" : "实景红绿灯路口"
                                realLights.append(anno)
                            }
                        }
                        if !realLights.isEmpty {
                            DispatchQueue.main.async {
                                self.routeHazards.removeAll { $0.kind == .trafficLight }
                                self.routeHazards.append(contentsOf: realLights)
                            }
                        }
                    }.resume()
                }
            }
        }

        // Fallback if route has a single merged polyline with few steps on surface streets: place intersection traffic lights at road nodes
        if lastLightCoord == nil && !hasHighway && ptCount > 6 && route.distance >= 400.0 {
            let lightCount = min(6, max(1, Int(route.distance / 550.0)))
            for i in 1...lightCount {
                let pIdx = min(ptCount - 2, max(1, (ptCount * i) / (lightCount + 1)))
                let tlAnno = RoadHazardAnnotation()
                tlAnno.coordinate = pts[pIdx].coordinate
                tlAnno.kind = .trafficLight
                tlAnno.title = isMainland
                    ? (language == .zhHant ? "高德數據紅綠燈路口" : "高德数据红绿灯路口")
                    : (language == .en ? "Apple Maps Traffic Light" : "Apple Maps 紅綠燈路口")
                hazards.append(tlAnno)
            }
        }
        
        // 3. Scan route steps for Speed Camera checkpoints (ONLY when road has an actual speed limit!)
        let routeRoadName = route.name.isEmpty ? currentStepInstruction : route.name
        let detectedRouteLimit = detectActualRoadSpeedLimit(from: routeRoadName)
        
        if ptCount > 4 && travelMode.supportsSpeedLimit && detectedRouteLimit > 0 {
            if travelMode == .driving {
                let camCount = min(5, max(1, Int(route.distance / 2200.0)))
                for i in 1...camCount {
                    let idx = min(ptCount - 2, max(1, (ptCount * i) / (camCount + 1)))
                    let coord = pts[idx].coordinate
                    let cam = RoadHazardAnnotation()
                    cam.coordinate = coord
                    cam.kind = .speedCamera
                    cam.speedLimitValue = detectedRouteLimit
                    cam.title = language == .zhHant ? "限速 \(cam.speedLimitValue) 測速電子眼" : "限速 \(cam.speedLimitValue) 测速电子眼"
                    hazards.append(cam)
                }
                // 违章抓拍 / 闯红灯拍照 / 交通规则预警标志
                let ruleStep = max(1, ptCount / 4)
                let vIdx = min(ptCount - 2, ruleStep)
                let vCam = RoadHazardAnnotation()
                vCam.coordinate = pts[vIdx].coordinate
                vCam.kind = .violationCam
                vCam.title = language == .zhHant ? "違章抓拍（禁止壓實線變道）" : "违章抓拍（禁止压实线变道）"
                hazards.append(vCam)

                if !hasHighway && ptCount > 8 {
                    let rIdx = min(ptCount - 2, ruleStep * 2)
                    let rCam = RoadHazardAnnotation()
                    rCam.coordinate = pts[rIdx].coordinate
                    rCam.kind = .redLightCam
                    rCam.title = language == .zhHant ? "闖紅燈拍照預警" : "闯红灯拍照预警"
                    hazards.append(rCam)
                }

                let wIdx = min(ptCount - 2, ruleStep * 3)
                let warn = RoadHazardAnnotation()
                warn.coordinate = pts[wIdx].coordinate
                warn.kind = .trafficRuleWarn
                warn.speedLimitValue = detectedRouteLimit
                warn.title = language == .zhHant ? "交通規則預警：限速 \(detectedRouteLimit) · 禮讓行人" : "交通规则预警：限速 \(detectedRouteLimit) · 礼让行人"
                hazards.append(warn)
            }
            
            // Highway Service Areas & Toll Stations (Driving on Highway only)
            if hasHighway && travelMode == .driving {
                let hwName = route.name.isEmpty ? currentStepInstruction : route.name
                let (saNames, tollNames) = getHighwaySpecificServiceAndToll(for: hwName, distanceKm: route.distance / 1000.0)
                
                var saItems: [ServiceAreaInfo] = []
                for (i, name) in saNames.enumerated() {
                    let d = max(1500, Int(route.distance * (0.28 + Double(i) * 0.35)))
                    if d < Int(route.distance) {
                        saItems.append(ServiceAreaInfo(name: name, distanceMeters: d))
                        
                        let ptIndex = min(ptCount - 2, max(2, Int(Double(ptCount) * (0.28 + Double(i) * 0.35))))
                        let saAnno = RoadHazardAnnotation()
                        saAnno.coordinate = pts[ptIndex].coordinate
                        saAnno.kind = .serviceArea
                        saAnno.title = name
                        hazards.append(saAnno)
                    }
                }
                
                var tollItems: [TollStationInfo] = []
                for (i, name) in tollNames.enumerated() {
                    let d = max(800, Int(route.distance * (0.15 + Double(i) * 0.40)))
                    if d < Int(route.distance) {
                        tollItems.append(TollStationInfo(name: name, distanceMeters: d))
                        
                        let ptIndex = min(ptCount - 2, max(1, Int(Double(ptCount) * (0.15 + Double(i) * 0.40))))
                        let tollAnno = RoadHazardAnnotation()
                        tollAnno.coordinate = pts[ptIndex].coordinate
                        tollAnno.kind = .tollStation
                        tollAnno.title = name
                        hazards.append(tollAnno)
                    }
                }
                self.serviceAreasAlongRoute = saItems
                self.tollsAlongRoute = tollItems
            } else {
                self.serviceAreasAlongRoute = []
                self.tollsAlongRoute = []
            }
        } else {
            self.serviceAreasAlongRoute = []
            self.tollsAlongRoute = []
        }
        
        self.routeHazards = hazards
        if travelMode.supportsSpeedLimit && detectedRouteLimit > 0 {
            self.upcomingCameraDistance = max(120, min(650, Int(route.distance * 0.12)))
            self.upcomingCameraLimit = detectedRouteLimit
            self.speedLimitKmh = Double(detectedRouteLimit)
        } else {
            self.upcomingCameraDistance = 0
            self.upcomingCameraLimit = 0
            self.isOverspeeding = false
        }
        self.lastTraveledMeters = 0
        self.updateUpcomingServiceAreaAndToll(traveledMeters: 0)
    }
    

    private func getHighwaySpecificServiceAndToll(for roadName: String, distanceKm: Double) -> ([String], [String]) {
        let nameLower = roadName.lowercased()
        if nameLower.contains("广深") || nameLower.contains("沿江") || nameLower.contains("京港澳") {
            return (["福永服务区", "厚街服务区", "麻涌服务区"], ["同乐收费站", "厚街主线收费站"])
        } else if nameLower.contains("水官") || nameLower.contains("机荷") || nameLower.contains("沈海") {
            return (["白泥坑服务区", "龙岗服务区", "深汕服务区"], ["水官主线收费站", "荷坳收费站"])
        } else if nameLower.contains("外环") {
            return (["特利服务区", "光明服务区"], ["外环主线收费站"])
        } else if nameLower.contains("惠盐") || nameLower.contains("长深") || nameLower.contains("丹平") {
            return (["沙湾服务区", "大梅沙服务区"], ["沙湾主线收费站", "盐田收费站"])
        } else {
            return (["高速第一服务区", "高速第二服务区"], ["高速ETC收费站"])
        }
    }
    
    func updateUpcomingServiceAreaAndToll(traveledMeters: Int) {
        if let firstSA = serviceAreasAlongRoute.first(where: { !$0.isPassed }) {
            let remain = max(0, firstSA.distanceMeters - traveledMeters)
            if remain <= 50 {
                if let idx = serviceAreasAlongRoute.firstIndex(where: { $0.id == firstSA.id }) {
                    serviceAreasAlongRoute[idx].isPassed = true
                }
                updateUpcomingServiceAreaAndToll(traveledMeters: traveledMeters)
                return
            }
            self.upcomingServiceAreaName = firstSA.name
            self.upcomingServiceAreaDist = remain
        } else {
            self.upcomingServiceAreaName = ""
            self.upcomingServiceAreaDist = 0
        }
        
        if let firstToll = tollsAlongRoute.first(where: { !$0.isPassed }) {
            let remain = max(0, firstToll.distanceMeters - traveledMeters)
            if remain <= 50 {
                if let idx = tollsAlongRoute.firstIndex(where: { $0.id == firstToll.id }) {
                    tollsAlongRoute[idx].isPassed = true
                }
                updateUpcomingServiceAreaAndToll(traveledMeters: traveledMeters)
                return
            }
            self.upcomingTollName = firstToll.name
            self.upcomingTollDistance = remain
        } else {
            self.upcomingTollName = ""
            self.upcomingTollDistance = 0
        }
    }

    private func triggerDepartureGreeting(title: String = "", isReroute: Bool = false) {
        let modeName = self.travelMode.title(self.language)
        if isReroute {
            let base = self.activeBaseId()
            let modeOff = self.activeModeOffset()
            self.playVoice(id: base + modeOff + 43, customQuote: "🔄 [\(modeName)] リルート完了！新しいルートで案内するよ！")
        } else {
            let base = self.activeBaseId()
            let modeOff = self.activeModeOffset()
            let destText = title.isEmpty ? self.destinationName : title
            let quote: String
            switch self.travelMode {
            case .driving:
                quote = "🚗 [\(modeName)·\(routePreference.title(language))] ルート案内開始！目的地: \(destText)"
            case .ebike:
                quote = "🛵 [\(modeName)·非机动车道优先] 安全運転で出発！目的地: \(destText)"
            case .walking:
                quote = "🚶 [\(modeName)·人行步道] のんびり歩いて行こう！目的地: \(destText)"
            case .transit:
                quote = "🚌 [\(modeName)] 公共交通・乗り換え案内開始！目的地: \(destText)"
            }
            self.enqueueVoiceCombo([
                (base + modeOff + 39, quote),
                (base + modeOff + 47, "🚦 実際の交通規制に従って、安全に移動してね！")
            ])
        }
    }
    
    func stopRouteGuidance() {
        stopDemoSimulation()
        activeRoute = nil
        customTransitPolyline = nil
        transitStopAnnotations = []
        isNavigatingFocused = false
        candidateRoutes = []
        routeHazards = []
        upcomingTollDistance = 0
        upcomingServiceAreaDist = 0
        destinationCoord = nil
        destinationName = ""
        initialRouteOriginCoordinate = nil
        consecutiveOffRouteCount = 0
        lastRoutePerpendicularDistance = 0.0
        currentStepInstruction = ""
        distanceToNextStepMeters = 0.0
        remainingRouteDistanceKm = 0.0
        remainingRouteMinutes = 0
        transitPhase = .idle
        rawTransitPlans.removeAll()
        transitPlans.removeAll()
        showTransitPlanSheet = false
        announcedStepThresholds.removeAll()
        isRecalculatingRoute = false
        consecutiveOffRouteCount = 0
        // Stay on enlarged navigation map page (never shrink to cockpit automatically!)
        let base = activeBaseId()
        let modeOff = activeModeOffset()
        playVoice(id: base + modeOff + 38, customQuote: "🏁 これで音声案内は終了だよ！運転お疲れ様♪")
    }
    
    // MARK: - Geometric Turn Verification & Segment-Aware Step Tracking
    private func bearingDegrees(from a: CLLocationCoordinate2D, to b: CLLocationCoordinate2D) -> Double {
        let lat1 = a.latitude * .pi / 180.0
        let lat2 = b.latitude * .pi / 180.0
        let dLon = (b.longitude - a.longitude) * .pi / 180.0
        let y = sin(dLon) * cos(lat2)
        let x = cos(lat1) * sin(lat2) - sin(lat1) * cos(lat2) * cos(dLon)
        let deg = atan2(y, x) * 180.0 / .pi
        return (deg + 360.0).truncatingRemainder(dividingBy: 360.0)
    }

    private func normalizedAngleDelta(_ delta: Double) -> Double {
        var d = delta.truncatingRemainder(dividingBy: 360.0)
        if d > 180.0 { d -= 360.0 }
        if d < -180.0 { d += 360.0 }
        return d
    }

    private func geometricTurnAngle(from prevStep: MKRoute.Step?, to nextStep: MKRoute.Step?) -> Double? {
        guard let pStep = prevStep, let nStep = nextStep else { return nil }
        let pPts = pStep.polyline.points()
        let pCount = pStep.polyline.pointCount
        let nPts = nStep.polyline.points()
        let nCount = nStep.polyline.pointCount
        guard pCount >= 2, nCount >= 2 else { return nil }

        let junction = pPts[pCount - 1].coordinate
        var inStart = pPts[pCount - 2].coordinate
        for i in stride(from: pCount - 2, through: 0, by: -1) {
            let c = pPts[i].coordinate
            let d = CLLocation(latitude: c.latitude, longitude: c.longitude).distance(from: CLLocation(latitude: junction.latitude, longitude: junction.longitude))
            inStart = c
            if d >= 12.0 { break }
        }

        let outStart = nPts[0].coordinate
        var outEnd = nPts[1].coordinate
        for i in 1..<nCount {
            let c = nPts[i].coordinate
            let d = CLLocation(latitude: outStart.latitude, longitude: outStart.longitude).distance(from: CLLocation(latitude: c.latitude, longitude: c.longitude))
            outEnd = c
            if d >= 12.0 { break }
        }

        let inB = bearingDegrees(from: inStart, to: junction)
        let outB = bearingDegrees(from: outStart, to: outEnd)
        return normalizedAngleDelta(outB - inB)
    }

    private func verifiedTurnInstruction(raw: String, prevStep: MKRoute.Step?, nextStep: MKRoute.Step?) -> String {
        var text = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let angle = geometricTurnAngle(from: prevStep, to: nextStep) else {
            return text
        }
        let lower = text.lowercased()
        let saysRight = lower.contains("右") || lower.contains("right")
        let saysLeft = lower.contains("左") || lower.contains("left")

        if angle <= -40.0 && angle > -155.0 {
            if saysRight && !saysLeft {
                text = text
                    .replacingOccurrences(of: "轉右", with: "轉左")
                    .replacingOccurrences(of: "转右", with: "转左")
                    .replacingOccurrences(of: "右轉", with: "左轉")
                    .replacingOccurrences(of: "右转", with: "左转")
                    .replacingOccurrences(of: "向右", with: "向左")
                    .replacingOccurrences(of: "Right", with: "Left")
                    .replacingOccurrences(of: "right", with: "left")
            }
        } else if angle >= 40.0 && angle < 155.0 {
            if saysLeft && !saysRight {
                text = text
                    .replacingOccurrences(of: "轉左", with: "轉右")
                    .replacingOccurrences(of: "转左", with: "转右")
                    .replacingOccurrences(of: "左轉", with: "右轉")
                    .replacingOccurrences(of: "左转", with: "右转")
                    .replacingOccurrences(of: "向左", with: "向右")
                    .replacingOccurrences(of: "Left", with: "Right")
                    .replacingOccurrences(of: "left", with: "right")
            }
        }
        return text
    }

    private func distanceAlongStepPolyline(_ step: MKRoute.Step, from coord: CLLocationCoordinate2D) -> (perpDist: Double, remainDist: Double, traveledDist: Double) {
        let pts = step.polyline.points()
        let ptCount = step.polyline.pointCount
        guard ptCount >= 2 else {
            if ptCount == 1 {
                let p = pts[0].coordinate
                let d = CLLocation(latitude: coord.latitude, longitude: coord.longitude).distance(from: CLLocation(latitude: p.latitude, longitude: p.longitude))
                return (d, d, 0.0)
            }
            return (999999.0, 0.0, 0.0)
        }
        var bestDist: Double = 999999.0
        var bestSegIdx: Int = 0
        var bestProj: CLLocationCoordinate2D = pts[0].coordinate
        for i in 0..<(ptCount - 1) {
            let a = pts[i].coordinate
            let b = pts[i + 1].coordinate
            let (proj, d, _) = projectPointOntoSegment(p: coord, a: a, b: b)
            if d < bestDist {
                bestDist = d
                bestSegIdx = i
                bestProj = proj
            }
        }
        var traveled = 0.0
        for i in 0..<bestSegIdx {
            let a = pts[i].coordinate
            let b = pts[i + 1].coordinate
            traveled += CLLocation(latitude: a.latitude, longitude: a.longitude).distance(from: CLLocation(latitude: b.latitude, longitude: b.longitude))
        }
        traveled += CLLocation(latitude: pts[bestSegIdx].coordinate.latitude, longitude: pts[bestSegIdx].coordinate.longitude)
            .distance(from: CLLocation(latitude: bestProj.latitude, longitude: bestProj.longitude))

        var remain = CLLocation(latitude: bestProj.latitude, longitude: bestProj.longitude)
            .distance(from: CLLocation(latitude: pts[bestSegIdx + 1].coordinate.latitude, longitude: pts[bestSegIdx + 1].coordinate.longitude))
        for i in (bestSegIdx + 1)..<(ptCount - 1) {
            let a = pts[i].coordinate
            let b = pts[i + 1].coordinate
            remain += CLLocation(latitude: a.latitude, longitude: a.longitude).distance(from: CLLocation(latitude: b.latitude, longitude: b.longitude))
        }
        return (bestDist, remain, traveled)
    }

    // Real-Time Turn-by-Turn GPS Step Evaluation
    private func updateNavigationProgress(location: CLLocation) {
        guard let route = activeRoute, !route.steps.isEmpty else { return }
        let steps = route.steps
        guard currentStepIndex < steps.count else { return }

        // Advance to the next step ONLY after the user has actually turned at the junction and traveled >= 6m onto the next step polyline!
        var activeSeg = currentStepIndex
        var activeEval = distanceAlongStepPolyline(steps[activeSeg], from: userCoordinate)
        let searchUpper = min(steps.count - 1, currentStepIndex + 2)
        if activeSeg < searchUpper {
            for candIdx in (activeSeg + 1)...searchUpper {
                let candStep = steps[candIdx]
                let candEval = distanceAlongStepPolyline(candStep, from: userCoordinate)
                let minEnterDist = min(6.5, max(2.5, candStep.distance * 0.25))
                if candEval.traveledDist >= minEnterDist && candEval.perpDist <= 28.0 && (candEval.perpDist <= activeEval.perpDist + 4.0 || activeEval.remainDist <= 8.0) {
                    activeSeg = candIdx
                    activeEval = candEval
                    break
                }
            }
        }
        if activeSeg > currentStepIndex {
            currentStepIndex = activeSeg
            let newStep = steps[currentStepIndex]
            let newInstr = newStep.instructions.trimmingCharacters(in: .whitespacesAndNewlines)
            let enterKey = "\(currentStepIndex)_ENTER"
            if !newInstr.isEmpty && !announcedStepThresholds.contains(enterKey) {
                announcedStepThresholds.insert(enterKey)
                let turnM = classifyTurnOffsetM(from: newInstr)
                let base = activeBaseId()
                let modeOff = activeModeOffset()
                enqueueVoiceCombo([
                    (base + modeOff + turnM, "↪️ \(newInstr)")
                ])
            }
        }

        let step = steps[currentStepIndex]
        let dist = activeEval.remainDist
        self.distanceToNextStepMeters = dist

        let nextStep = (currentStepIndex + 1 < steps.count) ? steps[currentStepIndex + 1] : nil
        let rawStepInstr = step.instructions.isEmpty
            ? (currentStepIndex == steps.count - 1
               ? (language == .en ? "Arrive at \(destinationName)" : (language == .zhHant ? "即將到達目的地：\(destinationName)" : "即将到达目的地：\(destinationName)"))
               : (nextStep?.instructions ?? destinationName))
            : step.instructions
        let verifiedInstr = verifiedTurnInstruction(raw: rawStepInstr, prevStep: step, nextStep: nextStep)
        if !verifiedInstr.isEmpty && self.currentStepInstruction != verifiedInstr {
            self.currentStepInstruction = verifiedInstr
            self.updateRoadLanes(for: verifiedInstr)
            self.evaluateRoadSpeedLimitAndNotify(for: verifiedInstr)
        }
        
        // Dynamically update remaining route distance, ETA minutes, camera distance, and highway SA/Toll distances!
        let futureStepsDist = steps.dropFirst(currentStepIndex + 1).reduce(0.0) { $0 + $1.distance }
        let totalRemainMeters = max(0.0, dist + futureStepsDist)
        self.remainingRouteDistanceKm = totalRemainMeters / 1000.0
        if route.distance > 0 {
            let ratio = max(0.02, min(1.0, totalRemainMeters / route.distance))
            if self.travelMode != .transit {
                let totalSec = self.realisticTravelSeconds(for: route)
                self.remainingRouteMinutes = max(1, Int(((totalSec * ratio) / 60.0).rounded()))
            }
            let traveledM = max(0, Int(route.distance - totalRemainMeters))
            self.updateUpcomingServiceAreaAndToll(traveledMeters: traveledM)
        }
        
        // 1. TRANSIT MULTI-PHASE STATE MACHINE (GaoDe 1:1 Lifecycle!)
        if self.travelMode == .transit {
            if self.transitPhase == .walkingToStation {
                // Reached boarding station: Auto-transition to In-Vehicle Mode!
                if dist <= 45.0 {
                    self.transitPhase = .inTransitVehicle
                    self.customTransitPolyline = nil
                    self.currentStepIndex = 0
                    if let dest = self.destinationCoord, let boardCoord = self.transitBoardingStationCoord {
                        let busReq = MKDirections.Request()
                        busReq.source = MKMapItem(placemark: MKPlacemark(coordinate: boardCoord))
                        busReq.destination = MKMapItem(placemark: MKPlacemark(coordinate: dest))
                        busReq.transportType = .automobile
                        MKDirections(request: busReq).calculate { [weak self] resp, _ in
                            DispatchQueue.main.async {
                                guard let self = self else { return }
                                if let r = resp?.routes.first {
                                    self.activeRoute = r
                                    self.customTransitPolyline = nil
                                }
                            }
                        }
                    }
                    let line = self.transitActiveLineName.isEmpty ? "公交/地铁" : self.transitActiveLineName
                    let nextSt = self.transitPassStationsList.first ?? self.transitAlightStationName
                    let remStops = max(1, self.transitPassStationsList.count)
                    self.currentStepInstruction = "乘坐 \(line) · 下一站: \(nextSt) (还有 \(remStops) 站)"
                    
                    let boardMsg = "🎉 已到达 [\(self.transitBoardingStationName)]！请上车乘坐 [\(line)]！"
                    self.playVoice(id: self.activeBaseId() + 39, customQuote: boardMsg, clearQueue: true)
                    return
                }
            } else if self.transitPhase == .walkingToDestination {
                // Reached final destination on foot after transit!
                if currentStepIndex == steps.count - 1 && dist <= 35.0 {
                    let base = activeBaseId()
                    let modeOff = activeModeOffset()
                    enqueueVoiceCombo([
                        (base + modeOff + 37, "🎉 顺利到达目的地！(\(destinationName))"),
                        (base + modeOff + 38, "✨ 全程导航已完成！辛苦啦♪")
                    ])
                    self.activeRoute = nil
                    self.customTransitPolyline = nil
                    self.destinationCoord = nil
                    self.destinationName = ""
                    self.transitPhase = .idle
                    self.currentStepInstruction = "已到达目的地"
                    return
                }
            }
        }
        
        // 2. DRIVING / E-BIKE / WALKING: Final Destination Arrival
        if self.travelMode != .transit && currentStepIndex == steps.count - 1 && dist <= 40.0 {
            let base = activeBaseId()
            let modeOff = activeModeOffset()
            enqueueVoiceCombo([
                (base + modeOff + 37, "🎉 目的地周辺に到着したよ！(\(destinationName))"),
                (base + modeOff + 38, "✨ これで音声案内は終了だよ！お疲れ様でした♪")
            ])
            // Cancel active route but stay on enlarged navigation page!
            self.activeRoute = nil
            self.destinationCoord = nil
            self.destinationName = ""
            self.currentStepInstruction = "已到达目的地"
            return
        }
        
        // 3. OFF-ROUTE DYNAMIC REROUTING (快速响应偏航重规划：支持48m连续2次或80m立即重规划，且放宽GPS精度到100m!)
        if (hasActiveNavigation || isNavigatingFocused) && !isRecalculatingRoute && travelMode != .transit, let dest = destinationCoord {
            let rawMapCoord = CoordinateConverter.wgs84ToGCJ02(location.coordinate)
            let pts = route.polyline.points()
            let ptCount = route.polyline.pointCount
            var minSegDist: Double = 999999.0
            if ptCount >= 2 {
                for i in 0..<(ptCount - 1) {
                    let (_, d, _) = projectPointOntoSegment(p: rawMapCoord, a: pts[i].coordinate, b: pts[i + 1].coordinate)
                    if d < minSegDist { minSegDist = d }
                }
            } else {
                minSegDist = lastRoutePerpendicularDistance
            }

            let offThreshold: Double = (travelMode == .walking) ? 22.0 : ((travelMode == .ebike) ? 26.0 : 30.0)
            if location.horizontalAccuracy >= 0 && location.horizontalAccuracy <= 100.0 && minSegDist > offThreshold {
                consecutiveOffRouteCount += (minSegDist > 42.0 ? 2 : 1)
            } else {
                consecutiveOffRouteCount = 0
            }

            if consecutiveOffRouteCount >= 2 && Date().timeIntervalSince(lastRerouteTime) > 3.5 {
                consecutiveOffRouteCount = 0
                lastRerouteTime = Date()
                let rerouteMsg = "🔄 你已偏离路线，正在为您重新规划路线..."
                playVoice(id: activeBaseId() + 43, customQuote: rerouteMsg, clearQueue: true)
                calculateAndStartRoute(to: dest, title: destinationName, isReroute: true)
                return
            }
        }
        
        let thresholds: [(minD: Double, maxD: Double, distM: Int, label: String)] = [
            (720, 1120, 5, "およそ1km先"),
            (360, 580, 10, "およそ500m先"),
            (170, 355, 12, "およそ300m先"),
            (60, 165, 14, "およそ100m先"),
            (0, 59, 15, "まもなく")
        ]
        
        for th in thresholds {
            let key = "\(currentStepIndex)_\(th.distM)"
            if dist >= th.minD && dist <= th.maxD && !announcedStepThresholds.contains(key) {
                announcedStepThresholds.insert(key)
                let voiceInstr = verifiedInstr.isEmpty ? step.instructions : verifiedInstr
                let turnM = classifyTurnOffsetM(from: voiceInstr)
                let base = activeBaseId()
                let modeOff = activeModeOffset()
                enqueueVoiceCombo([
                    (base + th.distM, "📍 \(th.label) (\(Int(dist))m)"),
                    (base + modeOff + turnM, "↪️ \(voiceInstr)")
                ])
                break
            }
        }
        
        // Step advancement is handled by segment projection above so banner never jumps past the upcoming turn prematurely.
    }
    
    private func classifyTurnOffsetM(from text: String) -> Int {
        let lower = text.lowercased()
        if lower.contains("调头") || lower.contains("掉头") || lower.contains("u-turn") || lower.contains("u turn") {
            return 21
        }
        if lower.contains("出口") || lower.contains("驶出") || lower.contains("exit") {
            return 20
        }
        if lower.contains("入口") || lower.contains("驶入") || lower.contains("匯入") || lower.contains("汇入") || lower.contains("merge") || lower.contains("ramp") {
            return 19
        }
        if lower.contains("稍向右") || lower.contains("靠右") || lower.contains("右前方") || lower.contains("slight right") || lower.contains("keep right") {
            return 30
        }
        if lower.contains("稍向左") || lower.contains("靠左") || lower.contains("左前方") || lower.contains("slight left") || lower.contains("keep left") {
            return 31
        }
        if lower.contains("右后") || lower.contains("sharp right") {
            return 32
        }
        if lower.contains("左后") || lower.contains("sharp left") {
            return 33
        }
        if lower.contains("右") || lower.contains("right") {
            return 28
        }
        if lower.contains("左") || lower.contains("left") {
            return 29
        }
        return 16
    }
    
    // MARK: - Live Demo Navigation Simulator
    func toggleDemoSimulation() {
        if isDemoSimulating {
            stopDemoSimulation()
        } else {
            startDemoSimulation()
        }
    }
    
    func startDemoSimulation() {
        stopDemoSimulation()
        isDemoSimulating = true
        // Keep user's current view mode (works seamlessly in compact cockpit or enlarged full-screen)
        destinationName = language == .en ? "Sakuragaoka High Music Room" : "樱丘高中轻音部部室 (模拟导航)"
        currentStepInstruction = language == .en ? "In 300m, Turn Right" : "前方 300 米右转进入樱高大道"
        updateRoadLanes(for: currentStepInstruction)
        distanceToNextStepMeters = 300
        currentSpeedKmh = 48.0
        upcomingCameraDistance = 280
        upcomingCameraLimit = Int(speedLimitKmh)
        upcomingTollDistance = 850
        upcomingServiceAreaDist = 2400
        upcomingServiceAreaName = "樱丘高速服务区(SA)"
        congestionStatusText = "前方道路畅通"
        isCongested = false
        
        let base = activeBaseId()
        let modeOff = activeModeOffset()
        
        enqueueVoiceCombo([
            (base + modeOff + 39, "🚗 ルート案内を始めるよ！ドライブ楽しみだな〜"),
            (base + 12, "📍 およそ 300m先 (前方300米)"),
            (base + modeOff + 28, "↪️ 右方向に行きまーす！対向車に注意してね！")
        ])
        
        var stepCounter = 0
        let timer = Timer(timeInterval: 9.0, repeats: true) { [weak self] _ in
            guard let self = self, self.isDemoSimulating else { return }
            stepCounter += 1
            let b = self.activeBaseId()
            let mOff = self.activeModeOffset()
            
            self.headingDegrees = (self.headingDegrees + 35.0).truncatingRemainder(dividingBy: 360.0)
            self.upcomingCameraDistance = max(50, self.upcomingCameraDistance - 90)
            self.userCoordinate = CLLocationCoordinate2D(
                latitude: self.userCoordinate.latitude + 0.0006,
                longitude: self.userCoordinate.longitude + 0.0006
            )
            self.tripDistanceKm += 0.1
            
            switch stepCounter {
            case 1:
                self.distanceToNextStepMeters = 100
                self.currentStepInstruction = self.language == .en ? "In 100m, Turn Left" : "前方 100 米左转进入商业街"
                self.updateRoadLanes(for: self.currentStepInstruction)
                self.evaluateRoadSpeedLimitAndNotify(for: "商业街辅路")
                self.upcomingTollDistance = max(0, self.upcomingTollDistance - 350)
                self.enqueueVoiceCombo([
                    (b + 14, "📍 およそ 100m先 (前方100米)"),
                    (b + mOff + 29, "↩️ 左方向に行きまーす！巻き込みに注意してね！")
                ])
            case 2:
                self.distanceToNextStepMeters = 30
                self.currentStepInstruction = self.language == .en ? "Soon, Enter Expressway" : "即将驶入高速道路入口(靠右)"
                self.updateRoadLanes(for: self.currentStepInstruction)
                self.evaluateRoadSpeedLimitAndNotify(for: "高速道路")
                self.upcomingTollDistance = 180
                self.enqueueVoiceCombo([
                    (b + 15, "📍 まもなく (即将到达路口)"),
                    (b + mOff + 19, "🛣️ 入口だよ！合流に注意してね！")
                ])
            case 3:
                self.distanceToNextStepMeters = 0
                self.currentStepInstruction = self.language == .en ? "Arrived at Destination!" : "已到达终点：轻音部部室！"
                self.enqueueVoiceCombo([
                    (b + mOff + 37, "🎉 目的地周辺に到着したよ！"),
                    (b + mOff + 38, "✨ これで音声案内は終了だよ！お疲れ様♪")
                ])
                DispatchQueue.main.asyncAfter(deadline: .now() + 8.0) {
                    self.stopDemoSimulation()
                }
            default:
                break
            }
        }
        RunLoop.main.add(timer, forMode: .common)
        self.demoSimTimer = timer
    }
    
    func stopDemoSimulation() {
        isDemoSimulating = false
        demoSimTimer?.invalidate()
        demoSimTimer = nil
        if activeRoute == nil && destinationCoord == nil {
            currentStepInstruction = ""
            distanceToNextStepMeters = 0
            currentSpeedKmh = 0
        }
    }
    
    private var smoothedSpeedKmh: Double = 0.0
    private var consecutiveLowSpeedFixes: Int = 0
    private var lastValidSpeedTimestamp: Date = .distantPast

    // MARK: - CLLocationManagerDelegate
    func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        guard let loc = locations.last else { return }
        
        DispatchQueue.main.async {
            if !self.isDemoSimulating {
                // If MKMapView has not yet provided its map-aligned userLocation, align via wgs84ToGCJ02 (no-op Overseas/HK/Macau, GCJ-02 in Mainland).
                // Once MKMapView is active (hasMapUserLocation == true), MKMapView.didUpdateUserLocation keeps userCoordinate 100% locked to the map tiles!
                if !self.hasMapUserLocation {
                    self.userCoordinate = CoordinateConverter.wgs84ToGCJ02(loc.coordinate)
                }
                
                // Auto-refresh transit plans if user moved to a new station location!
                if self.travelMode == .transit {
                    self.refreshTransitPlansForCurrentLocation(force: false)
                }
            }
            self.gpsAccuracyMeters = loc.horizontalAccuracy
            
            if loc.horizontalAccuracy < 0 || loc.horizontalAccuracy > 85.0 {
                if !self.isGPSSignalPoor {
                    self.isGPSSignalPoor = true
                    if self.hasActiveNavigation && self.currentSpeedKmh > 3.0 && Date().timeIntervalSince(self.lastGPSAlertTime) > 120.0 {
                        self.lastGPSAlertTime = Date()
                        self.triggerGPSSignalPoorAlert()
                    }
                }
                return
            } else {
                if self.isGPSSignalPoor {
                    self.isGPSSignalPoor = false
                    if self.hasActiveNavigation && self.currentSpeedKmh > 3.0 {
                        self.triggerGPSSignalRecovered()
                    }
                }
                self.lastValidGPSTime = Date()
            }
            
            var movedDelta: Double = 0.0
            var dtSec: Double = 1.0
            if let prev = self.lastLocation {
                dtSec = max(0.05, loc.timestamp.timeIntervalSince(prev.timestamp))
                if prev.horizontalAccuracy >= 0 && prev.horizontalAccuracy <= 50 {
                    let delta = loc.distance(from: prev)
                    movedDelta = delta
                    if self.hasActiveNavigation && delta > 1.5 && delta < 500 {
                        self.tripDistanceKm += delta / 1000.0
                    }
                }
            }
            self.lastLocation = loc
            
            // Smooth Doppler GPS speed with EMA & anti-zero-jump hysteresis (no false 0 drops on sub-second callbacks!)
            if !self.isDemoSimulating {
                let now = Date()
                var sampleKmh: Double? = nil
                if loc.horizontalAccuracy > 0 && loc.horizontalAccuracy <= 50.0 {
                    if loc.speed >= 0.0 {
                        sampleKmh = min(260.0, max(0.0, loc.speed * 3.6))
                    } else if dtSec >= 0.8 && loc.horizontalAccuracy <= 25.0 && movedDelta >= 2.0 && movedDelta <= 80.0 * dtSec {
                        sampleKmh = min(260.0, (movedDelta / dtSec) * 3.6)
                    }
                }
                let filteredKmh = (sampleKmh != nil && sampleKmh! < 6.5 && movedDelta < 2.2 && loc.horizontalAccuracy > 12.0) ? 0.0 : sampleKmh
                if let sKmh = filteredKmh {
                    if sKmh < 3.0 {
                        self.consecutiveLowSpeedFixes += 1
                        if self.consecutiveLowSpeedFixes >= 2 || self.smoothedSpeedKmh < 6.0 {
                            self.smoothedSpeedKmh = 0.0
                        }
                    } else {
                        self.consecutiveLowSpeedFixes = 0
                        if self.smoothedSpeedKmh < 1.0 || abs(sKmh - self.smoothedSpeedKmh) > 12.0 {
                            self.smoothedSpeedKmh = sKmh
                        } else {
                            self.smoothedSpeedKmh = self.smoothedSpeedKmh * 0.25 + sKmh * 0.75
                        }
                        self.lastValidSpeedTimestamp = now
                    }
                } else if now.timeIntervalSince(self.lastValidSpeedTimestamp) > 2.5 {
                    self.smoothedSpeedKmh = 0.0
                }
                self.currentSpeedKmh = Foundation.round(self.smoothedSpeedKmh)
            }
            
            // TRANSIT NAVIGATION AUTO-SWITCH ENGINE (GaoDe 1:1 Lifecycle!)
            if self.travelMode == .transit && self.transitPhase != .idle {
                if self.transitPhase == .walkingToStation, let bCoord = self.transitBoardingStationCoord {
                    let distToStation = loc.distance(from: CLLocation(latitude: bCoord.latitude, longitude: bCoord.longitude))
                    self.distanceToNextStepMeters = distToStation
                    
                    // Arrived at station (< 55m) or boarded vehicle (speed > 16 km/h) -> Auto-switch to In-Vehicle Mode!
                    if distToStation <= 55.0 || self.currentSpeedKmh > 16.0 {
                        self.transitPhase = .inTransitVehicle
                        self.transitCurrentStationIndex = 0
                        let line = self.transitActiveLineName.isEmpty ? "公交/地铁" : self.transitActiveLineName
                        let nextSt = self.transitPassStationsList.first ?? self.transitAlightStationName
                        let remStops = max(1, self.transitPassStationsList.count)
                        self.currentStepInstruction = "乘坐 \(line) · 下一站: \(nextSt) (还有 \(remStops) 站)"
                        
                        let boardMsg = "🎉 已到达 [\(self.transitBoardingStationName)]！请上车乘坐 [\(line)]！"
                        self.playVoice(id: self.activeBaseId() + 39, customQuote: boardMsg, clearQueue: true)
                    }
                } else if self.transitPhase == .inTransitVehicle {
                    // In transit vehicle: Track stations along the line!
                    let totalStops = self.transitPassStationsList.count
                    if totalStops > 0 {
                        let stepFraction = min(0.99, max(0.0, self.tripDistanceKm / max(1.0, self.remainingRouteDistanceKm)))
                        let currIdx = min(totalStops - 1, Int(stepFraction * Double(totalStops)))
                        self.transitCurrentStationIndex = currIdx
                        
                        let currSt = self.transitPassStationsList[currIdx]
                        let nextSt = (currIdx < totalStops - 1) ? self.transitPassStationsList[currIdx + 1] : self.transitAlightStationName
                        let remStops = max(1, totalStops - currIdx)
                        self.currentStepInstruction = "\(self.transitActiveLineName) · 当前: \(currSt) ➔ 下一站: \(nextSt) (还有 \(remStops) 站)"
                        
                        // Destination station arrival warning & Alight Transition!
                        if remStops <= 1 {
                            let arriveMsg = "🔔 即将到达下车站 [\(self.transitAlightStationName)]，请提前做好下车准备！"
                            if !self.announcedStepThresholds.contains("TRANSIT_ALIGHT_SOON") {
                                self.announcedStepThresholds.insert("TRANSIT_ALIGHT_SOON")
                                self.playVoice(id: self.activeBaseId() + 39, customQuote: arriveMsg, clearQueue: true)
                            }
                        }
                        
                        // When at alight station: Automatically trigger final pedestrian walking leg to destination!
                        if currIdx == totalStops - 1 || remStops <= 1 {
                            let alightMsg = "🔔 已到达下车站 [\(self.transitAlightStationName)]！正在为您开启出站后末段步行导航..."
                            if !self.announcedStepThresholds.contains("TRANSIT_ALIGHT_NOW") {
                                self.announcedStepThresholds.insert("TRANSIT_ALIGHT_NOW")
                                self.playVoice(id: self.activeBaseId() + 39, customQuote: alightMsg, clearQueue: true)
                                self.startFinalTransitWalkingLeg()
                            }
                        }
                    }
                }
            }
            if self.currentSpeedKmh > self.maxSpeedKmh {
                self.maxSpeedKmh = self.currentSpeedKmh
            }
            
            if self.hasActiveNavigation && self.travelMode.supportsSpeedLimit && self.speedLimitKmh > 0 && self.currentSpeedKmh > self.speedLimitKmh {
                self.isOverspeeding = true
                if Date().timeIntervalSince(self.lastOverspeedAlertTime) > 25.0 {
                    self.lastOverspeedAlertTime = Date()
                    self.triggerOverspeedAlert()
                }
            } else {
                self.isOverspeeding = false
            }
            
            let rawMapCoord = CoordinateConverter.wgs84ToGCJ02(loc.coordinate)
            self.updateSnappedRouteCoordinate(for: rawMapCoord)
            if let snapped = self.snappedRouteCoordinate {
                self.userCoordinate = snapped
                if let snapH = self.snappedRouteHeading, self.currentSpeedKmh > 2.0 {
                    self.headingDegrees = snapH
                }
            } else if loc.horizontalAccuracy >= 0 && loc.horizontalAccuracy <= 65.0 {
                self.userCoordinate = rawMapCoord
            }
            self.updateNavigationProgress(location: loc)
        }
    }
    
    func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) {
        DispatchQueue.main.async {
            if !self.isGPSSignalPoor && !self.isDemoSimulating {
                self.isGPSSignalPoor = true
                if self.hasActiveNavigation && self.currentSpeedKmh > 3.0 && Date().timeIntervalSince(self.lastGPSAlertTime) > 120.0 {
                    self.lastGPSAlertTime = Date()
                    self.triggerGPSSignalPoorAlert()
                }
            }
        }
    }
    
    func locationManager(_ manager: CLLocationManager, didUpdateHeading newHeading: CLHeading) {
        guard newHeading.headingAccuracy >= 0 else { return }
        let rawH = newHeading.trueHeading >= 0 ? newHeading.trueHeading : newHeading.magneticHeading
        DispatchQueue.main.async {
            // If actively riding/driving along a snapped route, prefer the smooth route tangent heading!
            if let snapH = self.snappedRouteHeading, self.hasActiveNavigation, self.currentSpeedKmh > 3.0 {
                self.headingDegrees = snapH
                return
            }
            var diff = abs(rawH - self.headingDegrees).truncatingRemainder(dividingBy: 360.0)
            if diff > 180.0 { diff = 360.0 - diff }
            // Anti-jitter deadband: require 18° change when stationary (0 km/h) so launch arrow never jitters!
            let minThreshold: Double = (self.currentSpeedKmh < 1.8 && !self.isDemoSimulating) ? 18.0 : 3.5
            if diff >= minThreshold {
                self.headingDegrees = rawH
            }
        }
    }
    
    // MARK: - Voice Queue & Playback
    func enqueueVoiceCombo(_ items: [(id: Int, quote: String)]) {
        guard !items.isEmpty else { return }
        voiceQueue = Array(items.dropFirst())
        playVoice(id: items[0].id, customQuote: items[0].quote, clearQueue: false)
    }
    
    func playVoice(id: Int, customQuote: String? = nil, clearQueue: Bool = true) {
        if UIApplication.shared.applicationState != .active && !hasActiveNavigation && !isCruiseModeActive {
            return
        }
        if clearQueue { voiceQueue.removeAll() }
        let safeId = (id < 157) ? (157 + (id % 144)) : id
        guard safeId >= 1 && safeId <= navIndexTable.count else { return }
        guard let handle = navFileHandle else { return }
        
        let entry = navIndexTable[safeId - 1]
        let absoluteOffset = navPayloadStart + UInt64(entry.offset)
        
        do {
            try handle.seek(toOffset: absoluteOffset)
            guard let combinedChunk = try handle.read(upToCount: Int(entry.length)), combinedChunk.count == Int(entry.length) else { return }
            let sealedBox = try AES.GCM.SealedBox(combined: combinedChunk)
            let decryptedAudioData = try AES.GCM.open(sealedBox, using: self.symmetricKey)
            
            audioPlayer?.stop()
            audioPlayer = try AVAudioPlayer(data: decryptedAudioData)
            audioPlayer?.delegate = self
            audioPlayer?.prepareToPlay()
            audioPlayer?.play()
            KOnMusicManager.shared.duckForVoice(duck: true)
            
            let spkFilter = characterForVoiceId(safeId)
            let speaker = spkFilter.displayName(language)
            let text = customQuote ?? defaultQuoteForVoiceId(safeId)
            DispatchQueue.main.async {
                if spkFilter != .all {
                    self.activeAllMemberChar = spkFilter
                } else {
                    self.activeAllMemberChar = CharacterFilter.fiveIndividuals.randomElement() ?? .yui
                }
                self.isPlaying = true
                self.currentPlayingId = safeId
                self.currentSpeechBubble = "[\(speaker)] \(text) (#\(safeId))"
            }
        } catch {
            print("Failed to play nav voice \(safeId): \(error)")
        }
    }
    
    func playMascotVoice(for character: CharacterFilter? = nil, customQuote: String? = nil) {
        if UIApplication.shared.applicationState != .active && !hasActiveNavigation && !isCruiseModeActive {
            return
        }
        voiceQueue.removeAll()
        guard let handle = mascotFileHandle, !mascotVoices.isEmpty else { return }
        let targetChar = character ?? selectedCharacter
        let matching: [MascotVoiceEntry]
        if targetChar == .all {
            matching = mascotVoices
        } else {
            matching = mascotVoices.filter { $0.charId == targetChar.charId }
        }
        guard let chosen = matching.randomElement() else { return }
        
        do {
            try handle.seek(toOffset: mascotPayloadStart + UInt64(chosen.offset))
            guard let chunk = try handle.read(upToCount: Int(chosen.length)), chunk.count == Int(chosen.length) else { return }
            let box = try AES.GCM.SealedBox(combined: chunk)
            let audioData = try AES.GCM.open(box, using: self.symmetricKey)
            
            audioPlayer?.stop()
            audioPlayer = try AVAudioPlayer(data: audioData)
            audioPlayer?.delegate = self
            audioPlayer?.prepareToPlay()
            audioPlayer?.play()
            KOnMusicManager.shared.duckForVoice(duck: true)
            
            let matchedMember = CharacterFilter.fiveIndividuals.first(where: { $0.charId == chosen.charId })
            let speakerName = matchedMember?.displayName(language) ?? targetChar.displayName(language)
            let quote = customQuote ?? localizedMascotQuote(for: chosen.charId)
            DispatchQueue.main.async {
                if let m = matchedMember {
                    self.activeAllMemberChar = m
                }
                self.isPlaying = true
                self.currentSpeechBubble = "[\(speakerName)] \(quote)"
            }
        } catch {
            print("Error playing mascot voice: \(error)")
        }
    }
    
    func characterForVoiceId(_ id: Int) -> CharacterFilter {
        switch id {
        case 157...300, 877...923, 1112, 1117: return .yui
        case 301...444, 924...970, 1113, 1118: return .mio
        case 445...588, 971...1017, 1114, 1119: return .ritsu
        case 589...732, 1018...1064, 1115, 1120: return .mugi
        case 733...876, 1065...1111, 1116, 1121: return .azusa
        default: return .all
        }
    }
    
