    // MARK: - Universal One-Click External App Navigation Jump Handler (高德/百度/腾讯/微信/美团/大众点评/小红书/浏览器)
    func handleIncomingNavigationURL(_ url: URL) {
        let rawStr = url.absoluteString
        let scheme = (url.scheme ?? "").lowercased()
        let comps = URLComponents(url: url, resolvingAgainstBaseURL: false)
        var params: [String: String] = [:]
        if let items = comps?.queryItems {
            for item in items {
                if let val = item.value, !val.isEmpty {
                    params[item.name.lowercased()] = val.removingPercentEncoding ?? val
                }
            }
        }
        
        var parsedLat: Double? = nil
        var parsedLon: Double? = nil
        var parsedName: String? = nil
        
        // 1. Check geo:lat,lon?q=name
        if scheme == "geo" {
            let body = rawStr.replacingOccurrences(of: "geo:", with: "", options: .caseInsensitive)
            let parts = body.components(separatedBy: "?")
            let coords = parts[0].components(separatedBy: ",")
            if coords.count >= 2, let la = Double(coords[0].trimmingCharacters(in: .whitespaces)), let lo = Double(coords[1].trimmingCharacters(in: .whitespaces)) {
                if la != 0 || lo != 0 {
                    parsedLat = la
                    parsedLon = lo
                }
            }
            if let q = params["q"] {
                // Could be "lat,lon(Name)" or just "Name"
                if let parenRange = q.range(of: "("), let closeRange = q.range(of: ")") {
                    parsedName = String(q[parenRange.upperBound..<closeRange.lowerBound])
                } else {
                    parsedName = q
                }
            }
        }
        
        // 2. Check Amap (iosamap:// / amapuri://): dlat, dlon, dname, lat, lon, poiname
        if parsedLat == nil {
            if let dla = params["dlat"] ?? params["lat"] ?? params["latitude"],
               let dlo = params["dlon"] ?? params["lon"] ?? params["lng"] ?? params["longitude"],
               let la = Double(dla), let lo = Double(dlo) {
                parsedLat = la
                parsedLon = lo
            }
        }
        // 2.5 Check Tencent/WeChat web marker param: marker=coord:22.54,114.05;title:XXX;addr:YYY
        if let markerParam = params["marker"] {
            for seg in markerParam.components(separatedBy: ";") {
                let s = seg.trimmingCharacters(in: .whitespacesAndNewlines)
                if s.lowercased().hasPrefix("coord:") {
                    let cParts = s.dropFirst(6).components(separatedBy: ",")
                    if cParts.count >= 2, let la = Double(cParts[0].trimmingCharacters(in: .whitespaces)), let lo = Double(cParts[1].trimmingCharacters(in: .whitespaces)) {
                        parsedLat = la
                        parsedLon = lo
                    }
                } else if s.lowercased().hasPrefix("title:") && parsedName == nil {
                    parsedName = String(s.dropFirst(6))
                } else if s.lowercased().hasPrefix("addr:") && parsedName == nil {
                    parsedName = String(s.dropFirst(5))
                }
            }
        }
        // 2.6 Check Amap web position param: position=lon,lat,name
        if parsedLat == nil, let posParam = params["position"] {
            let pParts = posParam.components(separatedBy: ",")
            if pParts.count >= 2, let lo = Double(pParts[0].trimmingCharacters(in: .whitespaces)), let la = Double(pParts[1].trimmingCharacters(in: .whitespaces)) {
                parsedLat = la
                parsedLon = lo
                if pParts.count >= 3 && parsedName == nil {
                    parsedName = pParts[2]
                }
            }
        }
        if parsedName == nil {
            parsedName = ["dname", "poiname", "name", "title", "dest", "keyword", "q", "daddr", "toname", "to", "address", "addr", "word"].compactMap { params[$0] }.first
        }
        
        // 3. Check Baidu Map (baidumap://map/direction?destination=latlng:22.54,114.05|name:xxx or destination=22.54,114.05)
        if let destParam = params["destination"] {
            if destParam.contains("|") {
                let segments = destParam.components(separatedBy: "|")
                for seg in segments {
                    if seg.lowercased().hasPrefix("latlng:") {
                        let cStr = seg.replacingOccurrences(of: "latlng:", with: "", options: .caseInsensitive)
                        let cParts = cStr.components(separatedBy: ",")
                        if cParts.count >= 2, let la = Double(cParts[0]), let lo = Double(cParts[1]) {
                            parsedLat = la
                            parsedLon = lo
                        }
                    } else if seg.lowercased().hasPrefix("name:") {
                        parsedName = seg.replacingOccurrences(of: "name:", with: "", options: .caseInsensitive)
                    }
                }
            } else {
                let cParts = destParam.components(separatedBy: ",")
                if cParts.count == 2, let la = Double(cParts[0]), let lo = Double(cParts[1]) {
                    parsedLat = la
                    parsedLon = lo
                } else {
                    parsedName = destParam
                }
            }
        }
        
        // 4. Check Tencent Map (qqmap://map/routeplan?tocoord=22.54,114.05&to=xxx)
        if let toCoord = params["tocoord"] ?? params["coord"] ?? params["center"] ?? params["ll"] ?? params["sll"] {
            let cParts = toCoord.components(separatedBy: ",")
            if cParts.count >= 2, let la = Double(cParts[0].trimmingCharacters(in: .whitespaces)), let lo = Double(cParts[1].trimmingCharacters(in: .whitespaces)) {
                parsedLat = la
                parsedLon = lo
            }
        }
        if parsedName == nil, let toName = params["to"] ?? params["address"] {
            parsedName = toName
        }
        
        // Convert BD-09 if coming from baidumap and coord_type is bd09
        let coordType = (params["coord_type"] ?? "").lowercased()
        if let la = parsedLat, let lo = parsedLon {
            var finalCoord = CLLocationCoordinate2D(latitude: la, longitude: lo)
            if scheme == "baidumap" && !coordType.contains("gcj") && !coordType.contains("wgs") {
                finalCoord = CoordinateConverter.bd09ToGCJ02(lat: la, lon: lo)
            } else if coordType.contains("wgs") || scheme == "geo" {
                // Align WGS-84 to GCJ-02 in Mainland China (no-op Overseas/HK/Macau) so Apple MapKit pin matches road!
                finalCoord = CoordinateConverter.wgs84ToGCJ02(finalCoord)
            }
            let finalTitle = (parsedName?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false) ? parsedName! : "外部App导入目的地"
            
            DispatchQueue.main.async {
                self.showMapMode = true
                self.isMapEnlarged = true
                self.isNavigatingFocused = false
                self.calculateAndStartRoute(to: finalCoord, title: finalTitle)
            }
            return
        }
        
        // 5. If only a place name/address was provided without coordinates, search and navigate automatically!
        if let queryName = parsedName?.trimmingCharacters(in: .whitespacesAndNewlines), !queryName.isEmpty {
            searchAndNavigateDirectly(query: queryName)
        }
    }
    
    func searchAndNavigateDirectly(query: String, allowRetry: Bool = true) {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        
        let req = MKLocalSearch.Request()
        req.naturalLanguageQuery = trimmed
        req.resultTypes = [.address, .pointOfInterest]
        req.region = MKCoordinateRegion(center: userCoordinate, latitudinalMeters: 2500000, longitudinalMeters: 2500000)
        
        MKLocalSearch(request: req).start { [weak self] resp, _ in
            DispatchQueue.main.async {
                guard let self = self else { return }
                if let first = resp?.mapItems.first {
                    self.showMapMode = true
                    self.isMapEnlarged = true
                    self.isNavigatingFocused = false
                    self.startRouteGuidance(to: first)
                } else if allowRetry {
                    // Retry with last clean line/segment if WeChat share included extra prefix text
                    let parts = trimmed.components(separatedBy: CharacterSet(charactersIn: "\n,，|· ")).map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { $0.count >= 2 }
                    if let fallback = parts.last, fallback != trimmed {
                        self.searchAndNavigateDirectly(query: fallback, allowRetry: false)
                        return
                    }
                    let msg = self.language == .en ? "Place not found: \(trimmed)" : "未找到地点「\(trimmed)」，请尝试在搜索框输入更短的关键词"
                    self.playVoice(id: self.activeBaseId() + 18, customQuote: msg, clearQueue: true)
                } else {
                    let msg = self.language == .en ? "Place not found: \(trimmed)" : "未找到地点「\(trimmed)」，请尝试在搜索框输入更短的关键词"
                    self.playVoice(id: self.activeBaseId() + 18, customQuote: msg, clearQueue: true)
                }
            }
        }
    }
    
    func parseSmartClipboardAndNavigate() {
        guard let raw = UIPasteboard.general.string?.trimmingCharacters(in: .whitespacesAndNewlines), !raw.isEmpty else {
            let msg = language == .en ? "Clipboard is empty!" : "剪贴板为空，请先在微信/美团/点评复制地址或链接！"
            playVoice(id: activeBaseId() + 18, customQuote: msg, clearQueue: true)
            return
        }
        // 1. Check if clipboard contains an embedded map URL scheme or web map link with coordinates/name
        let urlPattern = "(https?://[^\\s\\u4e00-\\u9fa5]+|(?:iosamap|amapuri|baidumap|qqmap|geo):[^\\s]+)"
        if let regex = try? NSRegularExpression(pattern: urlPattern, options: .caseInsensitive),
           let match = regex.firstMatch(in: raw, range: NSRange(raw.startIndex..., in: raw)),
           let r = Range(match.range, in: raw) {
            let urlStr = String(raw[r])
            if let url = URL(string: urlStr) {
                let lower = urlStr.lowercased()
                if lower.contains("coord") || lower.contains("dlat=") || lower.contains("lat=") || lower.contains("marker=") || lower.contains("position=") || lower.contains("destination=") || lower.hasPrefix("geo:") {
                    handleIncomingNavigationURL(url)
                    return
                }
            }
        }
        // 2. Otherwise strip WeChat / Meituan / Dianping / Amap share noise and search cleanly
        var cleaned = raw
        if let range = cleaned.range(of: "http", options: .caseInsensitive) {
            cleaned = String(cleaned[..<range.lowerBound])
        }
        let noiseTokens = ["【", "】", "「", "」", "位置：", "位置:", "地址：", "地址:", "分享位置：", "分享位置:", "导航到：", "导航到:", "我在", "我在\"", "点击查看地图", "高德地图", "腾讯地图", "百度地图"]
        for tok in noiseTokens {
            cleaned = cleaned.replacingOccurrences(of: tok, with: " ")
        }
        cleaned = cleaned.replacingOccurrences(of: "\"", with: " ")
        let lines = cleaned.components(separatedBy: .newlines).map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }.filter { !$0.isEmpty }
        let finalQuery = (lines.first ?? cleaned).trimmingCharacters(in: .whitespacesAndNewlines)
        if !finalQuery.isEmpty {
            searchAndNavigateDirectly(query: finalQuery)
        }
    }

    func openGaodeMap() {
        triggerDepartureGreeting()
        if let url = URL(string: "iosamap://"), UIApplication.shared.canOpenURL(url) {
            UIApplication.shared.open(url, options: [:], completionHandler: nil)
        } else if let webUrl = URL(string: "https://ditu.amap.com/") {
            UIApplication.shared.open(webUrl, options: [:], completionHandler: nil)
        }
    }
    
    func toggleCruiseMode() {
        if isCruiseModeActive { stopCruiseMode() } else { startCruiseMode() }
    }
    
    func startCruiseMode() {
        configureAudioSession()
        keepAlivePlayer?.play()
        isCruiseModeActive = true
        resetCruiseCountdown()
        playRandomCruiseVoice()
    }
    
    func stopCruiseMode() {
        isCruiseModeActive = false
        if activeRoute == nil {
            keepAlivePlayer?.stop()
        }
    }
    
    func resetCruiseCountdown() {
        cruiseRemainingSeconds = max(10, Int(cruiseIntervalMinutes * 60.0))
    }
    
    func playRandomCruiseVoice() {
        let roll = Int.random(in: 1...4)
        if enableBanter && roll == 1 {
            triggerBanter()
        } else if roll == 2 {
            playMascotVoice()
        } else {
            let pool = selectedCharacter.verifiedVoiceIds
            if let randomId = pool.randomElement() {
                playVoice(id: randomId)
            }
        }
    }
    
    var formattedCruiseCountdown: String {
        let mins = cruiseRemainingSeconds / 60
        let secs = cruiseRemainingSeconds % 60
        return String(format: "%02d:%02d", mins, secs)
    }
    
    var compassDirectionString: String {
        let dirsZh = ["北 N", "东北 NE", "东 E", "东南 SE", "南 S", "西南 SW", "西 W", "西北 NW"]
        let dirsEn = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"]
        let index = Int((headingDegrees + 22.5) / 45.0) & 7
        return language == .en ? dirsEn[index] : dirsZh[index]
    }
    
    var formattedDrivingTime: String {
        let hrs = drivingSeconds / 3600
        let mins = (drivingSeconds % 3600) / 60
        let secs = drivingSeconds % 60
        return String(format: "%02d:%02d:%02d", hrs, mins, secs)
    }
}

extension Double {
    func FloorMod(_ mod: Int) -> Int {
        let m = Double(mod)
        var r = self.truncatingRemainder(dividingBy: m)
        if r < 0 { r += m }
        return Int(r) % mod
    }
}


// ============================================================================
// MARK: - K-ON! Ho-kago Tea Time Face-to-Face P2P & Online Doudizhu Engine
// (支持面对面 MultipeerConnectivity 蓝牙/Wi-Fi 开房联机 + 轻音少女 AI 补位陪打 + 预留在线 WebSocket 服务器接口)
// ============================================================================

enum DoudizhuSuit: String, Codable, CaseIterable {
    case spade = "♠"
    case heart = "♥"
    case club = "♣"
    case diamond = "♦"
    case joker = "🃏"
    
    var isRed: Bool {
        return self == .heart || self == .diamond
    }
}

struct DoudizhuCard: Identifiable, Codable, Equatable, Hashable {
    let id: String
    let rank: Int        // 3..10, 11=J, 12=Q, 13=K, 14=A, 15=2, 16=小王, 17=大王
    let suit: DoudizhuSuit
    
    var displayRank: String {
        switch rank {
        case 3...10: return "\(rank)"
        case 11: return "J"
        case 12: return "Q"
        case 13: return "K"
        case 14: return "A"
        case 15: return "2"
        case 16: return "小王"
        case 17: return "大王"
        default: return "\(rank)"
        }
    }
    
    var isRedCard: Bool {
        if rank == 17 { return true }
        if rank == 16 { return false }
        return suit.isRed
    }
}

enum DoudizhuHandCategory: String, Codable {
    case invalid
    case single          // 单张
    case pair            // 对子
    case triple          // 三不带
    case tripleWithOne   // 三带一
    case tripleWithPair  // 三带二
    case straight        // 顺子 (>=5张)
    case consecutivePairs // 连对 (>=3对)
    case airplane        // 飞机
    case fourWithTwo     // 四带二
    case bomb            // 炸弹 (x2)
    case rocket          // 王炸 (x2)
    
    func localizedName(_ lang: AppLanguage) -> String {
        switch (self, lang) {
        case (.single, _): return "单张"
        case (.pair, _): return "对子"
        case (.triple, _): return "三张"
        case (.tripleWithOne, _): return "三带一"
        case (.tripleWithPair, _): return "三带二"
        case (.straight, .zhHant): return "順子"
        case (.straight, _): return "顺子"
        case (.consecutivePairs, .zhHant): return "連對"
        case (.consecutivePairs, _): return "连对"
        case (.airplane, .zhHant): return "飛機"
        case (.airplane, _): return "飞机"
        case (.fourWithTwo, _): return "四带二"
        case (.bomb, .zhHant): return "💥 炸彈!"
        case (.bomb, _): return "💥 炸弹!"
        case (.rocket, _): return "🚀 王炸!!"
        case (.invalid, _): return ""
        }
    }
}

struct EvaluatedDoudizhuHand: Codable, Equatable {
    let category: DoudizhuHandCategory
    let primaryRank: Int
    let length: Int
    let cards: [DoudizhuCard]
    
    func canBeat(_ previous: EvaluatedDoudizhuHand?) -> Bool {
        guard category != .invalid else { return false }
        guard let prev = previous, prev.category != .invalid else { return true }
        if category == .rocket { return true }
        if prev.category == .rocket { return false }
        if category == .bomb && prev.category != .bomb { return true }
        if category != .bomb && prev.category == .bomb { return false }
        guard category == prev.category && length == prev.length else { return false }
        return primaryRank > prev.primaryRank
    }
}

struct DoudizhuHandEvaluator {
    static func evaluate(_ cards: [DoudizhuCard]) -> EvaluatedDoudizhuHand {
        let sorted = cards.sorted { $0.rank > $1.rank }
        let n = sorted.count
        if n == 0 {
            return EvaluatedDoudizhuHand(category: .invalid, primaryRank: 0, length: 0, cards: [])
        }
        
        var counts: [Int: Int] = [:]
        for c in sorted { counts[c.rank, default: 0] += 1 }
        let groups = counts.sorted { a, b in
            if a.value != b.value { return a.value > b.value }
            return a.key > b.key
        }
        
        // 1. Single
        if n == 1 {
            return EvaluatedDoudizhuHand(category: .single, primaryRank: sorted[0].rank, length: 1, cards: sorted)
        }
        // 2. Pair or Rocket
        if n == 2 {
            if sorted[0].rank == 17 && sorted[1].rank == 16 {
                return EvaluatedDoudizhuHand(category: .rocket, primaryRank: 99, length: 2, cards: sorted)
            }
            if groups.count == 1 && groups[0].value == 2 {
                return EvaluatedDoudizhuHand(category: .pair, primaryRank: groups[0].key, length: 2, cards: sorted)
            }
            return EvaluatedDoudizhuHand(category: .invalid, primaryRank: 0, length: n, cards: sorted)
        }
        // 3. Triple
        if n == 3 {
            if groups.count == 1 && groups[0].value == 3 {
                return EvaluatedDoudizhuHand(category: .triple, primaryRank: groups[0].key, length: 3, cards: sorted)
            }
            return EvaluatedDoudizhuHand(category: .invalid, primaryRank: 0, length: n, cards: sorted)
        }
        // 4. Bomb or Triple+1
        if n == 4 {
            if groups.count == 1 && groups[0].value == 4 {
                return EvaluatedDoudizhuHand(category: .bomb, primaryRank: groups[0].key, length: 4, cards: sorted)
            }
            if groups.count == 2 && groups[0].value == 3 {
                return EvaluatedDoudizhuHand(category: .tripleWithOne, primaryRank: groups[0].key, length: 4, cards: sorted)
            }
            return EvaluatedDoudizhuHand(category: .invalid, primaryRank: 0, length: n, cards: sorted)
        }
        // 5. Triple+Pair (5 cards)
        if n == 5 && groups.count == 2 && groups[0].value == 3 && groups[1].value == 2 {
            return EvaluatedDoudizhuHand(category: .tripleWithPair, primaryRank: groups[0].key, length: 5, cards: sorted)
        }
        // 6. Four with two singles (6 cards) or two pairs (8 cards)
        if n == 6 && groups[0].value == 4 {
            return EvaluatedDoudizhuHand(category: .fourWithTwo, primaryRank: groups[0].key, length: 6, cards: sorted)
        }
        if n == 8 && groups[0].value == 4 && groups.count == 3 && groups[1].value == 2 && groups[2].value == 2 {
            return EvaluatedDoudizhuHand(category: .fourWithTwo, primaryRank: groups[0].key, length: 8, cards: sorted)
        }
        // 7. Straight (>= 5 singles, all ranks <= 14 i.e. 3..A)
        if n >= 5 && groups.count == n {
            let maxR = sorted.first!.rank
            let minR = sorted.last!.rank
            if maxR <= 14 && (maxR - minR == n - 1) {
                return EvaluatedDoudizhuHand(category: .straight, primaryRank: maxR, length: n, cards: sorted)
            }
        }
        // 8. Consecutive Pairs (>= 3 pairs, all ranks <= 14)
        if n >= 6 && n % 2 == 0 && groups.count == n / 2 && groups.allSatisfy({ $0.value == 2 && $0.key <= 14 }) {
            let pairRanks = groups.map { $0.key }.sorted()
            if pairRanks.last! - pairRanks.first! == (n / 2 - 1) {
                return EvaluatedDoudizhuHand(category: .consecutivePairs, primaryRank: pairRanks.last!, length: n, cards: sorted)
            }
        }
        // 9. Airplane (2+ consecutive triples, with or without wings)
        let tripleRanks = groups.filter { $0.value >= 3 && $0.key <= 14 }.map { $0.key }.sorted()
        if tripleRanks.count >= 2 {
            var maxConsec = 1
            var bestHigh = tripleRanks.last!
            var curConsec = 1
            for i in 1..<tripleRanks.count {
                if tripleRanks[i] == tripleRanks[i - 1] + 1 {
                    curConsec += 1
                    if curConsec >= maxConsec {
                        maxConsec = curConsec
                        bestHigh = tripleRanks[i]
                    }
                } else {
                    curConsec = 1
                }
            }
            if maxConsec >= 2 {
                if n == maxConsec * 3 || n == maxConsec * 4 || (n == maxConsec * 5 && groups.filter({ $0.value == 2 }).count >= maxConsec) {
                    return EvaluatedDoudizhuHand(category: .airplane, primaryRank: bestHigh, length: n, cards: sorted)
                }
            }
        }
        
        return EvaluatedDoudizhuHand(category: .invalid, primaryRank: 0, length: n, cards: sorted)
    }
    
    /// Finds candidate playable card subsets from `hand` that can beat `target`
    static func findHints(in hand: [DoudizhuCard], beating target: EvaluatedDoudizhuHand?) -> [[DoudizhuCard]] {
        let asc = hand.sorted { $0.rank < $1.rank }
        guard !asc.isEmpty else { return [] }
        
        var byRank: [Int: [DoudizhuCard]] = [:]
        for c in asc { byRank[c.rank, default: []].append(c) }
        let uniqueRanks = byRank.keys.sorted()
        
        var hints: [[DoudizhuCard]] = []
        
        // If free lead (no target to beat): suggest smallest single, pair, triple, or straight
        guard let tgt = target, tgt.category != .invalid else {
            for r in uniqueRanks {
                if let arr = byRank[r] {
                    if arr.count == 1 { hints.append(arr) }
                    else if arr.count == 2 { hints.append(arr) }
                    else if arr.count == 3 {
                        if let singleR = uniqueRanks.first(where: { $0 != r && (byRank[$0]?.count ?? 0) >= 1 }) {
                            hints.append(arr + [byRank[singleR]![0]])
                        } else {
                            hints.append(arr)
                        }
                    }
                }
            }
            if hints.isEmpty { hints.append([asc[0]]) }
            return hints
        }
        
        if tgt.category == .rocket { return [] }
        
        switch tgt.category {
        case .single:
            for r in uniqueRanks where r > tgt.primaryRank {
                if let arr = byRank[r], !arr.isEmpty {
                    hints.append([arr[0]])
                }
            }
        case .pair:
            for r in uniqueRanks where r > tgt.primaryRank {
                if let arr = byRank[r], arr.count >= 2 {
                    hints.append(Array(arr.prefix(2)))
                }
            }
        case .triple:
            for r in uniqueRanks where r > tgt.primaryRank {
                if let arr = byRank[r], arr.count >= 3 {
                    hints.append(Array(arr.prefix(3)))
                }
            }
        case .tripleWithOne:
            for r in uniqueRanks where r > tgt.primaryRank {
                if let arr = byRank[r], arr.count >= 3 {
                    if let kickerR = uniqueRanks.first(where: { $0 != r }) {
                        hints.append(Array(arr.prefix(3)) + [byRank[kickerR]![0]])
                    }
                }
            }
        case .tripleWithPair:
            for r in uniqueRanks where r > tgt.primaryRank {
                if let arr = byRank[r], arr.count >= 3 {
                    if let kickerR = uniqueRanks.first(where: { $0 != r && (byRank[$0]?.count ?? 0) >= 2 }) {
                        hints.append(Array(arr.prefix(3)) + Array(byRank[kickerR]!.prefix(2)))
                    }
                }
            }
        case .straight:
            let len = tgt.length
            let validSingleRanks = uniqueRanks.filter { $0 <= 14 }
            if validSingleRanks.count >= len {
                for startIdx in 0...(validSingleRanks.count - len) {
                    let slice = Array(validSingleRanks[startIdx..<(startIdx + len)])
                    if slice.last! - slice.first! == len - 1 && slice.last! > tgt.primaryRank {
                        hints.append(slice.map { byRank[$0]![0] })
                    }
                }
            }
        case .consecutivePairs:
            let pairCount = tgt.length / 2
            let validPairRanks = uniqueRanks.filter { $0 <= 14 && (byRank[$0]?.count ?? 0) >= 2 }
            if validPairRanks.count >= pairCount {
                for startIdx in 0...(validPairRanks.count - pairCount) {
                    let slice = Array(validPairRanks[startIdx..<(startIdx + pairCount)])
                    if slice.last! - slice.first! == pairCount - 1 && slice.last! > tgt.primaryRank {
                        var combo: [DoudizhuCard] = []
                        for r in slice { combo.append(contentsOf: byRank[r]!.prefix(2)) }
                        hints.append(combo)
                    }
                }
            }
        default:
            break
        }
        
        // Add Bombs that can beat tgt
        for r in uniqueRanks {
            if let arr = byRank[r], arr.count == 4 {
                if tgt.category != .bomb || r > tgt.primaryRank {
                    hints.append(arr)
                }
            }
        }
        // Add Rocket if available
        if let j1 = byRank[16]?.first, let j2 = byRank[17]?.first {
            hints.append([j2, j1])
        }
        
        return hints
    }
}

struct DoudizhuPlayerSeat: Identifiable, Codable, Equatable {
