// MARK: - QQ Group Coin Binder (放课后棋牌室 QQ 群金币绑定，仅在线服务器联机 ≥2 真人结算)
final class KOnQQCoinBinder: ObservableObject {
    static let shared = KOnQQCoinBinder()
    @Published var qqUid: String = UserDefaults.standard.string(forKey: "htt_qq_uid") ?? ""
    @Published var qqToken: String = UserDefaults.standard.string(forKey: "htt_qq_token") ?? ""
    @Published var coins: Int = UserDefaults.standard.integer(forKey: "htt_qq_coins")
    @Published var coinAnte: Int = max(5, UserDefaults.standard.integer(forKey: "htt_qq_ante") == 0 ? 10 : UserDefaults.standard.integer(forKey: "htt_qq_ante"))
    @Published var statusText: String = ""
    @Published var isBusy: Bool = false

    var isBound: Bool { !qqToken.isEmpty && !qqUid.isEmpty }
    var onlineTokenOrNil: String? { qqToken.isEmpty ? nil : qqToken }

    func save() {
        UserDefaults.standard.set(qqUid, forKey: "htt_qq_uid")
        UserDefaults.standard.set(qqToken, forKey: "htt_qq_token")
        UserDefaults.standard.set(coins, forKey: "htt_qq_coins")
        UserDefaults.standard.set(coinAnte, forKey: "htt_qq_ante")
    }

    func unbind() {
        qqUid = ""; qqToken = ""; coins = 0; statusText = "已解除 QQ 群金币绑定"
        save()
    }

    func requestCode(qq: String) {
        let clean = qq.trimmingCharacters(in: .whitespacesAndNewlines)
        guard clean.count >= 5, let url = URL(string: "https://azusa.online/club/bind_code") else {
            statusText = "请输入正确的 QQ 号"
            return
        }
        isBusy = true
        statusText = "正在通过群机器人私聊发送验证码..."
        var req = URLRequest(url: url)
        req.httpMethod = "POST"
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        req.httpBody = try? JSONSerialization.data(withJSONObject: ["qq": clean])
        URLSession.shared.dataTask(with: req) { data, _, err in
            DispatchQueue.main.async {
                self.isBusy = false
                guard let data = data,
                      let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
                    self.statusText = "网络请求失败：\(err?.localizedDescription ?? "请稍后重试")"
                    return
                }
                if (obj["ok"] as? Bool) == true {
                    self.statusText = "✅ 验证码已通过群机器人私聊发送，请查收并填写"
                } else {
                    self.statusText = "⚠️ \(obj["error"] as? String ?? "发送失败，请先在群内发言或开启临时会话")"
                }
            }
        }.resume()
    }

    func verifyCode(qq: String, code: String, completion: @escaping (Bool) -> Void) {
        let cleanQq = qq.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanCode = code.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let url = URL(string: "https://azusa.online/club/bind_verify") else { completion(false); return }
        isBusy = true
        var req = URLRequest(url: url)
        req.httpMethod = "POST"
        req.setValue("application/json", forHTTPHeaderField: "Content-Type")
        req.httpBody = try? JSONSerialization.data(withJSONObject: ["qq": cleanQq, "code": cleanCode])
        URLSession.shared.dataTask(with: req) { data, _, _ in
            DispatchQueue.main.async {
                self.isBusy = false
                guard let data = data,
                      let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                      (obj["ok"] as? Bool) == true,
                      let tok = obj["token"] as? String else {
                    let msg = (data.flatMap { try? JSONSerialization.jsonObject(with: $0) as? [String: Any] })?["error"] as? String
                    self.statusText = "⚠️ \(msg ?? "验证码错误或已过期")"
                    completion(false)
                    return
                }
                self.qqUid = cleanQq
                self.qqToken = tok
                self.coins = obj["coins"] as? Int ?? 0
                self.statusText = "🎉 绑定成功！当前 QQ 群金币：\(self.coins)"
                self.save()
                completion(true)
            }
        }.resume()
    }

    func refreshCoins(manual: Bool = false) {
        guard !qqToken.isEmpty,
              let enc = qqToken.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed),
              let url = URL(string: "https://azusa.online/club/coins?token=\(enc)&_t=\(Int(Date().timeIntervalSince1970 * 1000))") else { return }
        if manual {
            DispatchQueue.main.async {
                self.isBusy = true
                self.statusText = "🔄 正在同步最新 QQ 群金币..."
            }
        }
        var req = URLRequest(url: url, cachePolicy: .reloadIgnoringLocalAndRemoteCacheData, timeoutInterval: 8.0)
        req.setValue("no-cache", forHTTPHeaderField: "Cache-Control")
        URLSession.shared.dataTask(with: req) { data, _, err in
            DispatchQueue.main.async {
                if manual { self.isBusy = false }
                guard let data = data,
                      let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                      (obj["ok"] as? Bool) == true,
                      let c = obj["coins"] as? Int else {
                    if manual {
                        self.statusText = "⚠️ 刷新失败：\(err?.localizedDescription ?? "请检查网络或重新绑定")"
                    }
                    return
                }
                self.coins = c
                self.save()
                if manual {
                    self.statusText = "✅ 已同步最新 QQ 群金币：\(c) 🪙"
                }
            }
        }.resume()
    }
}

struct DoudizhuNetPacket: Codable {
    enum PacketKind: String, Codable {
        case joinRequest
        case leaveRoom
        case roomFull
        case roomRoster
        case stateSync
        case bidAction
        case playCardsAction
        case passAction
        case chatVoiceAction
    }
    var kind: PacketKind
    var roomCode: String
    var senderPeerName: String
    var senderCharId: Int
    var hostPeerName: String?
    var roomPeers: [DoudizhuRoomPeer]?
    var bidScore: Int?
    var playedCards: [DoudizhuCard]?
    var seats: [DoudizhuPlayerSeat]?
    var holeCards: [DoudizhuCard]?
    var phase: DoudizhuGamePhase?
    var currentTurnSeat: Int?
    var highestBid: Int?
    var highestBidderSeat: Int?
    var multiplier: Int?
    var lastValidHand: EvaluatedDoudizhuHand?
    var lastPlaySeat: Int?
    var winnerSeat: Int?
    var statusBanner: String?
    var totalRounds: Int?
    var currentRound: Int?
    var baseScore: Int?
    var maxMultiplier: Int?
    var turnTimeLimit: Int?
    var allowCardCounter: Bool?
    var aiDifficulty: String?
    var qqToken: String? = nil
    var coinAnte: Int? = nil
}

// Abstract Transport Protocol: Supports Face-to-Face P2P Now & Online WebSocket Server Later!
protocol DoudizhuTransportProtocol: AnyObject {
    var modeName: String { get }
    func startHosting(roomCode: String, hostName: String, hostCharId: Int)
    func startBrowsing()
    func stopAll()
    func sendPacket(_ packet: DoudizhuNetPacket)
}

func makeSafeMCPeerID(_ raw: String) -> MCPeerID {
    var s = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    if s.isEmpty { s = "HTT-Player" }
    while s.utf8.count > 55 && s.count > 1 { s.removeLast() }
    return MCPeerID(displayName: s.isEmpty ? "HTT-Player" : s)
}

