    func cardImage(for card: DoudizhuCard) -> UIImage? {
        if let img = cardImage(for: card.id) {
            return img
        }
        let fallbackKey: String
        if card.suit == .joker {
            fallbackKey = "joker_\(card.rank)"
        } else {
            fallbackKey = "\(card.suit.rawValue)_\(card.rank)"
        }
        return cardImage(for: fallbackKey)
    }

    func cardImage(for cardId: String) -> UIImage? {
        if let cached = pokerCardImageCache[cardId] {
            return cached
        }
        guard let b64 = KOnDoudizhuManager.pokerCardImagesBase64[cardId],
              let data = Data(base64Encoded: b64),
              let img = UIImage(data: data) else {
            return nil
        }
        pokerCardImageCache[cardId] = img
        return img
    }
    
    func cardBackImage() -> UIImage? {
        return cardImage(for: "back")
    }

    
    // Transport Mode: Face-to-Face P2P vs Online Server (Reserved for user's future server!)
    enum NetworkMode: String, CaseIterable, Identifiable {
        case faceToFaceP2P = "p2p"
        case onlineServer = "online"
        var id: String { rawValue }
    }
    
    @Published var networkMode: NetworkMode = .faceToFaceP2P {
        didSet {
            if oldValue != networkMode {
                leaveCurrentRoomAndReset()
            }
        }
    }
    @Published var customServerURL: String = (UserDefaults.standard.string(forKey: "kon_ddz_server_url") ?? "").replacingOccurrences(of: "psp.azusa.online", with: "azusa.online").isEmpty ? "wss://azusa.online/ddz" : (UserDefaults.standard.string(forKey: "kon_ddz_server_url") ?? "wss://azusa.online/ddz").replacingOccurrences(of: "psp.azusa.online", with: "azusa.online") {
        didSet {
            UserDefaults.standard.set(customServerURL, forKey: "kon_ddz_server_url")
        }
    }
    
    // Room & Lobby State
    @Published var roomCode: String = "" {
        didSet {
            let trimmed = roomCode.trimmingCharacters(in: .whitespacesAndNewlines)
            if trimmed != activeConnectedRoomCode && (isHostingRoom || isOnlineConnected || isBrowsingRooms || !connectedPeerNames.isEmpty) {
                leaveCurrentRoomAndReset()
            }
        }
    }
    private var activeConnectedRoomCode: String = ""
    private let deviceShortTag: String = {
        if let saved = UserDefaults.standard.string(forKey: "kon_ddz_device_tag"), !saved.isEmpty {
            return saved
        }
        let generated = String(Int.random(in: 100...999))
        UserDefaults.standard.set(generated, forKey: "kon_ddz_device_tag")
        return generated
    }()
    @Published var myNickname: String = UserDefaults.standard.string(forKey: "kon_ddz_nickname") ?? "轻音车友" {
        didSet {
            UserDefaults.standard.set(myNickname, forKey: "kon_ddz_nickname")
            refreshMyPeerIdentityOnProfileChange()
        }
    }
    @Published var myCharacter: AudioPlayerManager.CharacterFilter = .yui {
        didSet {
            refreshMyPeerIdentityOnProfileChange()
        }
    }
    @Published var isHostingRoom: Bool = false
    @Published var isBrowsingRooms: Bool = false
    @Published var connectedPeerNames: [String] = []
    @Published var discoveredRooms: [DoudizhuDiscoveredRoom] = []
    @Published var mySeatIndex: Int = 0
    @Published var isRoomAuthority: Bool = true
    @Published var isOnlineConnected: Bool = false
    @Published var totalRounds: Int = 3
    @Published var currentRound: Int = 1
    @Published var baseScore: Int = 100
    @Published var maxMultiplier: Int = 32
    @Published var turnTimeLimit: Int = 25
    @Published var turnRemainingSeconds: Int = 25
    @Published var allowCardCounter: Bool = true
    @Published var aiDifficulty: String = "标准 AI"
    @Published var statusBanner: String = "欢迎来到放课后茶会斗地主！可面对面建房联机或与轻音少女AI对局"
    
    // Game Table State
    @Published var phase: DoudizhuGamePhase = .lobby
    @Published var seats: [DoudizhuPlayerSeat] = [
        DoudizhuPlayerSeat(id: 0, name: "平泽唯 (我)", characterId: 1, isAI: false, peerDisplayName: "Me", hand: [], isLandlord: false, lastActionText: "", lastPlayedCards: [], score: 1000),
        DoudizhuPlayerSeat(id: 1, name: "秋山澪 (HTT)", characterId: 2, isAI: true, peerDisplayName: "AI_Mio", hand: [], isLandlord: false, lastActionText: "", lastPlayedCards: [], score: 1000),
        DoudizhuPlayerSeat(id: 2, name: "田井中律 (HTT)", characterId: 3, isAI: true, peerDisplayName: "AI_Ritsu", hand: [], isLandlord: false, lastActionText: "", lastPlayedCards: [], score: 1000)
    ]
    @Published var holeCards: [DoudizhuCard] = []
    @Published var selectedCardIds: Set<String> = []
    @Published var currentTurnSeat: Int = 0
    @Published var highestBid: Int = 0
    @Published var highestBidderSeat: Int = -1
    @Published var bidsCount: Int = 0
    @Published var multiplier: Int = 1
    @Published var lastValidHand: EvaluatedDoudizhuHand? = nil
    @Published var lastPlaySeat: Int = -1
    @Published var winnerSeat: Int? = nil
    @Published var showCardCounter: Bool = true
    @Published var hintIndex: Int = 0
    
    // MultipeerConnectivity P2P Components (Bluetooth + Peer-to-Peer Wi-Fi)
    private let serviceType = "kon-ddz"
    private var myPeerID: MCPeerID!
    private var mcSession: MCSession?
    private var advertiser: MCNearbyServiceAdvertiser?
    private var browser: MCNearbyServiceBrowser?
    private var webSocketTask: URLSessionWebSocketTask?
    private var aiTurnWorkItem: DispatchWorkItem?
    private var turnCountdownTimer: Timer?
    private var wsPingTimer: Timer?
    private var peerCharIds: [String: Int] = [:]
    private var orderedRoomPeers: [DoudizhuRoomPeer] = []
    
    override init() {
        super.init()
        let devName = UIDevice.current.name
        if myNickname == "轻音车友" && !devName.isEmpty && devName != "iPhone" {
            self.myNickname = devName
        }
        self.myPeerID = makeSafeMCPeerID(makeUniquePeerKey())
    }
    
    private func cleanNickname() -> String {
        let trimmed = myNickname.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? "轻音车友" : trimmed
    }
    
    private func makeUniquePeerKey() -> String {
        return "\(cleanNickname())#\(deviceShortTag)"
    }
    
    private func cleanPeerLabel(_ rawName: String) -> String {
        if let hashIdx = rawName.lastIndex(of: "#") {
            let prefix = String(rawName[..<hashIdx]).trimmingCharacters(in: .whitespacesAndNewlines)
            if !prefix.isEmpty { return prefix }
        }
        return rawName
    }
    
    private func refreshMyPeerIdentityOnProfileChange() {
        guard myPeerID != nil else { return }
        let oldKey = myPeerID.displayName
        let newKey = makeUniquePeerKey()
        if oldKey != newKey && !isHostingRoom && !isOnlineConnected && connectedPeerNames.isEmpty {
            myPeerID = makeSafeMCPeerID(newKey)
        }
        if let idx = orderedRoomPeers.firstIndex(where: { $0.name == oldKey || $0.name == myPeerID.displayName }) {
            orderedRoomPeers[idx] = DoudizhuRoomPeer(name: myPeerID.displayName, charId: myCharacter.charId, displayName: cleanNickname())
        }
        if phase == .lobby {
            rebuildLobbySeats()
            if isOnlineConnected {
                sendJoinRequestToRoom()
            } else if isHostingRoom && isRoomAuthority {
                broadcastFullState()
            }
        }
    }
    
    func syncRulesIfHost() {
        if isRoomAuthority && (isHostingRoom || isOnlineConnected) {
            broadcastFullState()
        }
    }
    
    func characterFilter(for charId: Int) -> AudioPlayerManager.CharacterFilter {
        switch charId {
        case 1: return .yui
        case 2: return .mio
        case 3: return .ritsu
        case 4: return .mugi
        case 5: return .azusa
        default: return .yui
        }
    }
    
    // MARK: - Face-to-Face P2P Room Creation & Discovery
    func startHostingFaceToFaceRoom() {
        let code = roomCode.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !code.isEmpty else {
            statusBanner = "⚠️ 请先填写房号，未填写无法创建房间！"
            return
        }
        stopNetworking()
        activeConnectedRoomCode = code
        roomCode = code
        isHostingRoom = true
        isRoomAuthority = true
        isBrowsingRooms = false
        mySeatIndex = 0
        currentRound = 1
        
        myPeerID = makeSafeMCPeerID(makeUniquePeerKey())
        orderedRoomPeers = [DoudizhuRoomPeer(name: myPeerID.displayName, charId: myCharacter.charId, displayName: cleanNickname())]
        let session = MCSession(peer: myPeerID, securityIdentity: nil, encryptionPreference: .optional)
        session.delegate = self
        self.mcSession = session
        
        let info: [String: String] = [
            "code": roomCode,
            "host": cleanNickname(),
            "char": "\(myCharacter.charId)"
        ]
        let adv = MCNearbyServiceAdvertiser(peer: myPeerID, discoveryInfo: info, serviceType: serviceType)
        adv.delegate = self
        adv.startAdvertisingPeer()
        self.advertiser = adv
        
        rebuildLobbySeats()
        statusBanner = "📡 房间 [\(roomCode)] 已创建！附近好友点击「加入房间」即可面对面秒连（不足3人自动由轻音AI补位）"
        AudioPlayerManager.shared.playMascotVoice(for: myCharacter)
    }
    
    func startScanningFaceToFaceRooms() {
        let code = roomCode.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !code.isEmpty else {
            statusBanner = "⚠️ 请先填写房号，未填写无法扫描加入房间！"
            return
        }
        stopNetworking()
        activeConnectedRoomCode = code
        roomCode = code
        isHostingRoom = false
        isBrowsingRooms = true
        discoveredRooms.removeAll()
        
        myPeerID = makeSafeMCPeerID(makeUniquePeerKey())
        let session = MCSession(peer: myPeerID, securityIdentity: nil, encryptionPreference: .optional)
        session.delegate = self
        self.mcSession = session
        
        let brw = MCNearbyServiceBrowser(peer: myPeerID, serviceType: serviceType)
        brw.delegate = self
        brw.startBrowsingForPeers()
        self.browser = brw
        
        statusBanner = "🔍 正在通过蓝牙与点对点 Wi-Fi 扫描附近的面对面房间..."
    }
    
    func joinDiscoveredRoom(_ room: DoudizhuDiscoveredRoom) {
        isRoomAuthority = false
        let code = roomCode.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !code.isEmpty else {
            statusBanner = "⚠️ 请先填写房号再加入房间！"
            return
        }
        guard room.roomCode == code else {
            statusBanner = "⚠️ 房号不匹配（您填写的是 \(code)，该房间房号为 \(room.roomCode)）！"
            return
        }
        guard let brw = browser, let session = mcSession else { return }
        statusBanner = "🔗 正在加入 [\(room.hostName)] 的房间 (\(room.roomCode))..."
        let contextData = try? JSONEncoder().encode([
            "name": myPeerID.displayName,
            "char": "\(myCharacter.charId)",
            "code": room.roomCode
        ])
        brw.invitePeer(room.peerID, to: session, withContext: contextData, timeout: 15)
    }
    
    func connectOnlineServerRoom() {
        let hostTrim = customServerURL.trimmingCharacters(in: .whitespacesAndNewlines)
        let isLanBridge = hostTrim.contains("://192.168.") || hostTrim.contains("://10.") || hostTrim.contains("://172.")
        if !isLanBridge && !KOnQQCoinBinder.shared.isBound {
            statusBanner = "🔒 远程服务器联机需先绑定登录 QQ 账号，未登录仅可使用面对面或 AI 游玩！"
            return
        }
        let code = roomCode.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !code.isEmpty else {
            statusBanner = "⚠️ 请先填写房间号，不填写无法进入在线房间！"
            return
        }
        let trimmed = customServerURL.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let url = URL(string: trimmed), trimmed.hasPrefix("ws://") || trimmed.hasPrefix("wss://") else {
            statusBanner = "⚠️ 服务器地址格式无效，请检查 ws:// 或 wss:// 地址"
            return
        }
        stopNetworking()
        activeConnectedRoomCode = code
        roomCode = code
        currentRound = 1
        myPeerID = makeSafeMCPeerID(makeUniquePeerKey())
        orderedRoomPeers = [DoudizhuRoomPeer(name: myPeerID.displayName, charId: myCharacter.charId, displayName: cleanNickname())]
        isRoomAuthority = false
        isOnlineConnected = true
        let task = URLSession.shared.webSocketTask(with: url)
        self.webSocketTask = task
        task.resume()
        receiveNextWebSocketMessage()
        startWebSocketPingTimer()
        statusBanner = "🌐 正在连接在线服务器 (\(trimmed))，房间号：\(roomCode)..."
        
        // Send joinRequest so all peers in the same roomCode see us immediately
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.25) { [weak self] in
            self?.sendJoinRequestToRoom()
        }
    }
    
    private func startWebSocketPingTimer() {
        wsPingTimer?.invalidate()
        let t = Timer(timeInterval: 15.0, repeats: true) { [weak self] _ in
            guard let self = self, self.isOnlineConnected, let ws = self.webSocketTask else { return }
            ws.sendPing { _ in }
        }
        RunLoop.main.add(t, forMode: .common)
        wsPingTimer = t
    }
    
    func sendJoinRequestToRoom() {
        let pkt = DoudizhuNetPacket(
            kind: .joinRequest,
            roomCode: roomCode,
            senderPeerName: myPeerID.displayName,
            senderCharId: myCharacter.charId,
            qqToken: isOnlineConnected ? KOnQQCoinBinder.shared.onlineTokenOrNil : nil
        )
        sendPacketToPeers(pkt)
        statusBanner = "✅ 已连接在线服务器，房间号：\(roomCode)（等待同房好友或直接开始）"
    }
    
    private func receiveNextWebSocketMessage() {
        webSocketTask?.receive { [weak self] result in
            guard let self = self else { return }
            switch result {
            case .success(let msg):
                if case .data(let data) = msg, let pkt = try? JSONDecoder().decode(DoudizhuNetPacket.self, from: data) {
                    DispatchQueue.main.async {
                        self.handleIncomingPacket(pkt)
                    }
                } else if case .string(let str) = msg, let data = str.data(using: .utf8),
                          let pkt = try? JSONDecoder().decode(DoudizhuNetPacket.self, from: data) {
                    DispatchQueue.main.async {
                        self.handleIncomingPacket(pkt)
                    }
                }
                self.receiveNextWebSocketMessage()
            case .failure:
                DispatchQueue.main.async {
                    if self.isOnlineConnected {
                        self.isOnlineConnected = false
                    }
                }
            }
        }
    }
    
    func returnRoomToLobby() {
        let inMultiplayerRoom = isHostingRoom || isOnlineConnected || !connectedPeerNames.isEmpty || orderedRoomPeers.count > 1
        if inMultiplayerRoom && isRoomAuthority {
            aiTurnWorkItem?.cancel()
            turnCountdownTimer?.invalidate()
            turnCountdownTimer = nil
            phase = .lobby
            rebuildLobbySeats()
            statusBanner = "⚙️ 房主已带领大家返回房间设置，可调整规则后开启下一局"
            broadcastFullState()
        } else {
            leaveCurrentRoomAndReset()
        }
    }
    
    func leaveCurrentRoomAndReset() {
        stopNetworking()
        phase = .lobby
        currentRound = 1
        mySeatIndex = 0
        holeCards = []
        lastValidHand = nil
        lastPlaySeat = -1
        winnerSeat = nil
        selectedCardIds.removeAll()
        rebuildLobbySeats()
        statusBanner = "✨ 已退出当前房间，座位已重置为单人+AI补位"
    }

    func stopNetworking() {
        aiTurnWorkItem?.cancel()
        turnCountdownTimer?.invalidate()
        turnCountdownTimer = nil
        wsPingTimer?.invalidate()
        wsPingTimer = nil
        if !activeConnectedRoomCode.isEmpty && (isHostingRoom || isOnlineConnected || !connectedPeerNames.isEmpty) {
            let leavePkt = DoudizhuNetPacket(
                kind: .leaveRoom,
                roomCode: activeConnectedRoomCode,
                senderPeerName: myPeerID.displayName,
                senderCharId: myCharacter.charId
            )
            if let data = try? JSONEncoder().encode(leavePkt) {
                if let session = mcSession, !session.connectedPeers.isEmpty {
                    try? session.send(data, toPeers: session.connectedPeers, with: .reliable)
                }
                if let ws = webSocketTask {
                    ws.send(.data(data)) { _ in }
                }
            }
        }
        activeConnectedRoomCode = ""
        peerCharIds.removeAll()
        orderedRoomPeers.removeAll()
        advertiser?.stopAdvertisingPeer()
        browser?.stopBrowsingForPeers()
        mcSession?.disconnect()
        webSocketTask?.cancel(with: .goingAway, reason: nil)
        advertiser = nil
        browser = nil
        mcSession = nil
        webSocketTask = nil
        isHostingRoom = false
        isBrowsingRooms = false
        isOnlineConnected = false
        isRoomAuthority = true
        mySeatIndex = 0
        connectedPeerNames.removeAll()
        discoveredRooms.removeAll()
        rebuildLobbySeats()
    }
    
    func rebuildLobbySeats() {
        let lang = AudioPlayerManager.shared.language
        let aiCandidates: [AudioPlayerManager.CharacterFilter] = [.mio, .ritsu, .mugi, .azusa, .yui].filter { $0 != myCharacter }
        var newSeats: [DoudizhuPlayerSeat] = []
        
        var prevScoresByPeer: [String: Int] = [:]
        for s in seats {
            prevScoresByPeer[s.peerDisplayName] = s.score
        }
        
        var roster = orderedRoomPeers
        if roster.isEmpty {
            roster.append(DoudizhuRoomPeer(name: myPeerID.displayName, charId: myCharacter.charId, displayName: cleanNickname()))
            for pName in connectedPeerNames where !roster.contains(where: { $0.name == pName }) && roster.count < 3 {
                roster.append(DoudizhuRoomPeer(name: pName, charId: peerCharIds[pName] ?? 2, displayName: cleanPeerLabel(pName)))
            }
        }
        
        for slot in 0..<3 {
            if slot < roster.count {
                let rp = roster[slot]
                let isMe = (rp.name == myPeerID.displayName)
                let ch = isMe ? myCharacter : characterFilter(for: rp.charId)
                let roleTag = (slot == 0) ? "🏠房主" : "🎮\(slot + 1)号"
                let disp = cleanPeerLabel(rp.displayName ?? rp.name)
                if isMe {
                    mySeatIndex = slot
                }
                let savedScore = prevScoresByPeer[rp.name] ?? (seats.count > slot ? seats[slot].score : 1000)
                newSeats.append(DoudizhuPlayerSeat(
                    id: slot,
                    name: "\(roleTag) \(disp) (\(ch.displayName(lang)))",
                    characterId: ch.charId,
                    isAI: false,
                    peerDisplayName: rp.name,
                    hand: [],
                    isLandlord: false,
                    lastActionText: slot == 0 ? "房主" : "已准备",
                    lastPlayedCards: [],
                    score: savedScore
                ))
            } else {
                let aiChar = aiCandidates[slot % aiCandidates.count]
                let aiPeerKey = "AI_\(slot)"
                let savedScore = prevScoresByPeer[aiPeerKey] ?? (seats.count > slot ? seats[slot].score : 1000)
                newSeats.append(DoudizhuPlayerSeat(
                    id: slot,
                    name: "\(aiChar.displayName(lang)) (AI)",
                    characterId: aiChar.charId,
                    isAI: true,
                    peerDisplayName: aiPeerKey,
                    hand: [],
                    isLandlord: false,
                    lastActionText: "AI陪打",
                    lastPlayedCards: [],
                    score: savedScore
                ))
            }
        }
        self.seats = newSeats
    }
    
    // MARK: - Start New Doudizhu Game (Host Deals 54 Cards & Syncs to Connected Peers)
    func startNewRound() {
        let inMultiplayerRoom = isHostingRoom || isOnlineConnected || !connectedPeerNames.isEmpty || orderedRoomPeers.count > 1
        if inMultiplayerRoom && !isRoomAuthority {
            statusBanner = "⏳ 只有1号房主可以开启下一局，请等待房主发牌..."
            return
        }
        aiTurnWorkItem?.cancel()
        if !inMultiplayerRoom {
            isRoomAuthority = true
            mySeatIndex = 0
        }
        if phase == .roundOver {
            if totalRounds > 0 && currentRound >= totalRounds {
                currentRound = 1
                for i in 0..<seats.count { seats[i].score = 1000 }
            } else {
                currentRound += 1
            }
        }
        // Always rebuild seats from orderedRoomPeers so human players in the room never get stuck as AI on Round 2+!
        rebuildLobbySeats()
        if mySeatIndex < 0 || mySeatIndex >= seats.count { mySeatIndex = 0 }
        
        // Build 54-card deck
        var deck: [DoudizhuCard] = []
        let suits: [DoudizhuSuit] = [.spade, .heart, .club, .diamond]
        for r in 3...15 {
            for s in suits {
                deck.append(DoudizhuCard(id: "\(s.rawValue)_\(r)", rank: r, suit: s))
            }
        }
        deck.append(DoudizhuCard(id: "joker_16", rank: 16, suit: .joker))
        deck.append(DoudizhuCard(id: "joker_17", rank: 17, suit: .joker))
        deck.shuffle()
        
        let h0 = Array(deck[0..<17]).sorted { $0.rank > $1.rank }
        let h1 = Array(deck[17..<34]).sorted { $0.rank > $1.rank }
        let h2 = Array(deck[34..<51]).sorted { $0.rank > $1.rank }
        let bottom3 = Array(deck[51..<54]).sorted { $0.rank > $1.rank }
        
        for i in 0..<3 {
            seats[i].isLandlord = false
            seats[i].lastActionText = ""
            seats[i].lastPlayedCards = []
        }
        seats[0].hand = h0
        seats[1].hand = h1
        seats[2].hand = h2
        holeCards = bottom3
        selectedCardIds.removeAll()
        
        phase = .bidding
        currentTurnSeat = Int.random(in: 0...2)
        highestBid = 0
        highestBidderSeat = -1
        bidsCount = 0
        multiplier = 1
        lastValidHand = nil
        lastPlaySeat = -1
        winnerSeat = nil
        hintIndex = 0
        
        statusBanner = "🃏 发牌完成！轮到 [\(seats[currentTurnSeat].name)] 叫地主"
        AudioPlayerManager.shared.playMascotVoice(for: characterFilter(for: seats[currentTurnSeat].characterId))
        
        startTurnCountdownTimer()
        broadcastFullState()
        scheduleAITurnIfNeeded()
    }
    
    private func startTurnCountdownTimer() {
        turnCountdownTimer?.invalidate()
        turnRemainingSeconds = turnTimeLimit > 0 ? turnTimeLimit : 25
        let t = Timer(timeInterval: 1.0, repeats: true) { [weak self] _ in
            guard let self = self else { return }
            guard self.phase == .bidding || self.phase == .playing else { return }
            guard self.turnTimeLimit > 0 else { return }
            if self.turnRemainingSeconds > 0 {
                self.turnRemainingSeconds -= 1
                if self.isRoomAuthority && self.currentTurnSeat >= 0 && self.currentTurnSeat < self.seats.count && self.seats[self.currentTurnSeat].isAI && self.aiTurnWorkItem == nil {
                    self.scheduleAITurnIfNeeded()
                }
            } else {
                if !self.isRoomAuthority, let firstHuman = self.seats.firstIndex(where: { !$0.isAI }), firstHuman == self.mySeatIndex {
                    self.isRoomAuthority = true
                }
                if self.isRoomAuthority {
                    self.turnRemainingSeconds = self.turnTimeLimit > 0 ? self.turnTimeLimit : 25
                    self.handleTurnTimeout()
                } else if self.currentTurnSeat == self.mySeatIndex {
                    self.turnRemainingSeconds = self.turnTimeLimit > 0 ? self.turnTimeLimit : 25
                    if self.phase == .bidding {
                        self.submitBid(0)
                    } else if self.phase == .playing {
                        if self.lastPlaySeat == self.mySeatIndex || self.lastPlaySeat == -1 {
                            if let c = self.seats[self.mySeatIndex].hand.last {
                                self.selectedCardIds = [c.id]
                                self.playSelectedCards()
                            }
                        } else {
                            self.passTurn()
                        }
                    }
                }
            }
        }
        RunLoop.main.add(t, forMode: .common)
        turnCountdownTimer = t
    }
    
    private func handleTurnTimeout() {
        let actor = currentTurnSeat
        guard actor >= 0 && actor < seats.count else { return }
        aiTurnWorkItem?.cancel()
        aiTurnWorkItem = nil
        if phase == .bidding {
            submitBid(0, fromSeat: actor)
        } else if phase == .playing {
            let effectiveTarget = (lastPlaySeat == actor || lastPlaySeat == -1) ? nil : lastValidHand
            if seats[actor].isAI, let hint = DoudizhuHandEvaluator.findHints(in: seats[actor].hand, beating: effectiveTarget).first {
                let ev = DoudizhuHandEvaluator.evaluate(hint)
                if ev.category != .invalid {
                    executePlayCards(hint, Evaluated: ev, fromSeat: actor)
                    return
                }
            }
            if lastPlaySeat == actor || lastPlaySeat == -1 {
                if let firstCard = seats[actor].hand.last {
                    let ev = DoudizhuHandEvaluator.evaluate([firstCard])
                    executePlayCards([firstCard], Evaluated: ev, fromSeat: actor)
                }
            } else {
                passTurn(fromSeat: actor)
            }
        }
    }
    
    // MARK: - Bidding Phase (叫地主: 0=不叫, 1=1分, 2=2分, 3=3分)
    func submitBid(_ score: Int, fromSeat seatIdx: Int? = nil) {
        let actor = seatIdx ?? mySeatIndex
        guard phase == .bidding, currentTurnSeat == actor else { return }
        
        if !isRoomAuthority && actor == mySeatIndex {
            // Client sends bid action to Host
            let pkt = DoudizhuNetPacket(
                kind: .bidAction,
                roomCode: roomCode,
                senderPeerName: myPeerID.displayName,
                senderCharId: myCharacter.charId,
                bidScore: score
            )
            sendPacketToPeers(pkt)
            return
        }
        
        let bidLabel = score == 0 ? "不叫" : "叫 \(score) 分"
        seats[actor].lastActionText = bidLabel
        if score > highestBid {
            highestBid = score
            highestBidderSeat = actor
            multiplier = max(1, score)
        }
        bidsCount += 1
        
        AudioPlayerManager.shared.playMascotVoice(for: characterFilter(for: seats[actor].characterId))
        
        if score == 3 || bidsCount >= 3 {
            let landlordIdx = highestBidderSeat >= 0 ? highestBidderSeat : 0
            finalizeLandlord(seatIdx: landlordIdx)
        } else {
            currentTurnSeat = (currentTurnSeat + 1) % 3
            turnRemainingSeconds = turnTimeLimit
            statusBanner = "轮到 [\(seats[currentTurnSeat].name)] 叫分 (当前最高: \(highestBid)分)"
            broadcastFullState()
            scheduleAITurnIfNeeded()
        }
    }
    
    private func finalizeLandlord(seatIdx: Int) {
        for i in 0..<3 {
            seats[i].isLandlord = (i == seatIdx)
            seats[i].lastActionText = (i == seatIdx) ? "🎩 地主" : "🌾 农民"
        }
        seats[seatIdx].hand.append(contentsOf: holeCards)
        seats[seatIdx].hand.sort { $0.rank > $1.rank }
        
        phase = .playing
        currentTurnSeat = seatIdx
        turnRemainingSeconds = turnTimeLimit
        lastValidHand = nil
        lastPlaySeat = seatIdx
        statusBanner = "🎩 [\(seats[seatIdx].name)] 成为地主！获得三张底牌并优先出牌"
        
        broadcastFullState()
        scheduleAITurnIfNeeded()
    }
    
    // MARK: - Playing Cards & Passing
    func toggleSelectCard(_ card: DoudizhuCard) {
        if selectedCardIds.contains(card.id) {
            selectedCardIds.remove(card.id)
        } else {
            selectedCardIds.insert(card.id)
        }
    }
    
    func clearSelectedCards() {
        selectedCardIds.removeAll()
    }
    
    func triggerSmartHint() {
        guard mySeatIndex < seats.count else { return }
        let myHand = seats[mySeatIndex].hand
        let effectiveTarget = (lastPlaySeat == mySeatIndex || lastPlaySeat == -1) ? nil : lastValidHand
        let candidates = DoudizhuHandEvaluator.findHints(in: myHand, beating: effectiveTarget)
        guard !candidates.isEmpty else {
            statusBanner = "💡 没有大过上家的牌，建议点击「不出」"
            return
        }
        let chosen = candidates[hintIndex % candidates.count]
        hintIndex += 1
        selectedCardIds = Set(chosen.map { $0.id })
    }
    
    func playSelectedCards() {
        guard phase == .playing, currentTurnSeat == mySeatIndex else { return }
        let myHand = seats[mySeatIndex].hand
        let chosen = myHand.filter { selectedCardIds.contains($0.id) }
        guard !chosen.isEmpty else {
            statusBanner = "⚠️ 请先点选要出的扑克牌！"
            return
        }
        
        let evaluated = DoudizhuHandEvaluator.evaluate(chosen)
        guard evaluated.category != .invalid else {
            statusBanner = "⚠️ 所选牌型不符合斗地主规则（支持单张/对子/三带一/三带二/顺子/连对/飞机/炸弹/王炸）"
            return
        }
        
        let effectiveTarget = (lastPlaySeat == mySeatIndex || lastPlaySeat == -1) ? nil : lastValidHand
        guard evaluated.canBeat(effectiveTarget) else {
            statusBanner = "⚠️ 所选牌型无法大过上家的 [\(effectiveTarget?.category.localizedName(AudioPlayerManager.shared.language) ?? "")]！"
            return
        }
        
        if !isRoomAuthority {
            let pkt = DoudizhuNetPacket(
                kind: .playCardsAction,
                roomCode: roomCode,
                senderPeerName: myPeerID.displayName,
                senderCharId: myCharacter.charId,
                playedCards: chosen
            )
            sendPacketToPeers(pkt)
            selectedCardIds.removeAll()
            return
        }
        
        executePlayCards(chosen, Evaluated: evaluated, fromSeat: mySeatIndex)
        selectedCardIds.removeAll()
    }
    
    func passTurn(fromSeat seatIdx: Int? = nil) {
        let actor = seatIdx ?? mySeatIndex
        guard phase == .playing, currentTurnSeat == actor else { return }
        if lastPlaySeat == actor || lastPlaySeat == -1 {
            statusBanner = "⚠️ 当前由您自由领出，不能选择「不出」！"
            return
        }
        
        if !isRoomAuthority && actor == mySeatIndex {
            let pkt = DoudizhuNetPacket(
                kind: .passAction,
                roomCode: roomCode,
                senderPeerName: myPeerID.displayName,
                senderCharId: myCharacter.charId
            )
            sendPacketToPeers(pkt)
            return
        }
        
        seats[actor].lastActionText = "不出"
        seats[actor].lastPlayedCards = []
        currentTurnSeat = (currentTurnSeat + 1) % 3
        turnRemainingSeconds = turnTimeLimit
        if currentTurnSeat == lastPlaySeat {
            // Everyone else passed -> new free lead!
            lastValidHand = nil
        }
        statusBanner = "[\(seats[actor].name)] 选择不出，轮到 [\(seats[currentTurnSeat].name)] 出牌"
        broadcastFullState()
        scheduleAITurnIfNeeded()
    }
    
    private func executePlayCards(_ cards: [DoudizhuCard], Evaluated eval: EvaluatedDoudizhuHand, fromSeat actor: Int) {
        let playedIds = Set(cards.map { $0.id })
        seats[actor].hand.removeAll { playedIds.contains($0.id) }
        seats[actor].lastPlayedCards = cards.sorted { $0.rank > $1.rank }
        seats[actor].lastActionText = eval.category.localizedName(AudioPlayerManager.shared.language)
        
        if eval.category == .bomb || eval.category == .rocket {
            let nextM = multiplier * 2
            multiplier = maxMultiplier > 0 ? min(nextM, maxMultiplier) : nextM
        }
        
        lastValidHand = eval
        lastPlaySeat = actor
        hintIndex = 0
        
        AudioPlayerManager.shared.playMascotVoice(for: characterFilter(for: seats[actor].characterId))
        
        // Check win condition
        if seats[actor].hand.isEmpty {
            winnerSeat = actor
            phase = .roundOver
            let landlordWon = seats[actor].isLandlord
            let delta = baseScore * multiplier
            for i in 0..<3 {
                if seats[i].isLandlord {
                    seats[i].score += landlordWon ? (delta * 2) : (-delta * 2)
                } else {
                    seats[i].score += landlordWon ? (-delta) : delta
                }
            }
            let roleTitle = landlordWon ? "🎩 地主获胜！" : "🌾 农民联手获胜！"
            statusBanner = "🎉 牌局结束：[\(seats[actor].name)] 出完手牌，\(roleTitle) (倍数 x\(multiplier))"
            let mySideWon = (mySeatIndex < seats.count) ? (seats[mySeatIndex].isLandlord == landlordWon) : (actor == mySeatIndex)
            let myDelta = (mySeatIndex < seats.count && seats[mySeatIndex].isLandlord) ? (delta * 2) : delta
            KOnLocalLLMManager.shared.recordGameOutcome(gameName: "放课后斗地主", didWin: mySideWon, detail: "\(roleTitle) 倍数 x\(multiplier)，\(mySideWon ? "+" : "-")\(myDelta)分")
            broadcastFullState()
            return
        }
        
        currentTurnSeat = (currentTurnSeat + 1) % 3
        turnRemainingSeconds = turnTimeLimit
        statusBanner = "[\(seats[actor].name)] 打出 \(eval.category.localizedName(AudioPlayerManager.shared.language))，轮到 [\(seats[currentTurnSeat].name)]"
        broadcastFullState()
        scheduleAITurnIfNeeded()
    }
    
    // MARK: - Intelligent K-ON! AI Decision Engine
    private func scheduleAITurnIfNeeded() {
        aiTurnWorkItem?.cancel()
        if !isRoomAuthority { return }
        guard currentTurnSeat >= 0 && currentTurnSeat < seats.count else { return }
        let activePlayer = seats[currentTurnSeat]
        guard activePlayer.isAI else { return }
        
        let seatToAct = currentTurnSeat
        let work = DispatchWorkItem { [weak self] in
            guard let self = self else { return }
            self.aiTurnWorkItem = nil
            guard self.currentTurnSeat == seatToAct, seatToAct < self.seats.count else { return }
            let activePlayer = self.seats[seatToAct]
            guard activePlayer.isAI else { return }
            if self.phase == .bidding {
                let highCards = activePlayer.hand.filter { $0.rank >= 15 }.count
                let desiredBid: Int
                if highCards >= 4 && self.highestBid < 3 {
                    desiredBid = 3
                } else if highCards >= 3 && self.highestBid < 2 {
                    desiredBid = 2
                } else if highCards >= 2 && self.highestBid < 1 {
                    desiredBid = 1
                } else {
                    desiredBid = 0
                }
                self.submitBid(desiredBid, fromSeat: seatToAct)
            } else if self.phase == .playing {
                let effectiveTarget = (self.lastPlaySeat == seatToAct || self.lastPlaySeat == -1) ? nil : self.lastValidHand
                let hints = DoudizhuHandEvaluator.findHints(in: activePlayer.hand, beating: effectiveTarget)
                if let chosen = hints.first {
                    // Teammate cooperation: if another Farmer played a big hand (>= Q) and AI is also a Farmer, don't waste a bomb on teammate!
                    if effectiveTarget != nil,
                       self.lastPlaySeat >= 0,
                       !activePlayer.isLandlord,
                       !self.seats[self.lastPlaySeat].isLandlord {
                        let ev = DoudizhuHandEvaluator.evaluate(chosen)
                        if ev.category == .bomb || ev.category == .rocket || (effectiveTarget?.primaryRank ?? 0) >= 13 {
                            self.passTurn(fromSeat: seatToAct)
                            return
                        }
                    }
                    let ev = DoudizhuHandEvaluator.evaluate(chosen)
                    self.executePlayCards(chosen, Evaluated: ev, fromSeat: seatToAct)
                } else {
                    self.passTurn(fromSeat: seatToAct)
                }
            }
        }
        self.aiTurnWorkItem = work
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.85, execute: work)
    }
    
    // MARK: - Remaining Card Counter (记牌器)
    func remainingCount(forRank rank: Int) -> Int {
        guard mySeatIndex < seats.count else { return 0 }
        // Count cards still unseen (in other players' hands + unrevealed hole cards)
        var total = 0
        for (idx, s) in seats.enumerated() {
            if idx != mySeatIndex {
                total += s.hand.filter { $0.rank == rank }.count
            }
        }
        if phase == .bidding {
            total += holeCards.filter { $0.rank == rank }.count
        }
        return total
    }
    
    // MARK: - Network Packet Sync
    private func broadcastFullState() {
        guard isRoomAuthority else { return }
        let pkt = DoudizhuNetPacket(
            kind: .stateSync,
            roomCode: roomCode,
            senderPeerName: myPeerID.displayName,
            senderCharId: myCharacter.charId,
            hostPeerName: myPeerID.displayName,
            roomPeers: orderedRoomPeers,
            seats: seats,
            holeCards: holeCards,
            phase: phase,
            currentTurnSeat: currentTurnSeat,
            highestBid: highestBid,
            highestBidderSeat: highestBidderSeat,
            multiplier: multiplier,
            lastValidHand: lastValidHand,
            lastPlaySeat: lastPlaySeat,
            winnerSeat: winnerSeat,
            statusBanner: statusBanner,
            totalRounds: totalRounds,
            currentRound: currentRound,
            baseScore: baseScore,
            maxMultiplier: maxMultiplier,
            turnTimeLimit: turnTimeLimit,
            allowCardCounter: allowCardCounter,
            aiDifficulty: aiDifficulty,
            coinAnte: isOnlineConnected ? KOnQQCoinBinder.shared.coinAnte : nil
        )
        sendPacketToPeers(pkt)
    }
    
    private func sendPacketToPeers(_ packet: DoudizhuNetPacket) {
        guard let data = try? JSONEncoder().encode(packet) else { return }
        if let session = mcSession, !session.connectedPeers.isEmpty {
            try? session.send(data, toPeers: session.connectedPeers, with: .reliable)
        }
        if let ws = webSocketTask {
            ws.send(.data(data)) { _ in }
        }
    }
    
    private func promoteAuthorityIfNeededAndResumeAI() {
        let prevAuth = isRoomAuthority
        if let firstPeer = orderedRoomPeers.first {
            isRoomAuthority = (firstPeer.name == myPeerID.displayName)
        } else if let firstHumanIdx = seats.firstIndex(where: { !$0.isAI }) {
            isRoomAuthority = (firstHumanIdx == mySeatIndex)
        } else {
            isRoomAuthority = true
        }
        if isRoomAuthority {
            if !prevAuth {
                statusBanner = "👑 原房主已离开，您已自动接任 [\(roomCode)] 房主！"
            }
            if phase == .bidding || phase == .playing {
                if turnCountdownTimer == nil {
                    startTurnCountdownTimer()
                }
                broadcastFullState()
                scheduleAITurnIfNeeded()
            } else if phase == .lobby {
                rebuildLobbySeats()
                broadcastFullState()
            }
        }
    }

    private func handleIncomingPacket(_ pkt: DoudizhuNetPacket) {
        let myCode = roomCode.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !myCode.isEmpty && pkt.roomCode == myCode else { return }
        switch pkt.kind {
        case .roomFull:
            let msg = pkt.statusBanner ?? "⚠️ 房间 [\(myCode)] 人数已满 (3/3人)，无法进入！请更换其他房号"
            stopNetworking()
            phase = .lobby
            statusBanner = msg
            
        case .roomRoster:
            guard let peers = pkt.roomPeers, !peers.isEmpty else { return }
            orderedRoomPeers = peers
            for rp in peers {
                peerCharIds[rp.name] = rp.charId
            }
            connectedPeerNames = peers.map { $0.name }.filter { $0 != myPeerID.displayName }
            let prevAuth = isRoomAuthority
            isRoomAuthority = (peers.first?.name == myPeerID.displayName)
            
            if phase == .lobby || phase == .roundOver {
                if phase == .lobby {
                    rebuildLobbySeats()
                }
                if isRoomAuthority {
                    statusBanner = "👑 您是房间 [\(myCode)] 的房主 (当前 \(peers.count)/3 人)，可设置规则并开始牌局"
                    if !prevAuth || peers.count > 1 {
                        broadcastFullState()
                    }
                } else {
                    let hostDisp = cleanPeerLabel(peers.first?.displayName ?? peers.first?.name ?? "1号玩家")
                    statusBanner = "✅ 已进入房间 [\(myCode)] (当前 \(peers.count)/3 人)，房主: [\(hostDisp)]"
                }
            } else {
                let activeNames = Set(peers.map { $0.name })
                var anyTurnedAI = false
                for i in 0..<seats.count where !seats[i].isAI && !activeNames.contains(seats[i].peerDisplayName) {
                    seats[i].isAI = true
                    seats[i].name = "\(characterFilter(for: seats[i].characterId).displayName(AudioPlayerManager.shared.language)) (AI接管)"
                    anyTurnedAI = true
                }
                if anyTurnedAI || (!prevAuth && isRoomAuthority) {
                    promoteAuthorityIfNeededAndResumeAI()
                }
            }
            
        case .leaveRoom:
            let pName = pkt.senderPeerName
            let cleanLeft = cleanPeerLabel(pName)
            connectedPeerNames.removeAll { $0 == pName }
            orderedRoomPeers.removeAll { $0.name == pName }
            peerCharIds.removeValue(forKey: pName)
            if phase == .lobby || phase == .roundOver {
                promoteAuthorityIfNeededAndResumeAI()
                if phase == .lobby {
                    rebuildLobbySeats()
                }
                statusBanner = "ℹ️ 玩家 [\(cleanLeft)] 已离开房间 \(myCode)\(isRoomAuthority ? "，您当前为房主" : "")"
            } else {
                for i in 0..<seats.count where seats[i].peerDisplayName == pName {
                    seats[i].isAI = true
                    let orig = cleanPeerLabel(seats[i].name)
                    if !orig.contains("AI接管") { seats[i].name = "\(orig) (AI接管)" }
                    seats[i].lastActionText = "🤖 AI接管"
                }
                statusBanner = "🤖 [\(cleanLeft)] 已退出，由 AI 自动接管出牌！"
                promoteAuthorityIfNeededAndResumeAI()
                if isRoomAuthority {
                    broadcastFullState()
                    scheduleAITurnIfNeeded()
                }
                promoteAuthorityIfNeededAndResumeAI()
                statusBanner = "ℹ️ 玩家 [\(cleanLeft)] 已离开，由轻音AI自动接管\(isRoomAuthority ? "（您已接任房主）" : "")"
                promoteAuthorityIfNeededAndResumeAI()
            }
            
        case .joinRequest:
            let pName = pkt.senderPeerName
            guard pName != myPeerID.displayName else { return }
            if isHostingRoom && isRoomAuthority {
                let alreadyIn = orderedRoomPeers.contains(where: { $0.name == pName })
                if !alreadyIn && orderedRoomPeers.count >= 3 {
                    let fullPkt = DoudizhuNetPacket(
                        kind: .roomFull,
                        roomCode: myCode,
                        senderPeerName: myPeerID.displayName,
                        senderCharId: myCharacter.charId,
                        statusBanner: "⚠️ 房间 [\(myCode)] 人数已满 (3/3人)，无法加入！"
                    )
                    sendPacketToPeers(fullPkt)
                    return
                }
                peerCharIds[pName] = pkt.senderCharId
                if !alreadyIn {
                    orderedRoomPeers.append(DoudizhuRoomPeer(name: pName, charId: pkt.senderCharId, displayName: pName))
                }
                if !connectedPeerNames.contains(pName) {
                    connectedPeerNames.append(pName)
                }
                rebuildLobbySeats()
                statusBanner = "🎉 好友 [\(pName)] 已加入房间 \(myCode)！(当前 \(orderedRoomPeers.count)/3 人)"
                let rosterPkt = DoudizhuNetPacket(
                    kind: .roomRoster,
                    roomCode: myCode,
                    senderPeerName: myPeerID.displayName,
                    senderCharId: myCharacter.charId,
                    hostPeerName: myPeerID.displayName,
                    roomPeers: orderedRoomPeers
                )
                sendPacketToPeers(rosterPkt)
                broadcastFullState()
            }
            
        case .stateSync:
            guard pkt.senderPeerName != myPeerID.displayName else { return }
            if let rPeers = pkt.roomPeers, !rPeers.isEmpty {
                self.orderedRoomPeers = rPeers
                self.connectedPeerNames = rPeers.map { $0.name }.filter { $0 != self.myPeerID.displayName }
            }
            if let hName = pkt.hostPeerName, !hName.isEmpty {
                self.isRoomAuthority = (hName == self.myPeerID.displayName)
            } else {
                self.isRoomAuthority = false
            }
            if !self.isRoomAuthority {
                self.aiTurnWorkItem?.cancel()
                self.aiTurnWorkItem = nil
            }
            if let s = pkt.seats {
                self.seats = s
                if let exactIdx = s.firstIndex(where: { $0.peerDisplayName == self.myPeerID.displayName }) {
                    self.mySeatIndex = exactIdx
                } else if !self.isRoomAuthority,
                          let guestIdx = s.indices.dropFirst().first(where: { !s[$0].isAI && self.cleanPeerLabel(s[$0].peerDisplayName) == self.cleanNickname() }) {
                    self.mySeatIndex = guestIdx
                } else if let rosterIdx = self.orderedRoomPeers.firstIndex(where: { $0.name == self.myPeerID.displayName }), rosterIdx < s.count {
                    self.mySeatIndex = rosterIdx
                }
            }
            if let h = pkt.holeCards { self.holeCards = h }
            if let tr = pkt.totalRounds { self.totalRounds = tr }
            if let cr = pkt.currentRound { self.currentRound = cr }
            if let bs = pkt.baseScore { self.baseScore = bs }
            if let mm = pkt.maxMultiplier { self.maxMultiplier = mm }
            if let ttl = pkt.turnTimeLimit { self.turnTimeLimit = ttl }
            if let acc = pkt.allowCardCounter { self.allowCardCounter = acc }
            if let aid = pkt.aiDifficulty { self.aiDifficulty = aid }
            if let p = pkt.phase {
                if p == .bidding && self.phase != .bidding {
                    self.selectedCardIds.removeAll()
                    self.hintIndex = 0
                }
                self.phase = p
                if p == .bidding || p == .playing {
                    self.startTurnCountdownTimer()
                }
            }
            if let t = pkt.currentTurnSeat {
                self.currentTurnSeat = t
                self.turnRemainingSeconds = self.turnTimeLimit > 0 ? self.turnTimeLimit : 25
            }
            if let hb = pkt.highestBid { self.highestBid = hb }
            if let hbs = pkt.highestBidderSeat { self.highestBidderSeat = hbs }
            if let m = pkt.multiplier { self.multiplier = m }
            self.lastValidHand = pkt.lastValidHand
            if let lp = pkt.lastPlaySeat { self.lastPlaySeat = lp }
            self.winnerSeat = pkt.winnerSeat
            if let sb = pkt.statusBanner { self.statusBanner = sb }
            
        case .bidAction:
            if isRoomAuthority, let score = pkt.bidScore,
               let seatIdx = seats.firstIndex(where: { $0.peerDisplayName == pkt.senderPeerName }) {
                submitBid(score, fromSeat: seatIdx)
            }
            
        case .playCardsAction:
            if isRoomAuthority, let cards = pkt.playedCards,
               let seatIdx = seats.firstIndex(where: { $0.peerDisplayName == pkt.senderPeerName }) {
                let ev = DoudizhuHandEvaluator.evaluate(cards)
                if ev.category != .invalid {
                    executePlayCards(cards, Evaluated: ev, fromSeat: seatIdx)
                }
            }
            
        case .passAction:
            if isRoomAuthority,
               let seatIdx = seats.firstIndex(where: { $0.peerDisplayName == pkt.senderPeerName }) {
                passTurn(fromSeat: seatIdx)
            }
            
        default:
            break
        }
    }
    
    // MARK: - MCSessionDelegate & MCNearbyService Delegates
    func session(_ session: MCSession, peer peerID: MCPeerID, didChange state: MCSessionState) {
        DispatchQueue.main.async {
            if state == .connected {
                if !self.connectedPeerNames.contains(peerID.displayName) {
                    self.connectedPeerNames.append(peerID.displayName)
                }
                if self.isHostingRoom {
                    if !self.orderedRoomPeers.contains(where: { $0.name == peerID.displayName }) && self.orderedRoomPeers.count < 3 {
                        self.orderedRoomPeers.append(DoudizhuRoomPeer(name: peerID.displayName, charId: self.peerCharIds[peerID.displayName] ?? 2, displayName: peerID.displayName))
                    }
                    self.rebuildLobbySeats()
                    self.statusBanner = "✅ 玩家 [\(peerID.displayName)] 已连接！(当前真机玩家: \(self.orderedRoomPeers.count)/3 人)"
                    let rosterPkt = DoudizhuNetPacket(
                        kind: .roomRoster,
                        roomCode: self.roomCode,
                        senderPeerName: self.myPeerID.displayName,
                        senderCharId: self.myCharacter.charId,
                        hostPeerName: self.myPeerID.displayName,
                        roomPeers: self.orderedRoomPeers
                    )
                    self.sendPacketToPeers(rosterPkt)
                    self.broadcastFullState()
                } else {
                    self.statusBanner = "✅ 已成功连入房主 [\(peerID.displayName)] 的面对面牌桌！"
                    self.sendJoinRequestToRoom()
                }
            } else if state == .notConnected {
                self.connectedPeerNames.removeAll { $0 == peerID.displayName }
                self.orderedRoomPeers.removeAll { $0.name == peerID.displayName }
                self.peerCharIds.removeValue(forKey: peerID.displayName)
                if self.phase == .lobby {
                    self.promoteAuthorityIfNeededAndResumeAI()
                    self.rebuildLobbySeats()
                    self.statusBanner = "ℹ️ 与 [\(peerID.displayName)] 的连接已断开"
                } else {
                    for i in 0..<self.seats.count where self.seats[i].peerDisplayName == peerID.displayName {
                        self.seats[i].isAI = true
                        self.seats[i].name = "\(self.characterFilter(for: self.seats[i].characterId).displayName(AudioPlayerManager.shared.language)) (AI接管)"
                    }
                    self.statusBanner = "ℹ️ 玩家 [\(peerID.displayName)] 已离开，由轻音AI自动接管继续对局"
                    self.promoteAuthorityIfNeededAndResumeAI()
                }
            }
        }
    }
    
    func session(_ session: MCSession, didReceive data: Data, fromPeer peerID: MCPeerID) {
        guard let pkt = try? JSONDecoder().decode(DoudizhuNetPacket.self, from: data) else { return }
        DispatchQueue.main.async {
            self.handleIncomingPacket(pkt)
        }
    }
    
    func session(_ session: MCSession, didReceive stream: InputStream, withName streamName: String, fromPeer peerID: MCPeerID) {}
    func session(_ session: MCSession, didStartReceivingResourceWithName resourceName: String, fromPeer peerID: MCPeerID, with progress: Progress) {}
    func session(_ session: MCSession, didFinishReceivingResourceWithName resourceName: String, fromPeer peerID: MCPeerID, at localURL: URL?, withError error: Error?) {}
    
    func advertiser(_ advertiser: MCNearbyServiceAdvertiser, didReceiveInvitationFromPeer peerID: MCPeerID, withContext context: Data?, invitationHandler: @escaping (Bool, MCSession?) -> Void) {
        // Automatically accept nearby friends into the room if < 2 peers connected
        let canAccept = (mcSession?.connectedPeers.count ?? 0) < 2
        invitationHandler(canAccept, mcSession)
    }
    
    func browser(_ browser: MCNearbyServiceBrowser, foundPeer peerID: MCPeerID, withDiscoveryInfo info: [String : String]?) {
        let code = (info?["code"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let myCode = roomCode.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !code.isEmpty && code == myCode else { return }
        let host = info?["host"] ?? peerID.displayName
        let charId = Int(info?["char"] ?? "1") ?? 1
        let room = DoudizhuDiscoveredRoom(
            id: "\(peerID.displayName)_\(code)",
            roomCode: code,
            hostName: host,
            hostCharId: charId,
            peerID: peerID
        )
        DispatchQueue.main.async {
            if !self.discoveredRooms.contains(where: { $0.id == room.id }) {
                self.discoveredRooms.append(room)
                self.statusBanner = "🎉 发现附近房间：房主 [\(host)] (房号 \(code))，点击即可加入！"
            }
        }
    }
    
    func browser(_ browser: MCNearbyServiceBrowser, lostPeer peerID: MCPeerID) {
        DispatchQueue.main.async {
            self.discoveredRooms.removeAll { $0.peerID == peerID }
        }
    }
}

// MARK: - Guangdong Hongzhong Laizi Mahjong Engine (广东红中麻将 · 红中赖子 · 不能吃 · 可碰杠)
enum MahjongSuit: String, Codable, CaseIterable {
    case wan = "W"
    case tiao = "T"
    case tong = "D"
    case honor = "H" // 1=东, 2=南, 3=西, 4=北, 5=发, 6=白
    case zhong = "Z"

    var chineseUnit: String {
        switch self {
        case .wan: return "万"
        case .tiao: return "条"
        case .tong: return "筒"
        case .honor: return "字"
        case .zhong: return "中"
        }
    }

    var sortOrder: Int {
        switch self {
        case .zhong: return 0
        case .wan: return 1
        case .tiao: return 2
        case .tong: return 3
        case .honor: return 4
        }
    }
}

struct MahjongTile: Identifiable, Codable, Equatable, Hashable {
    let id: String
    let suit: MahjongSuit
    let rank: Int // 1..9 for W/T/D, 1..6 for honor (东南西北发白), 0 for 红中

    var isLaizi: Bool { suit == .zhong }

    var typeKey: Int {
        switch suit {
        case .wan: return rank - 1          // 0..8
        case .tiao: return 9 + (rank - 1)   // 9..17
        case .tong: return 18 + (rank - 1)  // 18..26
        case .honor: return 27 + (rank - 1) // 27..32 (东南西北发白)
        case .zhong: return 33
        }
    }

    var shortLabel: String {
        if suit == .zhong { return "中" }
        if suit == .honor {
            let honors = ["", "东", "南", "西", "北", "发", "白"]
            return (rank >= 1 && rank <= 6) ? honors[rank] : "字"
        }
        let nums = ["", "一", "二", "三", "四", "五", "六", "七", "八", "九"]
        if suit == .wan, rank >= 1, rank <= 9 { return "\(nums[rank])" }
        return "\(rank)"
    }

    var fullName: String {
        if suit == .zhong { return "红中" }
        if suit == .honor { return shortLabel }
        return "\(rank)\(suit.chineseUnit)"
    }
}

enum MahjongMeldKind: String, Codable {
    case pong = "碰"
    case exposedKong = "明杠"
    case concealedKong = "暗杠"
}

struct MahjongMeld: Identifiable, Codable, Equatable {
    let id: String
    let kind: MahjongMeldKind
    let tile: MahjongTile
}

struct MahjongSeat: Identifiable, Codable {
    let id: Int
    var name: String
    var characterId: Int
    var isAI: Bool
    var peerDisplayName: String
    var hand: [MahjongTile]
    var melds: [MahjongMeld]
    var discards: [MahjongTile]
    var score: Int
    var isDealer: Bool
    var lastActionText: String
}

enum MahjongGamePhase: String, Codable {
    case lobby
    case playing
    case claimWindow
    case roundOver
}

struct MahjongPendingClaim: Codable, Equatable {
    let discarderSeat: Int
    let tile: MahjongTile
    var eligibleHuSeats: [Int]
    var eligibleKongSeats: [Int]
    var eligiblePongSeats: [Int]
    var passedSeats: [Int]

    var waitingSeats: [Int] {
        Array(Set(eligibleHuSeats + eligibleKongSeats + eligiblePongSeats)).filter { !passedSeats.contains($0) }
    }
}

struct MahjongNetPacket: Codable {
    enum Kind: String, Codable {
        case joinRequest
        case leaveRoom
        case roomRoster
        case roomFull
        case stateSync
        case discardAction
        case claimAction
        case selfAction
    }

    let kind: Kind
    let roomCode: String
    let senderPeerName: String
    let senderCharId: Int
    var maxPlayers: Int? = 4
    var gameType: String? = "mahjong"
    var hostPeerName: String? = nil
    var roomPeers: [DoudizhuRoomPeer]? = nil
    var seats: [MahjongSeat]? = nil
    var wallCount: Int? = nil
    var phase: MahjongGamePhase? = nil
    var currentTurnSeat: Int? = nil
    var drawnTileId: String? = nil
    var pendingClaim: MahjongPendingClaim? = nil
    var winnerSeat: Int? = nil
    var winReason: String? = nil
    var horseTiles: [MahjongTile]? = nil
    var hitHorseIds: [String]? = nil
    var statusBanner: String? = nil
    var totalRounds: Int? = nil
    var currentRound: Int? = nil
    var baseScore: Int? = nil
    var turnTimeLimit: Int? = nil
    var tileId: String? = nil
    var actionType: String? = nil // "hu", "kong", "pong", "pass", "selfHu", "selfKong"
    var qqToken: String? = nil
    var coinAnte: Int? = nil
}

enum MahjongEvaluator {
    static func sortHand(_ tiles: [MahjongTile]) -> [MahjongTile] {
        return tiles.sorted {
            if $0.suit.sortOrder != $1.suit.sortOrder {
                return $0.suit.sortOrder < $1.suit.sortOrder
            }
            if $0.rank != $1.rank {
                return $0.rank < $1.rank
            }
            return $0.id < $1.id
        }
    }

    static func canWin(hand: [MahjongTile], meldsCount: Int, extraTile: MahjongTile? = nil) -> Bool {
        var all = hand
        if let ex = extraTile { all.append(ex) }
        guard all.count == 14 - meldsCount * 3 else { return false }

        var counts = [Int](repeating: 0, count: 33)
        var laizi = 0
        for t in all {
            if t.isLaizi {
                laizi += 1
            } else if t.typeKey >= 0 && t.typeKey < 33 {
                counts[t.typeKey] += 1
            }
        }
        // 4 Hongzhong instant win
        if laizi >= 4 { return true }

        // 7 Pairs (Seven Pairs with Hongzhong Laizi) when no melds
        if meldsCount == 0 && all.count == 14 {
            var singles = 0
            for c in counts {
                if c % 2 == 1 { singles += 1 }
            }
            if laizi >= singles && (laizi - singles) % 2 == 0 {
                return true
            }
        }

        // Standard 3n + 2
        // Case A: Use 2 Laizi as pair
        if laizi >= 2 && canFormMelds(&counts, laizi: laizi - 2) {
            return true
        }
        // Case B: Use 1 tile + 1 Laizi as pair
        if laizi >= 1 {
            for i in 0..<33 where counts[i] >= 1 {
                counts[i] -= 1
                let ok = canFormMelds(&counts, laizi: laizi - 1)
                counts[i] += 1
                if ok { return true }
            }
        }
        // Case C: Natural pair
        for i in 0..<33 where counts[i] >= 2 {
            counts[i] -= 2
            let ok = canFormMelds(&counts, laizi: laizi)
            counts[i] += 2
            if ok { return true }
        }
        return false
    }

    private static func canFormMelds(_ counts: inout [Int], laizi: Int) -> Bool {
        guard let firstIdx = counts.firstIndex(where: { $0 > 0 }) else {
            return laizi % 3 == 0
        }
        let c = counts[firstIdx]
        // 1. Try Triplet (AAA) — independent branches so 3/4-of-a-kind can also split with Laizi!
        if c >= 3 {
            counts[firstIdx] -= 3
            let ok = canFormMelds(&counts, laizi: laizi)
            counts[firstIdx] += 3
            if ok { return true }
        }
        if c >= 2 && laizi >= 1 {
            counts[firstIdx] -= 2
            let ok = canFormMelds(&counts, laizi: laizi - 1)
            counts[firstIdx] += 2
            if ok { return true }
        }
        if c >= 1 && laizi >= 2 {
            counts[firstIdx] -= 1
            let ok = canFormMelds(&counts, laizi: laizi - 2)
            counts[firstIdx] += 1
            if ok { return true }
        }

        // 2. Try Sequence (ABC) across ALL 3 windows containing firstIdx (covers Laizi+8+9, Laizi+Laizi+9, etc.)
        if firstIdx < 27 {
            let suitBase = (firstIdx / 9) * 9
            for start in (firstIdx - 2)...firstIdx {
                if start >= suitBase && start + 2 <= suitBase + 8 {
                    var need = 0
                    var used: [Int] = []
                    for k in start...(start + 2) {
                        if counts[k] > 0 {
                            counts[k] -= 1
                            used.append(k)
                        } else {
                            need += 1
                        }
                    }
                    if laizi >= need && canFormMelds(&counts, laizi: laizi - need) {
                        for k in used { counts[k] += 1 }
                        return true
                    }
                    for k in used { counts[k] += 1 }
                }
            }
        }
        return false
    }

    static func readyTiles(hand: [MahjongTile], meldsCount: Int) -> [MahjongTile] {
        guard hand.count == 13 - meldsCount * 3 else { return [] }
        var result: [MahjongTile] = []
        for s in [MahjongSuit.wan, .tiao, .tong] {
            for r in 1...9 {
                let cand = MahjongTile(id: "ting_\(s.rawValue)_\(r)", suit: s, rank: r)
                if canWin(hand: hand, meldsCount: meldsCount, extraTile: cand) {
                    result.append(cand)
                }
            }
        }
        for r in 1...6 {
            let cand = MahjongTile(id: "ting_H_\(r)", suit: .honor, rank: r)
            if canWin(hand: hand, meldsCount: meldsCount, extraTile: cand) {
                result.append(cand)
            }
        }
        let zhong = MahjongTile(id: "ting_Z_0", suit: .zhong, rank: 0)
        if canWin(hand: hand, meldsCount: meldsCount, extraTile: zhong) {
            result.append(zhong)
        }
        return result
    }

    static func bestAIDiscard(hand: [MahjongTile], meldsCount: Int = 0, difficulty: MahjongAIDifficulty = .standard) -> MahjongTile {
        let nonLaizi = hand.filter { !$0.isLaizi }
        guard !nonLaizi.isEmpty else { return hand.last! }
        var counts = [Int](repeating: 0, count: 33)
        for t in nonLaizi where t.typeKey >= 0 && t.typeKey < 33 {
            counts[t.typeKey] += 1
        }
        if difficulty == .master {
            // Evaluate if discarding a tile immediately reaches Tenpai (listening) with maximum winning tiles
            var bestMasterTile: MahjongTile? = nil
            var bestReadyCount = 0
            for (idx, cand) in hand.enumerated() where !cand.isLaizi {
                var rem = hand
                rem.remove(at: idx)
                let ready = readyTiles(hand: rem, meldsCount: meldsCount)
                if ready.count > bestReadyCount {
                    bestReadyCount = ready.count
                    bestMasterTile = cand
                }
            }
            if let bt = bestMasterTile { return bt }
        }
        var bestTile = nonLaizi[0]
        var lowestScore = Int.max
        for t in nonLaizi {
            let k = t.typeKey
            var score = (counts[k] - 1) * (difficulty == .master ? 18 : 14)
            if difficulty == .master && counts[k] >= 3 { score += 16 }
            if k < 27 {
                let pos = k % 9
                if pos > 0 && counts[k - 1] > 0 { score += (difficulty == .master ? 10 : 7) }
                if pos < 8 && counts[k + 1] > 0 { score += (difficulty == .master ? 10 : 7) }
                if pos > 1 && counts[k - 2] > 0 { score += 3 }
                if pos < 7 && counts[k + 2] > 0 { score += 3 }
                if pos == 0 || pos == 8 { score -= (difficulty == .master ? 4 : 2) }
            } else {
                score -= (difficulty == .master ? 5 : 3)
            }
            if difficulty == .casual { score += Int.random(in: -4...6) }
            if score < lowestScore {
                lowestScore = score
                bestTile = t
            }
        }
        return bestTile
    }
}


