    static func localize(_ text: String, _ lang: AppLanguage) -> String {
        switch lang {
        case .zhHans:
            return text
        case .zhHant:
            var out = text
            for (k, v) in hantPhrases {
                out = out.replacingOccurrences(of: k, with: v)
            }
            return out
        case .en:
            var out = text
            for (k, v) in enPhrases {
                out = out.replacingOccurrences(of: k, with: v)
            }
            return out
        }
    }
}

